\begin{theorem}[\cite{Liebeck-affine}]\label{subdegree}
Let $X$ be a finite primitive affine permutation group of rank $3$ and of degree $p^d$, with socle $V$, where $V\cong\mz_p^d$ for some prime $p$, and let $X_0$ be the stabiliser of the zero vector in $V$. Then $X_0$ belongs to one of the following classes $($and, conversely, each of the possibilities listed below does give rise to a rank $3$ affine group$)$.
\begin{itemize}
\item[\rm (A)] Infinite classes. These are
\begin{itemize}
\item[\rm (1)] $X_0\leq \mathrm{\Gamma L}_1(p^d)$: all possibilities for $X_0$ are determined in~\cite[\textsection{3}]{Foulser-Kallaher-solvable-rank-3};
\item[\rm (2)] $X_0$ imprimitive: $X_0$ stabilises a pair $\{V_1,V_2 \}$ of subspaces of $V$ where $V=V_1 \oplus V_2$ and $\dim(V_1)=\dim(V_2)$; moreover, $(X_0)_{V_i}$ is transitive on $V_i\setminus 0$ for $i=1$, $2$ (and hence $ X_0$ is determined by Hering's Theorem~\cite{Hering});
\item[\rm (3)] tensor product case: for some $a$, $q$ with $q^a= p^d$, consider $V$ as a vector space $\GF(q)^a$ of dimension $a$ over $\GF(q)$; then $X_0$ stabilises a decomposition of $\GF(q)^a$ as a tensor product $V_1 \otimes V_2$ where $\dim_{\GF(q)}(V_1)=2$; moreover, $(X_0)^{V_2}\vartriangleright \SL(V_2)$, or $(X_0)^{V_2}=\A_7<\SL_4(2)$ $($and $p=q=2$, $d=a=8)$, or $\dim_{\GF(q)}(V_2)\leq 3$;
\item[\rm (4)] $X_0\vartriangleright \SL_a(q) $ and $p^d=q^{2a}$;
\item[\rm (5)] $X_0\vartriangleright \SL_2(q) $ and $p^d=q^{6}$;
\item[\rm (6)] $X_0\vartriangleright \mathrm{SU}_a(q) $ and $p^d=q^{2a}$;
\item[\rm (7)] $X_0\vartriangleright \Omega^{\pm}_{2a}(q)$ $($and if $q$ is odd, $X_0$ contains an automorphism interchanging the two orbits of $\Omega^{\pm}_{2a}(q)$ on nonsingular $1$-spaces$)$;
\item[\rm (8)] $X_0\vartriangleright \SL_5(q) $ and $p^d=q^{10}$ $($from the action of $\SL_5(q)$ on $\bigwedge^2( \GF(q) ^5)$, the exterior square of $\GF(q)^5)$;

\begin{lemma}\label{lem:class:b-c}
If $G$ satisfies Theorem~{\rm\ref{subdegree}} {\rm(B)--(C)}, then one of the following holds:
\begin{enumerate} [\rm (1)]
\item $\Ga\cong \mathrm{VO}^{-}_6(2)$ or $\overline{\mathrm{VO}^{-}_6(2)}$, arising from the case where $p^d=2^6$ and $G_0\leq \N_{\GL_6(2)}(3^{1+2})$ in {\rm(B)};
\item $\Ga\cong \K_9\square\K_9$ or $\K_9\times\K_9$, arising from the case where $p^d=3^4$ and $G_0\leq \N_{\GL_4(3)}(2^{1+4}) $ in {\rm(B)};
\item $\Ga\cong \mathrm{VO}^{+}_8(2)$ or $\overline{\mathrm{VO}^{+}_8(2)}$, arising from the case where $p^d=2^8$ and $\soc(G_0/\Z(G_0))=\A_9<\mathrm{P\Omega}^{+}_8(2)$ in {\rm(C)}.
\end{enumerate}
\end{lemma}

\begin{proof} Assume that $G$ is of type {\rm(A1)}. Then $G\leq \mathrm{A\Gamma L}_1(p^d)$. Let $\{\alpha, \beta\}$ be an edge of $\Ga$.
Then $|V(\Ga)|=p^d$ and $G_{\alpha\beta}\leq \ZZ_d$. Furthermore, $G_{\a\b}$ is semiregular on $V(\Ga) \setminus \{\alpha, \beta\}$.
From Lemma~\ref{lm:Gab10orbits} it follows that $G_{\alpha\beta}$ has at most $12$ orbits on $V(\Ga) \setminus \{\alpha, \beta\}$.
Therefore, $G_{\alpha\beta}$ has one orbit of length at least $(|V(\Ga)|-2)/12$.
It follows that $|G_{\alpha\beta}|\geq (|V(\Ga)|-2)/12$, which means
\[ p^d-2 \leq 12d.\]
This implies that
\[
p^d\in\{2^i (1\leq i\leq6), 3^j (1\leq j\leq 3), 5^k, 7^k, 11^k (1\leq k\leq 2), 13\}.
\]
Since $\Ga$ has girth $3$ and diameter $2$ by Hypothesis~\ref{hyp}, it follows that $|V(\Ga)|=p^d\geq7$. For all of the remaining possible values of $p^d$, we make use of Magma~\cite{BCP} to construct all primitive rank $3$ subgroups $G$ of $\mathrm{A\Gamma L}_1(p^d)$, and then for each rank $3$ graph arising from $G$, we can further check if $|\Om_i(\Ga)|$ divides $|G|$ for $i=1,2,3,4$, where $\Om_i(\Ga)$ is given in Lemma~\ref{lm:Gaorder}. We find that the only possibility is $p^d=3^2$, and $\Ga\cong \mathrm{Paley}(9)\cong\K_3\square\K_3$. \hfill\qed
\end{proof}

