    \item\label{G4} The bigons associated to the curves $\gamma_1,\gamma_2, \ldots, \gamma_k$ are pairwise distinct.
    \item\label{G5} There exists a point $p\in \gamma_1$ such that $p$ lies on an under-type arc of $\tau$, and there is no bigon directly above $p$.
    \item\label{G6} There exists a point $p\in \gamma_k$ such that $p$ lies on an under-type arc of $\tau$, and there is no bigon directly below $p$.
    \item\label{G7} For each $1\le i\le k-1$, there exists a vertical segment connecting a point $p_1 \in \gamma_i$ to a point $p_2 \in \gamma_{i+1}$ whose interior is disjoint from $\tau$, such that one of the points $p_1,p_2$ lies on an under-type arc of $\tau$ and the other does not lie on $\tau$.
    \item\label{G8} For each under-arc of $D$, there exists a point $p\in \tau$ lying on an under-type arc of $\tau$ arising from that under-arc, such that $p\notin \gamma_i$ for all $1\le i\le k$.
\end{enumerate}

