\section{Proof of Theorems~\ref{th:2sethomo} and \ref{trans-rank-4}}\label{sec6:proof-main-theorems}

\f{\bf Proof of Theorem~\ref{th:2sethomo}.}\ Let $\Ga=(V,E)$ be a $(G,2)$-set-homogeneous graph.
Suppose that $\Ga$ is neither complete nor empty.
If $G$ is imprimitive on the vertex set $V$, then by Lemma~\ref{imp},
$\Ga\cong m\K_b$ or $\K_{m[b]}$ for some positive integers $m$ and $ b$. Then Theorem~\ref{th:2sethomo}~(2) holds.

Assume that $G$ is primitive on $V$. By Lemma~\ref{rank<=5}, $G$ is of rank at most 5.

If $G$ is of rank $3$, then $\Ga$ is $(G,2)$-homogeneous and all candidates for $G$ are listed in \cite{Bannai,Kantor,Liebeck-affine,Liebeck-Saxl}. Then Theorem~\ref{th:2sethomo}~(3)  holds.

If $G$ is of rank $4$, then exactly one of the orbitals is self-paired. By Corollary~\ref{reduction}, $G$ is affine or almost simple. By Theorem~\ref{affine-rank-4}, $G$ is not affine. If $G$ is almost simple, then by Theorem~\ref{rank-4}, $G\cong\PSU_3(3)$ with stabiliser $\PSL_3(2)$, and the subdegrees are $1,7,7$ and $21$. Then $\Ga$ is either the orbital graph of $G$ of order $36$ and of valency $21$, or the complement of this graph. Furthermore, by Magma~\cite{BCP}, $\Aut(\Ga)={\rm P\Gamma U}_3(3)$ is $2$-homogeneous on $\Ga$. This proves part (4) of our theorem.

If $G$ is of rank 5, then none of the non-trivial orbitals of $G$ is self-paired. From Proposition~\ref{AGL_1(p^r)} we obtain part (5) of our theorem. \hfill\qed

\medskip
\f{\bf Proof of Theorem~\ref{trans-rank-4}.}\ Combining Proposition~\ref{th-rank-4}, Lemma~\ref{non-HA-AS}, Theorem~\ref{affine-rank-4} and Theorem~\ref{rank-4}, we obtain the proof of this theorem.\hfill\qed

\section{Finite $3$-set-homogeneous graphs}\label{set:3sethom}

In this section, we shall classify finite $3$-set-homogeneous graphs, and then prove Theorem~\ref{th:3sethomo}.

\subsection{Preliminaries}\label{subsec:3reduce}
\subsubsection{A reduction}
A finite graph $\Ga$ is \emph{strongly regular} with parameters $(v, k, \lambda, \mu)$ if it has $v$ vertices and is regular with valency $k$ where $0<k<v-1$, and if any two adjacent vertices have $\ld=\ld(\Ga)$ common neighbours and any two non-adjacent vertices have $\mu=\mu(\Ga)$ common neighbours. Note that a strongly regular graph is neither complete nor edgeless.

\begin{lem}\label{lem:prim-3ch-is-srg}
Let $\Ga $ be a finite $(G, 3)$-set-homogeneous graph. Then one of the following holds.
\begin{enumerate}
\item[{\rm(1)}] $\Ga \cong\K_n$ or $n\K_1$;

\item[{\rm(2)}]  $\Ga \cong \K_{m[b]}$ or $m\K_b$ where $m,b\geq 2$;

\item [{\rm (3)}]\ $G$ is primitive on $V(\Ga)$ of rank $3$, and $\Ga$ is strongly regular of diameter $2$. Furthermore, if $\Ga$ is not the pentagon, then either $\Ga$ or its complement $\overline{\Ga}$ has girth $3$.
\end{enumerate}
\end{lem}

\proof By \cite[Theorem~1.1 \& Corollary~1.2]{Zhou-EJC2021}, $\Ga$ is $(G,2)$-homogeneous, and then by Theorem~\ref{th:2sethomo}, we conclude that either parts (1) or (2) hold, or $G$ is primitive on $V(\Ga)$ of rank $3$.

Assume that neither part (1) nor part (2) happens. Then $\Ga$ has diameter $2$ and $G$ is arc-transitive on both $\Ga$ and the complement $\overline{\Ga}$ of $\Ga$. This implies that $\Ga$ is strongly regular. The first assertion of the part (3) is proved. If $\Ga$ has valency $2$, then since $\Ga$ has diameter $2$, it follows that $\Ga$ is the pentagon. If $\Ga$ has valency at least $3$, then either $\Ga$ or its complement $\overline{\Ga}$ has girth $3$. \hfill\qed

By Lemma~\ref{lem:prim-3ch-is-srg}, to prove Theorem~\ref{th:3sethomo}, it suffices to classify those $(G,3)$-set-homogeneous graphs $\Ga$ such that $G$ is primitive on $V(\Ga)$ of rank $3$. The following result can be obtained by the fundamental O'Nan-Scott theorem (see \cite[\textsection{1}]{Liebeck-ONan-Scott}).

\begin{theorem}\label{th:rank3groups}
Let $G$ be a primitive group of rank  $3$.
Then one of the following holds:
\begin{itemize}
\item[\rm (1)]  $T\times T\lhd G\leqslant H\wr\S_2$, where $H$ is a $2$-transitive permutation group of degree $n$ and $\soc(H)=T$ is a nonabelian simple group, and $G$ has production action;
\item[\rm (2)]  $G$ is an affine group;
\item[\rm (3)]  $G$ is an almost simple group.
\end{itemize}
\end{theorem}

\begin{lemma}\label{lm:CaseI}
Suppose that $\Ga$ is a finite $(G,3)$-set-homogeneous graph such that $G$ satisfies Theorem~{\rm\ref{th:rank3groups}~(1)}.
Then $\Ga$ is isomorphic to $\K_n\square\K_n$ or its complement $\K_n\times\K_n$, and $\Ga$ is $3$-homogeneous.
\end{lemma}

\proof Without loss of generality, assume that $H$ is a $2$-transitive permutation group on the set $\Del =\{1,2,\dots, n\}$. Then $V(\Ga)=\Del \times\Del $. Take $\a=(1, 1)\in V(\Ga)$. Then the three orbits of $G$ are
\[\Ome_0=\{\a\}, \Ome_1=\{(1, i), (i,1)\mid i\in\Delta\setminus\{1\}\}, \Ome_2=\{(i,j)\mid i, j\in\Del \setminus\{1\}\}.\]
So $\Ga(\a)=\Ome_1$ or $\Ome_2$. It is easy to see that $\Ga\cong\K_n\square\K_n$ or $\K_n\times\K_n$. By \cite[Corollary~1.2]{Cameron-3-hom}, $\Ga$ is $3$-homogeneous.\hfill\qed

By Lemmas~\ref{lem:prim-3ch-is-srg} and \ref{lm:CaseI}, from now on we will adopt the following hypothesis.

\begin{hypothesis}\label{hyp}
Let $\Ga=(V, E)$ be a finite $(G,3)$-set-homogeneous graph satisfying the following:
\begin{itemize}
  \item $G\leq\Aut(\Ga)$ is primitive on $V$ with rank $3$,
  \item $\soc(G)$ is either abelian or nonabelian simple,
  \item $\Ga$ has girth $3$ and diameter $2$.
\end{itemize}
\end{hypothesis}

We will deal with the case where $\soc(G)$ is abelian in Subsection~\ref{subsec:affine}, and the case where $\soc(G)$ is nonabelian simple in Subsection~\ref{subsec:simple}.

\subsubsection{Some useful lemmas}

The first two lemmas concern the arc-stabilisers of $(G,3)$-set-homogeneous graphs. Let $s$ be a positive integer and let $\Sig$ be a graph. For a subgroup $H$ of $\Aut(\Sig)$, we say that $\Sig$ is {\em $(H, s)$-connected-set-homogeneous} if any two isomorphic connected induced subgraphs of $\Sigma$ on at most $s$ vertices are equivalent under $H$. Clearly, every $(H,s)$-set-homogeneous graph is $(H,s)$-connected-set-homogeneous.
For any vertex $v$ of a graph $\Sig$ of diameter at least two, let $\Sig(v)$ be the vertices of $\Sig$ adjacent to $v$, and let $\Sig_2(v)$ be the vertices of $\Sig$ at distance $2$ from $v$.

\begin{lemma}{\rm \cite[Theorem~1.3~(3)-(4)]{Zhou-EJC2021}}\label{rank}
Let $\Sig$ be a finite $(H, 3)$-connected-set-homogeneous non-complete graph of girth $3$ with $H\leq\Aut(\Sig)$. Then for every edge $\{\a, \b\}$ of $\Sig$, we have the following:
\begin{enumerate}
  \item [{\rm (1)}]\ $H_{\a\b}$ has $s$ orbits on $\Sig(\a)\cap \Sig(\b)$ with equal size, where $s=1, 2, 3$ or $6$.
  \item [{\rm (2)}]\ $H_{\a\b}$ has $t$ orbits on $\Sig(\a)-(\Sig(\a)\cap \Sig(\b))\cup\{\b\}$ with equal size, where $t=1$ or $ 2$.
      \end{enumerate}
\end{lemma}

\begin{lemma}\label{lm:Gab10orbits}
Under Hypothesis~{\rm \ref{hyp}}, let $\{\alpha,\beta\}\in E$. Then $G_{\alpha\beta}$ has at most $12$ orbits on $V(\mathit{\Ga})\setminus\{\alpha,\beta\}$.
\end{lemma}

\begin{proof}By Hypothesis~{\rm \ref{hyp}}, $\Ga$ is a $(G,3)$-set-homogeneous graph. Furthermore, $\Ga$ has diameter $2$ and girth $3$. Note that $V(\mathit{\Ga})\setminus\{\alpha,\beta\}$ is partitioned into the following four subsets:
\[\Ga(\a)\cap\Ga(\b), \Ga(\a)\cap\Ga_2(\b), \Ga_2(\a)\cap\Ga(\b), \Ga_2(\a)\cap\Ga_2(\b).\]
Moreover, $G_{\a\b}$ setwise fixes each of the four subsets.

Since every $(G,3)$-set-homogeneous graph is $(G,3)$-connected-set-homogeneous, by Lemma~\ref{rank} $G_{\a\b}$ has at most $6$ orbits on $\Ga(\a)\cap\Ga(\b)$, and has at most $2$ orbits on $\Ga(\a)\cap\Ga_2(\b)$ and on $\Ga_2(\a)\cap\Ga(\b)$.

To complete the proof, it suffices to prove that $G_{\a\b}$ has at most two orbits on $\Ga_2(\a)\cap\Ga_2(\b)$. To see this, we may assume that $G_{\a\b}$ is intransitive on $\Ga(\a)\cap\Ga_2(\b)$. Then there exist $\d_1, \d_2\in\Ga_2(\a)\cap\Ga_2(\b)$ such that the orbits $\d_1^{G_{\a\b}}\neq \d_2^{G_{\a\b}}$. Then $\d_1,\d_2$ are not adjacent to $\a$ and $\b$. Since $\Ga$ is $(G,3)$-set-homogeneous, there exists a $g\in G$ such that $\d_1^g=\d_2$, and $\a^g=\b$ and $\b^g=\a$. For any $\d\in \Ga_2(\a)\cap\Ga_2(\b)$, also since $\Ga$ is $(G,3)$-set-homogeneous, there exists $h\in G_{\{\a,\b\}}$ such that $\d^h=\d_1$. If $h\in G_{\a\b}$, then $\d\in \d_1^{G_{\a\b}}$. If $h\notin G_{\a\b}$, then $h$ swaps $\a$ and $\b$ and so $hg\in G_{\a\b}$. Furthermore, $\d^{hg}=\d_1^g=\d_2$, and hence $\d\in \d_2^{G_{\a\b}}$. Thus, $\Ga_2(\a)\cap\Ga_2(\b)=\d_1^{G_{\a\b}}\cup \d_2^{G_{\a\b}}$.
The proof is completed.
\hfill\qed
\end{proof}

The next lemma gives some basic properties about strongly regular graphs, see \cite[\textsection{1.1.1-1.1.2}]{BrouwerSRG}.

\begin{lem}\label{lem:drg-basic}
Let $\Ga$ be a strongly regular graph with parameters $(v, k, \lambda, \mu)$. Then the following hold:
\begin{enumerate}
  \item [{\rm (1)}]\ The complement $\overline{\Ga}$ of $\Ga$ is strongly regular with parameters $(v, \overline{k}, \overline{\ld}, \overline{\mu})$, where $\overline{k}=v-k-1$, $\overline{\ld}=v-2k+\mu-2$ and $\overline{\mu}=v-2k+\lambda$;
  \item [{\rm (2)}]\ $0\leq \ld\leq k-1$ and $0\leq\mu\leq k$;
  \item [{\rm (3)}]\ $k(k-1-\lambda)=\mu(v-1-k)$.
\end{enumerate}
\end{lem}

Let $\mathbf{P}_{3}$ be a path of length $2$. For a graph $\Ga$, let
\[
\begin{array}{l}
\Ome_1(\Ga):=\{U\subseteq V(\Ga) \mid [U]\cong \K_1\cup\K_2 \},\\
\Ome_2(\Ga):=\{U\subseteq V(\Ga) \mid [U]\cong \mathbf{P}_{3}\},\\
\Ome_3(\Ga):=\{U\subseteq V(\Ga) \mid [U]\cong \K_3\},\\
\Ome_4(\Ga):=\{U\subseteq V(\Ga) \mid [U]\cong 3\K_1\}.\\
\end{array}

