In a different approach, Lupu \cite{[L-MZ]} provided elementary proofs of
Zagier's formula for the special case $b=0$, and also established a Zagier-type
formula for multiple $t$-values when $b=0$. For the general case $b>0$, Lupu
\cite{[L-MZ]} proposed the following two conjectures.

\begin{conjecture}\label{con1}
For nonnegative integers $a$ and $b$, we have
\begin{align}
H(a,b)=\frac{-4\pi^{2a+2b+2}}{(2a+2)!}\sum_{n=0}^{\infty}
\frac{\zeta(2n)}{(2n+2a+2)(2n+2a+3)\cdots(2n+2a+2b+3)2^{2n}}.
\end{align}
\end{conjecture}

\begin{conjecture}\label{con2}
For nonnegative integers $a$ and $b$, we have
\begin{align}
T(a,b)=\frac{-2}{(2a+1)!}\left(\frac{\pi}{2}\right)^{2a+2b+2}
\sum_{n=0}^{\infty}\frac{\zeta(2n)}{(2n+2a+1)(2n+2a+2)\cdots(2n+2a+2b+2)2^{2n}}.
