We now compute $\P_{\boldsymbol{\lambda}, \boldsymbol{\mu}}(\mathcal{A}_{u}(v))$ for $\{u^{-1},u\}\in\mathcal{P}_v$. When $u\sim \rho$, it is clear that $\P_{\boldsymbol{\lambda}, \boldsymbol{\mu}}(\mathcal{A}_{u}(v))=\P_{\boldsymbol{\lambda}, \boldsymbol{\mu}}(\mathcal{A}_{u}(u))=1$. Assume from now {on} that $|u|\ge 2$. Recall that $\mathcal{A}_{u}(v)$ is the event that the process $\X^{(v)}$ reaches $u$ before returning to $\rho$ since the first hitting time to $u^{-1}$. It is clear that $\X^{(v)}$ has visited all vertices from $\rho$ to $u^{-1}$ by that time.
Let
\begin{align*}
 \mathcal{I}_0:=\Big\{ u^{-2}=\arg\min_{w\sim u^{-1}} \frac{\xi(u^{-1},w,0)}{r_{\boldsymbol{\lambda}}(u^{-1},w)}\Big\},\ 
\mathcal{I}_1 := \Big\{u=\arg\min_{w\sim u^{-1}} \frac{\xi(u^{-1},w,0)}{r_{\boldsymbol{\lambda}}(u^{-1},w)}\Big\} \text{ and }
\mathcal{I}_2 := (\mathcal{I}_{0}\cup \mathcal{I}_{1})^c.
\end{align*}
Note that
\begin{equation}\label{prob.Ik}\begin{aligned}
 \P_{\boldsymbol{\lambda}, \boldsymbol{\mu}}(\mathcal{I}_0)&=\frac{\lambda_{u^{-1}}}{\lambda_{u^{-1}}+\deg({u^{-1}})-1},\\ \P_{\boldsymbol{\lambda}, \boldsymbol{\mu}}(\mathcal{I}_1)&=\frac{1}{\lambda_{u^{-1}}+\deg({u^{-1}})-1}\ \ \text{ and}\\
 \P_{\boldsymbol{\lambda}, \boldsymbol{\mu}}(\mathcal{I}_2)&=1-\frac{1}{\lambda_{u^{-1}}+\deg({u^{-1}})-1}-\frac{\lambda_{u^{-1}}}{\lambda_{u^{-1}}+\deg({u^{-1}})-1}=\frac{\deg({u^{-1}})-2}{\lambda_{u^{-1}}+\deg({u^{-1}})-1}. \end{aligned}\end{equation}

Throughout this section we assume that for all $v\in V\setminus\{\rho\}$,
 $$\mu_{v}=1 \text{ and }\lambda_v=1+\alpha_v \deg(v),$$
 where $(\alpha_v)_{v\in V\setminus\{\rho\}}$ are i.i.d. non-negative random variables with $m=\E[1/(\alpha_v+1)].$ We will show that $\Psi(e)$ concentrates around $|e|^{-2+m\pm\eps}$ with high probability. Using the Borel-Cantelli lemma, we infer that there is a sequence of cutsets $(\pi_n)_{n\ge0}$ such that $\Psi(e)\le |e|^{-2+m+\eps}$ a.s. for each edge $e\in \bigcup_{n\ge0} \pi_{n}$. Combining this fact and Theorem \ref{RT.thm}, we obtain the recurrence case of Theorem \ref{main.thm}. In order to demonstrate the transience case of Theorem \ref{main.thm}, we use the quasi-independent percolation technique to show that, with positive probability, there is an infinite subtree $\widetilde{\Tcal}$ containing the root such that $\Psi(e)\ge \kappa^{-1} |e|^{-2+m-\eps}$, with $\kappa>0$, for each edge $e$ of $\widetilde{\Tcal}$ and $\text{br}_{r}(\widetilde{\Tcal})>\text{br}_{r}(\Tcal)-2\eps$. This fact, together with Theorem \ref{RT.thm}, yields the transience case.

Set $\kappa:= 1+\max_{v\sim \rho} \alpha_v$.
 Fix $\eps>0$ and
 let $$\mathcal{B}_e:=\Big\{\kappa^{-1}|e|^{-2+m-\eps} \le \Psi(e)\le |e|^{-2+m+\eps}\Big\}.$$
 \begin{lemma}\label{lem.B} We have
 $$ \P( \mathcal{B}_e^c)\le K_1 \exp(- K_2(\log |e|)^2),$$
 where $K_1$ and $K_2$ are some positive constants depending only on $\eps$.
 \end{lemma}
 \begin{proof}
 Substituting 
 $\mu_{v}=1$ for all $v\in V\setminus\{\rho\}$ into \eqref{def.psi}, we have
 $$\psi(v^{-1},v)=1-\frac{2(\lambda_{v^{-1}}-1)+\deg({v^{-1}})}{|v|(\lambda_{v^{-1}}-1+\deg({v^{-1}}))} \text{ for $|v|\ge 2$.}$$
 As $\lambda_v=1+\alpha_v \deg(v)$, we obtain
 $$\psi(v^{-1},v)=1-\frac{1}{|v|}\frac{2\alpha_{v^{-1}}+1}{\alpha_{{v^{-1}}}+1},$$
 {for $|v|\ge 2$ and $\psi(\rho,v)=1$ for $v\sim \rho$.}
 Define $C_v:=\frac{2\alpha_{v^{-1}}+1}{\alpha_{v^{-1}}+1}$. We obtain
 $$\Psi(e)=\prod_{g \in \Pcal_e} \psi(g) = \frac{1}{2(1+\alpha_{v_1(e)})} \prod_{v\in\mathcal{P}_e, |v|\ge 3} \left( 1 - \frac{C_v}{|v|} \right),$$
 where $v_1(e)$ is the unique vertex on $\mathcal{P}_e$ such that $v_1(e)\sim \rho$. Hence
 $$\log(\Psi(e)) = \sum_{v\in\mathcal{P}_e, |v|\ge 3} \log\Big(1 - \frac{C_v}{|v|}\Big)- \log\left(2(1+\alpha_{v_1(e)})\right).$$
 Using the inequality $\log(1 - x) \le -x$ for $x \in (0, 1)$ with 
 $x=\frac{C_v}{|v|} \in (0,1) \text{ for } |v| \ge 3$, we obtain
 $$\log(\Psi(e)) \le -\sum_{v\in\mathcal{P}_e, |v|\ge 3} \frac{C_v}{|v|}.$$
 Using the inequality $\log(1 - x) \ge -x - \frac{x^2}{1-x}$ with $x=\frac{C_v}{|v|} \in (0,1)$ for $|v| \ge 3$, we get
 $$
 \log(\Psi(e)) \ge -\sum_{v\in\mathcal{P}_e, |v|\ge 3} \frac{C_v}{|v|} - \sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{(\frac{C_v}{|v|})^2}{1-\frac{C_v}{|v|}}- \log\left(2\kappa\right),
 $$
 where we recall that $\kappa= 1+\max_{v\sim \rho} \alpha_v$.
 The second sum in the right hand side is bounded by a constant. In fact, since $C_v \in [1,2]$ and $|v| \ge 3$, we have
 $$
 \sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{(\frac{C_v}{|v|})^2}{1-\frac{C_v}{|v|}} \le \sum_{v\in\mathcal{P}_e, |v|\ge 3} \frac{\frac{4}{|v|^2}}{1-\frac{2}{|v|}}
 \le \sum_{v\in\mathcal{P}_e, |v|\ge 3} \frac{\frac{4}{|v|^2}}{\frac{1}{3}}
 = 12\sum_{n=3}^{|e|} \frac{1}{n^2}\le 12\sum_{n=1}^{\infty}\frac{1}{n^2}=2\pi^2.
 $$
 Therefore
 \begin{align}\label{R.E1}
 - S_e - 2\pi^2-\log\left(2\kappa\right) \le \log(\Psi(e)) \le -S_e,
 \end{align}
in which we set $$S_e:=\sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{C_v}{|v|}.$$ 
Applying Hoeffding's inequality (see Proposition \ref{Hoeffding}) to the random variables $\frac{C_v}{|v|} \in \big[\frac{1}{|v|},\frac{2}{|v|}\big]$ for $v\in \mathcal{P}_e$ with $|v|\ge 3$, we have
 $$\P \big(|S_e-\E[S_e]|\geq t\big)\leq 2\exp \left(-{\frac {2t^{2}}{\sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{1}{|v|^2}}}\right).$$
Choosing $t=\frac{\eps}{2}\log|e|$ and using the fact that
 $$\sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{1}{|v|^2} \le \sum_{k=1}^{\infty}\frac{1}{k^2}=\frac{\pi^2}{6},$$
we obtain
 \begin{align}\label{Hoeffding1}
 \P \big(|S_e-\E[S_e]|\geq \frac{\eps}{2}\log|e| \big)\leq 2\exp\left(
 -\frac{3\varepsilon^{2}}{\pi^{2}}(\log|e|)^{2} \right).
 \end{align}
On the other hand, we notice that
 $$\E[S_e]=\sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{\E[C_v]}{|v|}=\sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{\E[2-\frac{1}{\alpha_{v^{-1}}+1}]}{|v|}=(2-m)\sum_{k=3}^{|e|}\frac{1}{k}.$$
 Using the harmonic series bound $\log(n) \le \sum_{k=1}^n \frac{1}{k} \le 1+\log(n)$, we have
 \begin{align}\label{Ex1}
 (2-m) \left(\log|e|-\frac{3}{2}\right) \le \E[S_e] \le (2-m) \log|e|.
 \end{align}
It follows from (\ref{R.E1}) and (\ref{Ex1}) that, on the event $\{\Psi(e) < \kappa^{-1}|e|^{-2+m-\eps}\}$, we have
\begin{equation}\label{lb}
 \begin{aligned}
 S_e-\E[S_e] & \ge (2-m+\eps)\log|e|-2\pi^2- \log(2) -(2-m) \log|e|\\
 &=\eps \log|e|-2\pi^2- \log(2).
 \end{aligned}
\end{equation}
 Similarly, it follows from (\ref{R.E1}) and (\ref{Ex1}) that, on the event $\{\Psi(e) > |e|^{-2+m+\eps}\}$, we have
 \begin{align}\label{ub}
 S_e-\E[S_e] \le (2-m-\eps)\log|e|-(2-m) \left(\log|e|-\frac{3}{2}\right)\le -\eps \log|e|+3.
 \end{align}
Combining (\ref{lb}) and (\ref{ub}), we obtain that
\begin{align*}
 \mathcal{B}_e^{c}& = \big\{\Psi(e) < \kappa^{-1} |e|^{-2+m-\eps}\big\}\cup\{ \Psi(e) > |e|^{-2+m+\eps}\big\}
 \\ & \subset \{ S_e-\E[S_e] \ge \eps \log|e|-2\pi^2- \log(2)\}\cup \{ S_e-\E[S_e] \le -\eps \log|e|+3\}\\
 & \subset \Big\{|S_e-\E[S_e]|\geq \frac{\eps}{2}\log|e|\Big\}
\end{align*} 
for large enough $|e|$.
Using the above inclusion and \eqref{Hoeffding1}, we deduce that
 $$
 \begin{aligned}
 \P(\mathcal{B}_e^{c}) 
 & \le \P \Big(|S_e-\E[S_e]|\geq \frac{\eps}{2}\log|e| \Big) \le 2\exp\left(
 -\frac{3\varepsilon^{2}}{\pi^{2}}(\log|e|)^{2} \right)
 \end{aligned}
$$
for large enough $|e|$. This ends the proof of the lemma. 
 \end{proof}
