\section{Preliminaries}
\label{sec:prelim}
Let $B$ be a skew brace. Equation~\eqref{eq:left-dist} yields the same identity element in both additive and multiplicative groups. We denote it by~$0$. Then, the multiplicative group acts on the additive group by means of a homomorphism $\lambda\colon a \in (B,\cdot) \mapsto \lambda_a\in \Aut(B,+)$, with $\lambda_a(b) = -a+ab$ for every $a,b\in B$. Moreover, equation~\eqref{eq:left-dist} on the left (resp. on the right) yields
\begin{equation} 
\label{eq:a(-b)}
a(-b) = a -ab +a, \quad (-b)a= a -ba +a, \quad \forall a,b\in B
\end{equation}

\begin{Lemma} \label{easyLemma}
Let $B$ be a skew brace and $x \in B$. If $\lambda_{x}(x) = x$, then $\langle x \rangle_{+}$ is a trivial subbrace of~$B$.
\end{Lemma}
\begin{proof}
Since $\lambda_{x}(x) = x$, we also have that $\lambda_{x^{-1}}(x) = x$. Thus, $0 = x^{-1}x = x^{-1} + \lambda_{x^{-1}}(x) = x^{-1}+x$, i.e. $x^{-1} = -x$. By induction, assume that $x^k = kx$ and $x^{-k} = -kx$ for some $k\geq 1$. Then,
\[ x^{k+1} = xx^{k} = x + \lambda_x(x^k) = x + \lambda_x(kx) = x + k\lambda_x(x) = (k+1)x,\]
and, analogously,
\[x^{-(k+1)} = x^{-1}x^{-k} = x^{-1} + \lambda_{x^{-1}}(x^{-k}) = -x + \lambda_{x^{-1}}(-kx) = -(k+1)x\]
Hence $\langle x \rangle_{+}$ is a trivial subbrace of~$B$.
\end{proof}

\begin{Note}
\label{Note:trivialSemitrivial}
If a skew brace $B$ is either trivial or almost trivial, then every subset $H$ of $B$ satisfies: $H \le (B,+)$ if and only if $H \le (B,\cdot)$. Thus, for every prime $p$ dividing $|B|$, there exists a subbrace $H \le B$ such that $|H| = p$.
\end{Note}

Question~\ref{que:Cauchy} has a positive answer if the additive group of a skew brace is nilpotent.
\begin{Lemma} \label{nilptype}
Let $B$ be a skew brace with nilpotent additive group. Then, for every prime $p$ dividing $|B|$, there exists a subbrace $H \le B$ such that $|H| = p$.
\end{Lemma}

