We are ready to prove the uniqueness part of our main result.
 \begin{pro}
 \label{prop:unical}
 Let $\bar g\in \mathcal{C}$. Assume that there exist points $\varphi_i,\psi_i$, $i=1,2$, satisfying \eqref{eq:alternance-pts} and such that
 \begin{equation}
 \label{eq:alternance-pts-values-2}
 f(\varphi_i) - \bar g(\varphi_i) = \bar g(\psi_i) - f(\psi_i) =\|f-\bar g\|_\infty,\quad i=1,2.
 \end{equation}
 Then $\bar g$ is the unique solution to \eqref{eq:Ch}.
 \end{pro}
 \begin{proof}
 Let $\hat g \in \mathcal{C}$ be such that
 \begin{equation}
 \label{eq:51}
 \|f-\hat g\|_\infty \le \|f - \bar g\|_\infty.
 \end{equation}
 If we can prove that from this follows $\hat g = \bar g$ then obviously $\bar g$ is a solution to \eqref{eq:Ch} and, moreover, unique.

Assume that
 \begin{equation}
 \label{eq:71}
 \bar g \neq \hat g.
 \end{equation} 
 Let $h := \bar g - \hat g$. We can write $h(\varphi_i) = (f-\hat g) (\varphi_i) - (f-\bar g) (\varphi_i)$. By \eqref{eq:alternance-pts-values-2} we have $(f-\bar g)(\varphi_i) = \|f-\bar g\|_\infty$, so $h(\varphi_i) = (f-\hat g)(\varphi_i) - \|f-\bar g\|_\infty \le \|f-\hat g\|_\infty - \|f-\bar g\|_\infty \le 0$ by \eqref{eq:51}. Thus $h(\varphi_i) \le 0$.
 Similarly, $h(\psi_i) = (f-\hat g)(\psi_i) + (\bar g -f)(\psi_i) = (f-\hat g)(\psi_i) + \|f-\bar g\|_\infty \ge \|f-\bar g\|_\infty - \|f-\hat g\|_\infty \ge 0$. We have shown that
 \begin{equation}
 \label{eq:72}
 h(\varphi_i) \le 0 \le h(\psi_i),\quad i=1,2.
 \end{equation}
 Consequently, there exist $\xi_i\in[\varphi_i,\psi_i]$, $i=1,2$ (in particular, $\xi_1<\xi_2$) such that $h(\xi_i) = 0$ for $i=1,2$. If there were a third point in $[\varphi_1,\varphi_1+\pi)$ at which $h=0$, then Proposition~\ref{prop:elipses-3-pts-equial} would have implied $\bar g = \hat g$, contradicting \eqref{eq:71}, so
 \begin{equation}
 \label{eq:73}
 h(\varphi) \neq 0,\quad \forall \varphi \in [\varphi_1,\varphi_1+\pi) \setminus \{\xi_1,\xi_2\}.
 \end{equation}
 Also, if $h'(\xi_i) = 0$ for some $i=1,2$, then again Proposition~\ref{prop:elipses-3-pts-equial} implies $\bar g = \hat g$, so
 \begin{equation}
 \label{eq:74}
 h'(\xi_i) \neq 0,\quad i=1,2.
 \end{equation}
 From \eqref{eq:73} and $\xi_1\le\psi_1<\varphi_2\le\xi_2$ it follows that $h(\varphi) \neq 0$ for all $\varphi\in(\psi_1,\varphi_2)$. Since $h$ is continuous, it has a constant sign on $(\psi_1,\varphi_2)$, so there are two possibilities:

Thus \eqref{eq:contra} is verified, but it contradicts \eqref{eq:alternance-*}. Therefore, there is $\varphi_2\in\Phi\cap(\psi_1,\psi_2)$ and $\varphi_i,\psi_i$ satisfy \eqref{eq:alternance-pts} and \eqref{eq:alternance-pts-values-2}.
 \end{proof}
 In view of the work so far the following completes our study.
 \begin{pro}
 \label{prop:final}
 The problem \eqref{eq:Ch} has a solution.
 \end{pro}
 \begin{proof}
 Here it is easier to work with the standard form of the ellipses in polar co-ordinates. Take $(a,b,c)\in K$, that is, $a>\sqrt{b^2+c^2}$, and set 
 $$
 b':= \sqrt{b^2+c^2},\quad b = b'\cos 2\theta,\ c = b'\sin 2\theta.
 $$
 Then
 $$
 \mathfrak{R}(a,b,c) = a + b'\cos 2(\varphi-\theta).
 $$
 $K$ translates to
 $$
 K' := \{(a,b',\theta):\ a>b'\ge0,\ \theta\in[0,\pi]\},
 $$
 and
 $$
 \mathcal{C} = \{-(1/2)\log(a + b'\cos 2(\varphi-\theta)) : (a,b',\theta) \in K'\}.
 $$
 Let $(a_n,b_n',\theta_n)\in K'$ be such that for
 $$
 g_n(\varphi) := -\frac{1}{2}\log(a_n + b_n'\cos 2(\varphi-\theta_n))
 $$
 we have
 $$
 \lim_{n\to\infty} \|f-g_n\|_\infty = \mathfrak{d}.
 $$
 By taking a subsequence we may assume that $\theta_n\to\theta$, as $n\to\infty$. Since
 $$
 g_n(\theta_n+\pi/4) = -\frac{1}{2}\log a_n,
 $$
 and $\|g_n\|_\infty < \|f\|_\infty + \mathfrak{d} + 1$ for large enough $n$'s, the sequence $\{\log a_n\}_{n=1}^\infty$ is bounded, so there is $r>0$ such that
 $$
 r \le a_n \le 1/r,\quad\forall n\in\mathbb{N}.
 $$
 Therefore, we may assume that $a_n\to a >0$, as $n\to\infty$. We also assume that $b_n'\to b'\le a$, as $n\to\infty$. If $b'=a$ then
 $$
 g_n(\theta_n+\pi/2) = -\frac{1}{2}\log(a_n - b_n') \to \infty,\text{ as }n\to\infty,
 $$
 which is a contradiction. So, $(a,b',\theta)\in K'$ and by continuity it follows that the corresponding $g\in\mathcal{C}$ solves \eqref{eq:Ch}.
 \end{proof}

