\begin{equation}
 \frac{1}{p+2}\frac{d}{dt}\int \rho |v|^{p+2}dx + \frac{1}{2}\int \rho |v|^p |\nabla v|^2dx + \frac{p}{2}\int \rho |v|^p |\nabla |v||^2dx \leq C(p+1)\left( \int \rho |v|^{p+2} dx \right)^{1-\frac{2}{p}}.
\end{equation}
