\begin{equation}
 \begin{aligned}
&\sup_{0 \le t \le T}\frac{1}{p+2}\int{\rho}|v|^{p+2}dx+ \frac{1}{2}\int_{0}^{T}\int \rho |v|^p |\nabla v|^2dxdt + \frac{p}{2}\int_{0}^{T}\int \rho |v|^p |\nabla |v||^2dxdt \\
