\end{aligned}
\end{equation}
Substituting this into the RHS of \eqref{the initial estimate for Psi}, we get
\begin{equation}
 \begin{aligned}
\Psi(r(p+2))&\leq C{V}_{T} \left( C(p+2)^2 \left( \int^{T}_{0}\int \rho |v|^{p+2} dxdt \right)^{\frac{p-2}{p}} + C \int \rho_0 |v_0|^{p+2} dx \right) ^{r }\\
