We prove Theorem~\ref{thm1} by constructing appropriate comparison functions. They are given in the form
\begin{equation*}
u^{\pm}(x,y,t)\coloneqq\Phi_{c^{*}}\left(\frac{y-V(x,t)}{\sqrt{1+|\nabla_{x}V|^{2}}}\mp q(t)\right)\pm p(t)\chi \left( e^{\lambda (y-c_*t)}\right),
\end{equation*}
where $V$ is a solution of the equation
\begin{equation*}
V_{t}=\Delta_{x}V+\frac{c^{*}}{2}|\nabla_{x} V|^2+c_*,
\end{equation*}
$\lambda$ is a number with $\lambda<\lambda_1$
and $\chi$ is a smooth function safisfying $\chi(s)=s$ ($s \le 1/2$) and $\chi(s)=1$ ($s \ge 1$).
We will show that $u^+$ (resp. $u^-$) becomes a supersolution (resp. a subsolution) for the problem \eqref{Rea-Diff} if $p(t)$, $q(t)$ and the initial data for $V(x,t)$ are chosen appropriately. Theorem~\ref{thm1} (ii) is then proved by using these comparison functions and applying the fact that the solution $U$ of \eqref{MCF} is approximated by $V$.

In this section, we establish the following estimates.
\begin{prop}\label{lem3}
Let $u(x,z,t)$ be a solution of \eqref{MRea-Diff}. 
If the initial data $u_{0}$ is satisfies \eqref{init1} and \eqref{init3},
then there exists constants $z_{1},z_{2}\in\mathbb{R}$ such that
\begin{equation}
\label{upper}
\limsup_{t\to\infty}\sup_{x\in\mathbb{R}^{n-1}}u(x,z,t)\le\Phi_{c}(z-z_{0})\;\mbox{uniformly in }z\in\mathbb{R}
\end{equation}
\begin{equation}
\label{lower}
\liminf_{t\to\infty}\inf_{x\in\mathbb{R}^{n-1}}u(x,z,t)\ge\Phi_{c}(z-z_{1})\;\mbox{uniformly in }z\in\mathbb{R}
\end{equation}
The same inequalities hold if \eqref{init2} is assumed instead of \eqref{init3}.
\end{prop}
We split the proof of this proposition into the case 1 and case 2:
\begin{enumerate}
\item[1:]\eqref{init1} and \eqref{init3}
\item[2:]\eqref{init1} and \eqref{init2}
\end{enumerate}
First, we show upper and lower estimates for case 1.
For this, we recall the lemmas in \cite{MR639447}. We take any $\lambda<\lambda_{1}<\lambda_{+}$ and define $\psi(s)$ as
\begin{equation*}
\psi(s)=\chi(e^{\lambda_{1}s})
\end{equation*}
\begin{equation*}
\chi(s)\coloneqq\left\{
\begin{aligned}
1\;(s\ge1)\\
s\;(s\le\frac{1}{2})
\end{aligned}
\right.
\end{equation*}
, where $0\le\chi(s)\le1$ for $s\in(\frac{1}{2},1)$. For these, the following lemmas hold
\begin{lem}[\cite{MR639447}]\label{add_B}
There exists $p\in(0,1)$ such that, for any $q_{0}\in(0,p],z_{1},z_{2}\in\mathbf{R}$, there exists $\beta>0,C>0$ such that
\begin{equation*}
w^{+}(z,t)\coloneqq \Phi_{c^{*}}(z-z_{1}- C(1-e^{-\beta t}))+q_{0}e^{-\beta t}\psi(z-z_{2})
\end{equation*}
satisfies $L[w^+]\ge0$.
\end{lem}

\section{Level set of the solutions}
As we mention in the previous section, we only give statements of lemmas and omit their proof.
\begin{lem}[Level set]\label{lem11}
Let $u(x,z,t)$ be a solution of ($\ref{MRea-Diff}$) and $T>0$ be as defined in Corollary 2. Then there exists a smooth bounded function $\Gamma(x,t)$ such that
\begin{equation*}
u(x,z,t)=\Phi_{c}(0)\quad\mbox{if and only if}\quad z=\Gamma(x,t),
\end{equation*}
for any $(x,t)\in\mathbb{R}^{n-1}\times[T,\infty)$. Furthermore the following estimates hold:
\begin{enumerate}
\item For each $1\le i,j \le n-1$,
\begin{equation*}
\lim_{t\to\infty}\sup_{x\in\mathbb{R}^{n-1}}|\Gamma_{x_{i}}(x,t)|=0,\quad\lim_{t\to\infty}\sup_{x\in\mathbb{R}^{n-1}}|\Gamma_{x_{i}x_{j}}(x,t)|=0,
\end{equation*}
\item There exists a constant $M>0$ such that, for each $1\le i,j,k \le n-1$,
\end{enumerate}
\begin{equation*}
\sup_{x\in\mathbb{R}^{n-1}}|\Gamma_{x_{i}x_{j}x_{k}}|\le M,\quad \mbox{for}\quad t\ge T.
\end{equation*}
\end{lem}

\begin{lem}[Approximation of $\Gamma(x,t)$]\label{lem15}
Let $u(x,z,t)$ be a solution of (\ref{MRea-Diff}) and let $\Gamma(x,t)$ be as defined in Lemma \ref{lem11}. Then for any $\varepsilon>0$, there exists a constant $\tau_{\varepsilon}>0$ such that the function $V(x,t)$ defined by
\begin{equation*}
\left\{
\begin{aligned}
&V_{t}=\Delta_{x}V+\frac{c^{*}}{2}|\nabla_{x} V|,\quad x\in\mathbb{R}^{n-1},t>0\\
&V(x,0)=\Gamma(x,\tau_{\varepsilon}).\qquad\hspace{9.4pt} x\in\mathbb{R}^{n-1}.
\end{aligned}
\right.
\end{equation*}
satisfies
\begin{equation*}
\sup_{x\in\mathbb{R}^{n-1}}|\Gamma(x,t)-V(x,t-\tau_{\varepsilon})|\le\varepsilon,\quad t\ge\tau_{\varepsilon}.
\end{equation*}
\end{lem}

\begin{proof}
 First, we verify upper bound. By Lemma \ref{lem12} and \ref{lem13}, we can take $T>0, M>0$ and $K>0$ such that, for $D\coloneqq\left\{(x,z,t)\in\mathbb{R}^{n}\times[T,\infty)||u(x,z,t)-\Phi_{c}(0)|\le\min(1-\Phi_{c}(0),\Phi_{c}(0))\right\}$
\begin{equation*}
\sup_{t\ge T}\|\Gamma(\cdot,t)\|_{W^{3,\infty}}\le M,\quad \inf_{(x,z,t)\in D}-u_{z}(x,z,t)\ge K.
\end{equation*}
For the constants $M$ and $\hat{\varepsilon}\coloneq1/(\|\Phi_{c^{*}}^{\prime}\|_{L^{\infty}}+1)\cdot\min\{K\varepsilon,\min(1-\Phi_{c^{*}}(0),\Phi_{c^{*}}(0))\}$, we choose a constant $\delta>0$ and functions $p(t),q(t)$ satisfying
\begin{equation*}
p(0)>0,\quad q(0)=0,\quad 0\le p(t),q(t)\le\hat{\varepsilon}\quad for \quad t\ge0.
\end{equation*}
From proof of Lemma \ref{lem3} and (\ref{asym}), we can take $z_{0}\in\mathbb{R}$ such that, for some larger $T>0$, 
\begin{equation*}
u(x,z,t)\le p(0)e^{\lambda z}\quad((x,z,t)\in\mathbb{R}^{n-1}\times[z_{0},\infty)\times[T,\infty)).
\end{equation*}
Taking $\tau_{\varepsilon}\ge T$ larger if necessary, by Lemma \ref{lem11} and \ref{lem12}, the following holds
\begin{equation*}
u(x,z,t)\le\Phi_{c^{*}}(z-\Gamma(x,\tau_{\varepsilon}))+\frac{p(0)e^{\lambda z_{0}}}{2}\le\Phi_{c^{*}}\left(\frac{z-\Gamma(x,\tau_{\varepsilon})}{\sqrt{1+|\nabla_{x}\Gamma|^{2}}}\right)+p(0)e^{\lambda z_{0}}
\end{equation*}
For any $z\ge z_{0}$, 
\begin{equation*}
u(x,z,\tau_{\varepsilon})\le p(0)e^{\lambda z}\le u^{+}(x,z,0).
\end{equation*}
For any $z<z_{0}$,
\begin{equation*}
u(x,z,\tau_{\varepsilon})\le \Phi_{c^{*}}\left(\frac{z-\Gamma(x,\tau_{\varepsilon})}{\sqrt{1+|\nabla_{x}\Gamma|^{2}}}\right)+p(0)e^{\lambda z_{0}}\le\Phi_{c^{*}}\left(\frac{z-\Gamma(x,\tau_{\varepsilon})}{\sqrt{1+|\nabla_{x}\Gamma|^{2}}}\right)+p(0)\psi(z).
\end{equation*}
So, by comparison principle, $u(x,z,t)\le u^{+}(x,z,t)$ for $t\ge\tau_{\varepsilon}$. Therefore, we have the following inequality
\begin{align*}
u(x,V(x,t-\tau_{\varepsilon}),t)-\Phi_{c^{*}}(0)&\le u^{+}(x,V(x,t-\tau_{\varepsilon}),t)-\Phi_{c^{*}}(0)\\
 &=\Phi_{c^{*}}(-q(t-\tau_{\varepsilon}))-\Phi_{c^{*}}(0)+p(t-\tau_{\varepsilon})\\
 &\le(\|\Phi_{c^{*}}^{\prime}\|_{L^{\infty}}+1)\hat{\varepsilon}\\
 &=\min\{K\varepsilon,\min\{1-\Phi_{c^{*}}(0),\Phi_{c^{*}}(0)\}\}.
\end{align*}
Thus, we have, for $\Gamma(x,t)\ge V(x,t-\tau_{\varepsilon})$,
\begin{align*}
K\varepsilon&\ge u(x,V(x,t-\tau_{\varepsilon},t),t)-u(x,\Gamma(x,t),t)\\
 &\ge (\inf_{u\in[0,\min\{1-\Phi_{c^{*}}(0),\Phi_{c^{*}}(0)\}],t\ge\tau_{\varepsilon}}-u_{z})\cdot(\Gamma(x,t)-V(x,t-\tau_{\varepsilon}))\\
 &\ge K(\Gamma(x,t)-V(x,t-\tau_{\varepsilon})).
\end{align*}
This implies $\Gamma(x,t)\le V(x,t-\tau_{\varepsilon})+\varepsilon$ for $t\ge\tau_{\varepsilon}$. Thus, we have the upper estimate. The lower estimate is followed from Lemma \ref{lem14} in a similar way.
\end{proof}

