\begin{theorem} \label{Th1.1}
Let $(M_j,g_j)\ (j=1,2)$ be two compact Riemannian surfaces with boundaries $\Gamma_j$ and let
$\varphi:(\Gamma_1,ds_{g_1})\rightarrow(\Gamma_2,ds_{g_2})$ be an isometry preserving the DtN-map, i.e., such that the following diagram is commutative:
$$
\begin{array}{ccc}
C^\infty(\Gamma_1)&\stackrel{\varphi^*}\longleftarrow&C^\infty(\Gamma_2)\\
\Lambda_{g_1}\downarrow&&\downarrow\Lambda_{g_2}\\
C^\infty(\Gamma_1)&\stackrel{\varphi^*}\longleftarrow&C^\infty(\Gamma_2).
\end{array}
$$
Then $\varphi$ extends to a diffeomorphism $\psi:M_1\rightarrow M_2$ such that $\psi|_{\Gamma_1}=\varphi$ and $\psi^*g_2=\rho g_1$ for some
function $0<\rho\in C^\infty(M_1)$ satisfying $\rho|_{\Gamma_1}=1$.
\end{theorem}

ref_dict.Th4.1:
\begin{theorem} \label{Th4.1}
Let the  space ${\mathcal A}(\gamma)$ of functions on the unit circle  ${\mathbb S}$ be defined by \eqref{4.1} for some
compact simply connected domain $\Omega\subset{\mathbb C}$ bounded by a smooth simple curve $\Gamma$ of length $2\pi$. Then

{\rm (1)} The equation
\begin{equation}
\Big|\frac{df}{ds}\Big|=1
                                \label{4.2}
\end{equation}
has a solution $f\in{\mathcal A}_s(\gamma)$.

{\rm (2)} If $f_1,f_2\in{\mathcal A}_s(\gamma)$ are two solutions to the equation \eqref{4.2}, then
$f_1( s)=\alpha f_2( s)+c$ for some complex constants $\alpha$ and $c$ satisfying $|\alpha|=1$.

{\rm (3)} If $f\in{\mathcal A}_s(\gamma)$ is a solution to \eqref{4.2}, then the curve $s\mapsto f(s)$ bounds a domain that is
obtained from $\Omega$ by a shift and rotation.
\end{theorem}

ref_dict.thm_uniform_vanish:
\begin{theorem}
\label{thm_uniform_vanish}
Let $S$ be a Noetherian scheme over the field of rational numbers, and $f\colon X\subset\PP_S^n\to S$ be a smooth morphism of relative dimension $d\ge 0$. Let $\calF$ be a coherent sheaf on $X$ that is flat over $S$, and set $\calF_s\colonequals \calF\otimes_{\calO_S}\kappa(s)$ for $s\in S$. Then there exists an integer $t_0>0$ such that 
\[
\HH^i\left(X_s,\, \Sym^t\big(\scrI_{X_s}/\scrI_{X_s}^2\big)\otimes_{\calO_{X_s}}\calF_s\right)\ =\ 0
\]
for all $s\in S$, $t\ge t_0$, and $i\neq d$.
\end{theorem}

ref_dict.prop_inject:
\begin{proposition}
\label{prop_inject}
Let $I \subset R$ be a homogeneous ideal and $X=V(I)\subset\PP_A^n$ be the closed subscheme defined by $I$. Fix an integer $j\in\ZZ$. Assume that: 

\begin{enumerate}[\quad\rm(a)]
\item The natural projection $X\subset\PP_A^n\to\Spec A$ is a smooth morphism of relative dimension $d\ge 0$,
\item $I^t/I^{t+1}$ is $A$-flat for each $t\ge 0$,
\item $\HH_I^i(R)$ is $A$-flat for each $i\ge 0$.
\end{enumerate}
Then there is an integer $t_0>0$, such that the natural map 
\[
\CD
\psi_{B,t}^i\colon {\Ext_{R_B}^i\left(R_B/I^tR_B,\, R_B\right)}_{-j-n-1} @>>> {\Ext_{R_B}^i\left(R_B/I^{t+1}R_B,\, R_B\right)}_{-j-n-1}
\endCD
\]
is injective for each $t\ge t_0$ and $i\ge 0$, where $B$ is an arbitrary $A$-algebra, and $R_B\colonequals R\otimes_A B$.
\end{proposition}

