\begin{theorem}\label{theorem closed image del delbar}
Let $(M,g)$ be a complete K\"ahler manifold. If $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$, then for $b\in\{s,w\}$ it follows that
$\im\del\delbar_b$ and $\im\delbar^*\del^*_b$ are closed in $L^2\Lambda^{p,q}$.
\end{theorem}
\begin{proof}
By Theorem \ref{theorem spectral gap kodaira spencer laplacians}, $\tilde\Delta_{BC,bw}$ has a spectral gap in $L^2\Lambda^{p,q}$. By Lemma \ref{lemma spectral gap equiv}, this is equivalent to the closure of the image of $\tilde\Delta_{BC,bw}$. Therefore we can orthogonally decompose
\begin{align*}
L^2\Lambda^{p,q}&=\ker\tilde\Delta_{BC,bw}\overset{\perp}{\oplus}\im\tilde\Delta_{BC,bw}\\
&\subseteq \ker\tilde\Delta_{BC,bw}\overset{\perp}{\oplus}\left(\im\del\delbar_b + \im \delbar^*\del^*_s+\im \del^*\delbar_s+\im\delbar^*\del_s+\im(\del^*\oplus\delbar^*)_s\right)\\
&\subseteq \ker\tilde\Delta_{BC,bw}\overset{\perp}{\oplus}\im\del\delbar_b \overset{\perp}{\oplus} (\im\del^*_s+\im\delbar^*_s)\subseteq L^2\Lambda^{p,q}.
\end{align*}
The first inclusion follows by definition of $\tilde\Delta_{BC,bw}$, while the second inclusion is justified by \emph{(2)} of Proposition \ref{proposition properties strong weak} and the fact that 
\[
\im(\del^*\oplus\delbar^*)_s\subseteq\c{\im(\del^*\oplus\delbar^*)_s}=\c{\im\del^*_s}+\c{\im\delbar^*_s}=\im\del^*_s+\im\delbar^*_s,
\]
where the first equality is equation \eqref{equation kernel image del* e delbar*} and the second is obtained via Lemmas \ref{lemma spectral gap equiv 2} and \ref{lemma im closed} using the spectral gap of $\Delta_{\delbar,sw}=\Delta_{\del,sw}$ in $L^2\Lambda^{p,q}$.
The orthogonality of the above decompositions is easy to check.
The closure of $\im\del\delbar_b$ now follows from the orthogonality of the decomposition of $L^2\Lambda^{p,q}$ in the last line. Using the spectral gap of $\tilde\Delta_{A,sb}$ we similarly find the closure of $\im\delbar^*\del^*_b$ in $L^2\Lambda^{p,q}$.
\end{proof}

\begin{theorem}\label{theorem l2 del delbar lemma}
 Let $(M,g)$ be a complete K\"ahler manifold such that $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{k}_\C$. Given a smooth $L^2$-form $\alpha\in L^2A^k_\C$ which satisfies $\del\alpha=\delbar\alpha=0$, then the following conditions are equivalent:
 \begin{enumerate}
 \item $\alpha=\del\delbar\beta$, for $\beta\in L^2 A^{k-2}_\C$;
 \item $\alpha=\del\gamma$, for $\gamma\in L^2 A^{k-1}_\C$;
 \item $\alpha=\delbar\zeta$, for $\zeta\in L^2 A^{k-1}_\C$;
 \item $\alpha=\del\eta+\delbar\theta$, for $\eta,\theta\in L^2 A^{k-1}_\C$;
 \item $\alpha=d\lambda$, for $\lambda\in L^2 A^{k-1}_\C$.
 \end{enumerate}
\end{theorem}
\begin{proof}
 Since $\Delta_{\delbar,sw}=\Delta_{\del,sw}=\frac12\Delta_{d,sw}$ has a spectral gap in $L^2\Lambda^{k}_\C$, by Theorem \ref{theorem spectral gap kodaira spencer laplacians} also $\tilde\Delta_{BC,sw}$ and $\tilde\Delta_{A,sw}$ have a spectral gap in $L^2\Lambda^{k}_\C$.
 We define the orthogonal projection
 \[
 P_{BC}:L^2\Lambda^{k}_\C\to\ker \tilde\Delta_{BC,sw}
 \]
 and the Green operator
 \begin{align*}
 G_{BC}:&\im \tilde\Delta_{BC,sw}\to \D(\tilde\Delta_{BC,sw})\\
 & \tilde\Delta_{BC,sw}\beta\mapsto\beta.
 \end{align*}
 Being $\im \tilde\Delta_{BC,sw}$ closed, and recalling the orthogonal decomposition
 \[
 L^2\Lambda^{k}_\C=\ker \tilde\Delta_{BC,sw}\oplus\im \tilde\Delta_{BC,sw},
 \]
 we can extend the Green operator on the whole space $L^2\Lambda^{k}_\C$ simply by setting $G_{BC}=0$ on $\ker \tilde\Delta_{BC,sw}$. Given any form $\alpha\in L^2\Lambda^{k}_\C$, it decomposes as
 \[
 \alpha=P_{BC}\alpha+(id-P_{BC})\alpha,
 \]
 where $(id-P_{BC})\alpha=\tilde\Delta_{BC,sw}\beta$. Now $G_{BC}\alpha=\beta$, therefore
 \[
 \alpha=P_{BC}\alpha+\tilde\Delta_{BC,sw}G_{BC}\alpha.
 \]
 If, in particular, $\alpha$ is smooth and so $\alpha\in L^2A^k_\C$, then by elliptic regularity (see, \textit{e.g.}, \cite[Theorem 2.1]{HP}) also $G_{BC}\alpha=\beta\in L^2A^k_\C\cap \D(\tilde\Delta_{BC,sw})$ is smooth. In particular, by \emph{(5)} of Proposition \ref{proposition properties strong weak} we obtain 
 \[
 \tilde\Delta_{BC,sw}G_{BC}\alpha=\tilde\Delta_{BC}G_{BC}\alpha.
 \]
 The same holds for analogue operators $P_\delta$ and $G_\delta$ for $\delta\in\{A,\del,\delbar,d\}$.
 Therefore, if $\alpha\in L^2A^k_\C$, for $\delta\in\{A,BC\}$ and $\epsilon\in\{\del,\delbar,d\}$ we deduce decompositions
 \[
 \alpha=P_{\delta}\alpha+\tilde\Delta_{\delta}G_{\delta}\alpha=P_\epsilon\alpha+\Delta_{\epsilon}G_{\epsilon}\alpha,
 \]
 with smooth forms $G_{\delta}\alpha,G_{\epsilon}\alpha\in L^2A^k_\C$. Recall that by Theorem \ref{theorem complete kahler equality harmonic} the kernels of $\Delta_{\delbar,sw}=\Delta_{\del,sw}=\frac12\Delta_{d,sw}$, $\tilde\Delta_{BC,sw}$ and $\tilde\Delta_{A,sw}$ coincide, thus $P_{BC}\alpha=0$ iff $P_\delta=0$ for all $\delta\in\{A,\del,\delbar,d\}$.

Now assume that $\alpha\in L^2A^k_\C$ satisfies $\del\alpha=\delbar\alpha=0$. We know $\ker\del_w\cap\ker\delbar_w\subseteq L^2A^k_\C$ is $L^2$-orthogonal to
 \begin{align*}
 &\im d_s^*, &&\im\del_s^*, & &\im\delbar_s^*, &\im(\del^*\oplus\delbar^*)_s, &&\im\del\delbar_s^*,
 \end{align*}
 as in the proof of Theorem \ref{theorem reduced l2 del delbar lemma}. Thanks to this and to \emph{(5)} of Proposition \ref{proposition properties strong weak}, we obtain
 \begin{align*}
 &\alpha=\tilde\Delta_{A}G_{A}\alpha &&\iff && \alpha=(\del\del^*+\delbar\delbar^*)G_{A}\alpha,\\
 &\alpha=\tilde\Delta_{BC}G_{BC}\alpha &&\iff && \alpha=\del\delbar\delbar^*\del^*G_{BC}\alpha,\\
 &\alpha=\Delta_{\del}G_{\del}\alpha &&\iff && \alpha=\del\del^*G_{\del}\alpha,\\
 &\alpha=\Delta_{\delbar}G_{\delbar}\alpha &&\iff && \alpha=\delbar\delbar^*G_{\delbar}\alpha,\\
 &\alpha=\Delta_{d}G_{d}\alpha &&\iff && \alpha=dd^*G_{d}\alpha.
 \end{align*}
 It is then enough to set $\beta:=\delbar^*\del^*G_{BC}\alpha$, $\gamma:=\del^*G_{\del}\alpha$, $\zeta:=\delbar^*G_{\delbar}\alpha$, $\eta:=\del^*G_{A}\alpha$, $\theta:=\delbar^*G_{A}\alpha$, $\lambda:=d^*G_{d}\alpha$, which lie in $L^2\Lambda^\bullet_\C$ since the image of each Green operator is the domain of the corresponding Laplacian.
 This concludes the proof.
\end{proof}

\begin{remark}\label{remark bounded geometry}
 Suppose that, in addition to the assumptions of Theorem \ref{theorem l2 del delbar lemma}, the manifold $(M,g)$ is of bounded geometry and the elliptic Laplacians $\Delta_{\delbar}=\Delta_{\del}=\frac12\Delta_{d}$, $\tilde\Delta_{BC}$ and $\tilde\Delta_{A}$ are $\cinf$-bounded and uniformly elliptic, with the bundles of differential forms which are of bounded geometry (cf. \cite{Sh}). Examples of such manifolds are given by the universal coverings of K\"ahler hyperbolic manifolds \cite{G}. Then, by \cite[Proposition 1.1]{Sh} the domains of the above operators coincide with the Sobolev spaces
 \[
 \D(\Delta_{\delbar,sw})=\D(\Delta_{\del,sw})=\D(\Delta_{d,sw})=W^2_2(M,\Lambda^\bullet_\C)
 \]
 and
 \[
 \D(\tilde\Delta_{A,sw})=\D(\tilde\Delta_{BC,sw})=W^4_2(M,\Lambda^\bullet_\C),
 \]
 with the notation for Sobolev spaces as in \cite{Sh}. Therefore, since the image of each Green operator is one of the above domains, and thus the image is a Sobolev space, in the statement of Theorem \ref{theorem l2 del delbar lemma} we can choose $\beta\in W^2_2(M,\Lambda^{k-2}_\C)$ and $\gamma,\zeta,\eta,\theta,\lambda\in W^1_2(M,\Lambda^{k-1}_\C)$. In particular, $\del\beta,\delbar\beta\in W^1_2(M,\Lambda^{k-1}_\C)\subseteq L^2\Lambda_\C^{k-1}$.
\end{remark}

expanded_sketch:
The post-theorem introduction says that “The proof of the main theorem relies primarily on new spectral properties of some self-adjoint operators introduced in \cite{HP}.” More precisely, they “prove that if $\Delta$ has a spectral gap, there are self-adjoint extensions of fourth-order elliptic Aeppli and Bott-Chern Laplacians having a spectral gap, thereby allowing one to use arguments based on elliptic regularity,” and this is described as “the core of the proof.”

Because the “natural” Aeppli and Bott-Chern Laplacians $\Delta_A,\Delta_{BC}$ have kernels matching Aeppli/Bott--Chern cohomology but “are not elliptic,” the text explains that the spectral gap for self-adjoint extensions of $\Delta_A,\Delta_{BC}$ from \cite[Corollary 8.12]{HP} “was not sufficient to prove the main theorem.” Instead, “to prove our main result, we use the spectral gap of the elliptic Kodaira-Spencer Laplacians,” establishing it in the following theorem.

\begin{theorem}\label{theorem spectral gap kodaira spencer laplacians}
Let $(M,g)$ be a complete K\"ahler manifold. If $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$, then for $b\in\{s,w\}$ the operators $\tilde\Delta_{A,sb}$ and $\tilde\Delta_{BC,bw}$ have a spectral gap in $L^2\Lambda^{p,q}$.
\end{theorem}

They “also prove a spectral gap of the Varouchas Laplacians” in the following theorem.

\begin{theorem}\label{theorem spectral gap varouchas laplacians}
    Let $(M,g)$ be a complete K\"ahler manifold. 
    If $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$, $L^2\Lambda^{p-1,q}$ and $L^2\Lambda^{p,q-1}$, then $\square_{A,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$. If $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$, $L^2\Lambda^{p+1,q}$ and $L^2\Lambda^{p,q+1}$, then $\square_{BC,sw}$ has a spectral gap in $L^2\Lambda^{p,q}$.
\end{theorem}

Finally, the introduction remarks that the “spectral gap assumption of $\Delta$ is essential” for a direct generalisation like the main theorem, since “in the absence of a spectral gap, the images of the closed extensions of $d$, $\partial$, $\delbar$, and $\partial\delbar$ fail to be closed,” and it points to a weaker variant without a spectral gap given by the following theorem.

\begin{theorem}\label{theorem reduced l2 del delbar lemma}
Given a complete K\"ahler manifold $(M,g)$, in both the spaces $L^2\Lambda^k_\C$ and $L^2\Lambda^{p,q}$ the following equalities hold true
\begin{align*}
\c{\im \del\delbar_s}
&=\c{\im \del_s}\cap\ker\delbar_w=\c{\im \delbar_s}\cap\ker\del_w\\
&=(\c{\im\del_s}+\c{\im\delbar_s})\cap\ker\del_w\cap\ker\delbar_w\\
&=\c{\im d_s}\cap\ker\del_w\cap\ker\delbar_w.
\end{align*}
\end{theorem}

expanded_theorem:
\begin{theorem}\label{theorem l2 del delbar lemma}
    Let $(M,g)$ be a complete K\"ahler manifold such that $\Delta_{\delbar,sw}$ has a spectral gap in $L^2\Lambda^{k}_\C$. Given a smooth $L^2$-form $\alpha\in L^2A^k_\C$ which satisfies $\del\alpha=\delbar\alpha=0$, then the following conditions are equivalent:
    \begin{enumerate}
        \item $\alpha=\del\delbar\beta$, for $\beta\in L^2 A^{k-2}_\C$;
        \item $\alpha=\del\gamma$, for $\gamma\in L^2 A^{k-1}_\C$;
        \item $\alpha=\delbar\zeta$, for $\zeta\in L^2 A^{k-1}_\C$;
        \item $\alpha=\del\eta+\delbar\theta$, for $\eta,\theta\in L^2 A^{k-1}_\C$;
        \item $\alpha=d\lambda$, for $\lambda\in L^2 A^{k-1}_\C$.
    \end{enumerate}
\end{theorem}\label{theorem intro l2 del delbar lemma}
    Let $(M,g)$ be a complete K\"ahler manifold such that the self-adjoint Laplacian $\Delta$ has a spectral gap in $L^2\Lambda^{k}_\C$. Given a smooth $L^2$-form $\alpha\in L^2A^k_\C$ which satisfies $\partial\alpha=\delbar\alpha=0$, then the following conditions are equivalent:
    \begin{enumerate}
        \item $\alpha=\partial\delbar\beta$, for $\beta\in L^2 A^{k-2}_\C$;
        \item $\alpha=\partial\gamma$, for $\gamma\in L^2 A^{k-1}_\C$;
        \item $\alpha=\delbar\zeta$, for $\zeta\in L^2 A^{k-1}_\C$;
        \item $\alpha=\partial\eta+\delbar\theta$, for $\eta,\theta\in L^2 A^{k-1}_\C$;
        \item $\alpha=d\lambda$, for $\lambda\in L^2 A^{k-1}_\C$.
    \end{enumerate},

