\label{main_thm}
Let $\mathcal{H}\in (\frac{1}{3},1)$, and let the initial data $u_0^{\epsilon},v_0^\epsilon $ be divergence-free, of zero mean, and such that
\begin{align*}
   \sup_{\epsilon\in (0,1)} \|u_0^{\epsilon}\|_{L^2_x}+\|\sqrt{\epsilon}v_0^{\epsilon}\|_{L^2_x}<+\infty.
\end{align*}
Assume that the operators $Q$ and $C$ satisfy the conditions stated in \autoref{sec_hp_noise}. Then there exist probabilistically weak rough path solutions $(u^{\epsilon},(-C)^{-1}dW^{\mathcal{H},\epsilon})$ to \eqref{system_prelimit} that converge in law to a probabilistically weak rough path solution of \eqref{eq_Hgreat12} in the case $\alpha=1$ and $\mathcal{H}>\tfrac{1}{2}$, and to a probabilistically weak rough path solution of \eqref{eq_Hsmall12} in the case $\mathcal{H}<\tfrac{1}{2}$ and $\alpha=\tfrac{1}{2}+\mathcal{H}$.

ref_dict.def_rough_sol:
\begin{definition}\label{def_rough_sol}
    Let $\epsilon\in (0,1)$, $\frac1\H\in[N,N+1)\cap(1,3)$, $p\in (\frac{1}{\H},N+1)$ and assume $C,Q$ satisfy the condition of \autoref{sec_hp_noise}.\\
     A tuple $((\Omega^\epsilon, \mathcal{F}^\epsilon, (\mathcal{F}_t^\epsilon)_t,\mathbb{P}^{\epsilon}),W^{\epsilon}_t,u^\epsilon_t,r^\epsilon_t)$ is a probabilistically weak solution to equation \eqref{system_prelimit} if 
    \begin{enumerate}
        \item $(\Omega^\epsilon, \mathcal{F}^\epsilon, (\mathcal{F}_t^\epsilon)_t,\mathbb{P}^{\epsilon})$ is a stochastic basis with complete and right-continuous filtration,
        \item $W^{\epsilon,\H}_t$ is a fractional Wiener process of Hurst parameter $\H$ and space covariance $Q$ and it is adapted to $(\Omega^\epsilon, \mathcal{F}^\epsilon, \mathcal{F}_t^\epsilon,\mathbb{P}^{\epsilon})$,
        \item $r^\epsilon\in L^2([0,T],H^{\gamma})$ $\mathbb{P}^{\epsilon}$-a.s., it is progressively measurable and satisfies $\mathbb{P}^{\epsilon}$-a.s. 
       \begin{equation*}
       \begin{aligned}
    \partial_t r^{\epsilon}&=\epsilon^{-1}Cr^{\epsilon}+\nu \Delta(\epsilon^{-\beta}w^{\epsilon}+r^{\epsilon})\\&-b(u^{\epsilon}+\epsilon^{-\alpha+\H}w^{\epsilon}+r^{\epsilon},\epsilon^{-\alpha+\H}w^{\epsilon}+r^{\epsilon})
    \end{aligned}
       \end{equation*}
        in an analytically weak sense,
        \item $u^{\epsilon}\in L^{\infty}([0,T],L^2)\cap L^2([0,T],H^1)$ $\mathbb{P}^{\epsilon}$-a.s., it is progressively measurable and $\mathbb{P}^{\epsilon}$-a.s it holds, in a weak sense, 
        \begin{equation*}
            u^\epsilon\st=\int_s^t \Delta u^\epsilon_\theta-b(u_\theta^\epsilon+r^\epsilon_\theta,u^\epsilon_\theta)\,d\theta+\sum_{k=1}^N \mathbb{A}^{k,\epsilon}\st u_s^\epsilon+u^{\natural,\epsilon}\st,
        \end{equation*}
        where $u^{\natural}\st\in C^{p/(N+1)\var}_{2,loc}(H^{-3})$ $\mathbb{P}^{\epsilon}$-a.s.
    \end{enumerate}
    \end{definition}

