\subsection*{Case $\H>\frac{1}{2}$} 
The convergence in this final case is obtained by closely mirroring the proof from the preceding case.
The apriori estimates provided by \autoref{lemma_a_priori} combined with \autoref{proproughHgreat12} and the compactness criteria \cite[Lemma A.2]{hofmanova2019navier} imply that, in the case of \autoref{main_thm}, the family 
\begin{align*}
 (u^{\epsilon},r^{\epsilon}, W^\H,\mathbb{Y}^{\epsilon,1})
\end{align*}
is tight in the space
\begin{align*}
 \mathcal{X}&=\mathcal{X}_{u,r,W}\times\mathcal{X}_{RP},\\
 \mathcal{X}_{u,r,W}&=(C_w([0,T];H)\cap L^2(0,T;H))\times L^2((0,T)\times \T^3)_w\times C([0,T];H),\\
 \mathcal{X}_{RP}&= C^{p\var}([0,T];H^{\xi}).
\end{align*}
 Therefore, by Jakubowski–Skorokhod’s representation theorem, see for example \cite[Section 2.7]{breit2018stochastically}, there exists a subsequence of $\epsilon_k\rightarrow 0$ which for the matter of notation we continue to denote by $\epsilon$ and an auxiliary probability space $\left(\overline{\Omega},\overline{\mathcal{F}},\overline{\mathbb{P}}\right)$ with $\mathcal{X}$ valued random variables $\sx(\overline{u}^{\epsilon},\overline{r}^{\epsilon}, \overline{W}^{\H,\epsilon},\overline{\mathbb{Y}}^{\epsilon,1}\dx)$ and $\sx(\overline{u},\overline{r}, \overline{W}^{\H},\overline{\mathbb{Y}}^{1}\dx)$ such that 
\begin{align*}
 \sx(\overline{u}^{\epsilon},\overline{r}^{\epsilon}, \overline{W}^{\H,\epsilon},\overline{\mathbb{Y}}^{\epsilon,1}\dx)\stackrel{\mathcal{X}}{\rightarrow}\sx(\overline{u},\overline{r}, \overline{W}^{\H},\overline{\mathbb{Y}}^{1}\dx)\quad \overline{\mathbb{P}}-a.s..
\end{align*}
The convergence of all the terms as well as showing that the remainder $\overline{u}^{\sharp}\in C^{p/2\var}_{2,loc}(H^{-3})$ can be justified similarly to the previous case. Therefore, we need to identify $\overline{r}$ to conclude the proof of \autoref{main_thm}.
\begin{lemma}\label{identification_lemma_smoothcase}
 It holds
 \begin{align*}
 \overline{r}=0.
 \end{align*}
\end{lemma}
\begin{proof}
 Let us call by $\overline{w}^{\epsilon}$ the solution of 
 \begin{align*}
d\overline{w}^{\epsilon}=\epsilon^{-1}C\overline{w}^{\epsilon}\,dt+\epsilon^{- \H}d\overline{W}^{\H,\epsilon}_t.
 \end{align*}
 For each $\psi\in C^{1}_c(0,T)$ it holds due to \autoref{def_rough_sol}
 \begin{align*}
 \int_0^T \psi_t \overline{r}^{\epsilon}_t dt&=\epsilon^{2\H-1}\int_0^T \psi_t(-C)^{-1}b(\overline{w}^{\epsilon}_t,\overline{w}^{\epsilon}_t)dt\\ & +\epsilon^{\H}\int_0^T\psi_t (-C)^{-1}\left(A\overline{w}^{\epsilon}_t+b(\overline{u}^{\epsilon}_t,\overline{w}^{\epsilon}_t)+b(\overline{w}^{\epsilon}_t,\overline{r}^{\epsilon}_t)+b(\overline{r}^{\epsilon}_t,\overline{w}^{\epsilon}_t)\right)dt\\ & +\epsilon\int_0^T\psi(-C)^{-1}\left(A\overline{r}^{\epsilon}_t+b(\overline{u}^{\epsilon}_t,\overline{r}^{\epsilon}_t)+b(\overline{r}^{\epsilon}_t,\overline{r}^{\epsilon}_t)\right)dt+\epsilon\int_0^T \partial_t \psi_t (-C)^{-1}\overline{r}^{\epsilon}_t dt\\ & =J_1^{\epsilon}+J_2^{\epsilon}+J_3^{\epsilon}+J_4^{\epsilon}.
 \end{align*}
 We will show that, up to subsequences, all the terms approach $0$ in $H^{-\xi}$ $\overline{\mathbb{P}}-a.s.$ . This is enough to conclude by uniqueness of the limit. The treatment of $J_2^\epsilon,\ J_3^\epsilon,\ J_4^\epsilon$ follows verbatim as in the first case of \autoref{identification_lemma} and we omit details. To treat $J_1^\epsilon$ we argue in a simpler way compared to the first case of \autoref{identification_lemma}. Indeed since $\H>\frac{1}{2}$, it holds
 \begin{align*}
 \mathbb{E}\left[\|I_1^{\epsilon}\|_{H^{-\xi}}\right] \lesssim \epsilon^{2\H-1}\int_0^T\mathbb{E}\left[\|\overline{w}^{\epsilon}_t\|^2 \right]dt\rightarrow 0
 \end{align*}
 by \autoref{hp_stoch_conv}. This completes the proof.
\end{proof}
\begin{remark}
 For the sake of simplicity, we have reported estimates showing that $\overline{u}^{\sharp}\in C^{p/2\var}_{2,loc}(H^{-3})$. Nevertheless, we stress that by refining \eqref{stimaExtraURD} we could have shown that 
 $\overline{u}^{\sharp}\in C^{p/2\var}_{2,loc}(H^{-2})$ for $H\in (1/2,2/3]$ and $\overline{u}^{\sharp}\in C^{2p/(2p+1)\var}_{2,loc}(H^{-2})$ for $\H>2/3$. Therefore for all $\H\in (1/2,1)$, the integral term arising from the transport noise in the limiting equation can be constructed as a Young integral in $H^{-2}$ instead of $H^{-3}.$ 
\end{remark}
