$$
\end{lem}
\begin{proof}
We argue by contradiction. Assume that there exist $k\rightarrow+\infty$, $(\varphi_k,\psi_k)\in \bar{E}_k$ satisfying $\|\bar{L}(\varphi_k,\psi_k)\|=o(1)\|(\varphi_k,\psi_k)\|^2$.
Without loss of generality, we may assume $\|(\varphi_k,\psi_k)\|^2=k$, we have
\begin{align*}
\langle \bar{L}(\varphi_k,\psi_k),(g,h)\rangle=o(1)\|(\varphi_k,\psi_k)\|\|(g,h)\|.
\end{align*}
Taking $(g,h)=(\varphi_k,\psi_k)$, we have
\begin{align*}
o(k)=&\int_{\R^3}\epsilon^2|\nabla\varphi_k|^2+P(x)\varphi_k^2-3\mu_1\bar{S}_{\epsilon, k}^2\varphi_k^2+\int_{\R^3}\epsilon^2|\nabla\psi_k|^2+Q(x)\psi_k^2-3\mu_2\bar{T}_{\epsilon, k}^2\psi_k^2\cr
&-\beta\int_{\R^3}(\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon, k}^2\varphi_k^2+4\bar{S}_{\epsilon, k}\bar{T}_{\epsilon, k}\varphi_k\psi_k).
\end{align*}
For any fixed $R>0$, there is large enough $k>0$ such that $B_R(x_1)\subset\Omega_1$. Set
\begin{align*}
\tilde{\varphi}_k=\varphi_k(x+x^1),\,\,\,\tilde{\psi}_k=\psi_k(x+y^1).
\end{align*}
We have
\begin{align*}
\int_{B_R(0)}\epsilon^2|\nabla \tilde{\varphi}_k|^2+P(x)\tilde{\varphi}_k^2+\epsilon^2|\nabla\tilde{\psi}_k|^2+Q(x)\tilde{\psi}_k^2\leq1.
\end{align*}
Up to a subsequence, we may assume there exist $(\varphi,\psi)\in H^1(\R^3)\times H^1(\R^3)$ such that
\begin{align}\label{eq1.1}
&(\tilde{\varphi}_k,\tilde{\psi}_k)\rightharpoonup(\varphi,\psi)\,\,\, \hbox{weakly in }\, H_{loc}^1(\R^3)\times H_{loc}^1(\R^3),\cr
&(\tilde{\varphi}_k,\tilde{\psi}_k)\rightarrow(\varphi,\psi)\,\,\,\hbox{strongly in}\,L_{loc}^q(\R^3)\times L_{loc}^q(\R^3),q\in[2,6).
\end{align}

Moreover, in view of the non-degeneracy of $U_\epsilon$, it holds $\varphi=0$.
By \eqref{eq1.1}, we see
\begin{align*}
o(1)=\int_{B_R(0)}\tilde{\varphi}_k^qdx=\int_{B_R(x^1)}\varphi_k^qdx.
\end{align*}
Using the same argument on $\tilde{\Omega}$, we can prove that as $k\rightarrow+\infty$,
\begin{align}\label{3.3}
\tilde{\psi}_k\rightarrow0,\,\,\hbox{weakly in }\, H_{loc}^1(\R^3),\,\,\,\tilde{\psi}_k\rightarrow0,\,\,\,\hbox{strongly in} \,L_{loc}^2(\R^3).
\end{align}
As a result, it holds
\begin{align*}
\int_{B_R(x^1)}\varphi^2=o(1),\,\,\,\,\,\,\int_{B_R(y^1)}\psi^2=o(1), \forall\,\,\,R>0.
\end{align*}
Similar as Lemma \ref{lm2.2}, we get
\begin{align*}
\Big(\int_{B_R(0)}\varphi_k^qdx\Big)^{\frac{1}{q}}=o(\sqrt{k}).
\end{align*}
Then we find
\begin{align}\label{eqs33}
o(k)=&\int_{\R^3}\epsilon^2|\nabla\varphi_k|^2+P(x)\varphi_k^2-3\mu_1\bar{S}_{\epsilon, k}^2\varphi_k^2+\int_{\R^3}\epsilon^2|\nabla\psi_k|^2+Q(x)\psi_k^2-3\mu_2\bar{T}_{\epsilon, k}^2\psi_k^2\cr
