expanded_sketch:
At a conceptual level, the proof of the main theorem (and the following theorem) “follow the strategy of \cite{CM10} in the bounded-curvature regime”: when two embedded minimal sheets are “very close but disjoint,” their “separation function satisfies a uniformly elliptic equation whose coefficients are controlled by \(|A|\)”; then “a Harnack inequality” gives “quantitative control on how fast the sheets can separate.” We first prove the following theorem.

\begin{mainthm}\label{thm:unbounded}
Let \(\Sigma^{n} \subset \mathbb{R}^{n+1}\) be a complete, embedded minimal hypersurface and assume that \(\sup_{\Sigma}|A|^2 < \infty\). Then \(\Sigma\) is unbounded.
\end{mainthm}

ref_dict.thm:subextension:
\begin{thm} \label{thm:subextension} 
Let $f \in W^*(B(0,1))$ be such that $f\leq -1$. Assume $\|f\|_*\leq 1$. Let $\veps>0$  and $0<s<1$. Then, there exists $u \in \cL(\bC^n)$ such that $u\leq -|f^\star|^{\frac{2}{n}-\veps}$ on $B(0,s)$ everywhere.
\end{thm}

ref_dict.lem:cap-sublevel-set:
\begin{lem}\label{lem:cap-sublevel-set} Let $f\in W^*(\Om) \cap C^0(\Om)$.  Assume either $f\geq 0$ or $f\leq 0$ on $\Om$. Denote $E_s = \{z\in \Om: |f(z)| > s\}$ for $s > 0$. Then,
\[\label{eq:c-sublevel-set-est}
	\tc (E_s) \leq \frac{1}{s^2} \|f\|_*^2.
\]
\end{lem}

ref_dict.prop:density:
\begin{prop} \label{prop:density} Let $\Om\subset \bC^n$ be a bounded domain. 
\begin{itemize}
\item[(a)] If $n=1$, then $W^*(\Om) = W^{1,2}(\Om)$ together with its Sobolev norm. 
\item[(b)] If $n\geq 2$, then the continuous functions in $C^0(\Om) \cap W^*(\Om)$ are not dense in $W^*(\Om)$ with respect to $W^*$-norm. 
\end{itemize}
\end{prop}

ref_dict.thm:star-norm:
\begin{thm}\label{thm:star-norm} Let $\Om$ be a bounded domain in $\bC^n$.
\begin{itemize}
\item[(a)]  $\| \cdot\|_*$ is a norm in $W^*(\Om)$ and $\| \cdot \|_{W^{1,2}(\Om)} \leq \|\cdot \|_*$.
\item[(b)] $W^*(\Om)$ and $W^*_0(\Om)$ are Banach spaces with this norm.
\end{itemize}
\end{thm}

ref_dict.cor:FO-polar:
\begin{cor} \label{cor:FO-polar}
Let $E\subset \Om$ be a Borel subset. Then, $cap (E) =0$ if  and only if $\tc_\te(E) =0$ for all $\te $ of the form \eqref{eq:current-te} with $0<\de \leq 1$.
\end{cor}

ref_dict.thMain:
\begin{theorem} \label{thMain}
There exist constants $\delta, \eps > 0$ and a sequence of finite groups $(G_n)_{n \geq 1}$ with $|G_n| \to \infty$
with bounded-size generating sets $X_n, Y_n \subseteq G_n$ such that
\begin{enumerate}[\normalfont(a)]
    \item $\Cay(G_n,X_n)$ are $\eps$-expander graphs, and
    \item $\diam( \Cay(G_n,Y_n) ) \geq \exp(\delta \sqrt{\log|G_n|})$.
\end{enumerate}
\end{theorem}

theorem.content:
\label{theo.finite.top}
For fixed $n\,,m \in \mathbb{Z}^+\,,n \geqslant 3\,, m \geq1\,,$ and $ \Gamma \, ,\Lambda \in \mathbb{R} \,,  \Gamma\,,\Lambda \geqslant 0\,$, there exists $N = N(n,m,\Gamma,\Lambda) \in \mathbb{N}$ so that there are at most $N$ mutually non-diffeomorphic complete immersed minimal submanifolds $M^n$ in $\mathbb{R}^{n+m}$ satisfying that  $\int_{M} \lvertA\rvert^{n}d\mu_M  \leqslant \Gamma$ and 
$\vol_M ( B_R(0)) \leqslant  \Lambda R^n$ for any $R>0\,.$

ref_dict.theo.finite.top:
\begin{theo} \label{theo.finite.top}
For fixed $n\,,m \in \ZZ^+\,,n \geq 3\,, m \geq1\,,$ and $ \Gamma \, ,\Lambda \in \RR \,,  \Gamma\,,\Lambda \geq 0\,$, there exists $N = N(n,m,\Gamma,\Lambda) \in \NN$ so that there are at most $N$ mutually non-diffeomorphic complete immersed minimal submanifolds $M^n$ in $\RR^{n+m}$ satisfying that  $\int_{M} \abs{A}^{n}d\mu_M  \leq \Gamma$ and 
$\vol_M ( B_R(0)) \leq  \Lambda R^n$ for any $R>0\,.$
\end{theo}

ref_dict.lemm.Annular.composition:
\begin{lemm}[Annular decomposition] \label{lemm.Annular.composition}
For fixed $n\,,m\in \ZZ^+\,,n\geq 2\,,$ there is a $0 < \sigma_0 <\fh{1}{2} $ only depending on $n,m$ with the following property. Suppose that $M^n(\iota : M^n \to \bar{B_2(0)} \subset\RR^{n+m})$ is a complete properly immersed submanifold  with $\iota(\de M)  \subset \de B_2(0)\, . $ Assume that for some $\sigma \leq \sigma_0$ and $p \in B_{\sigma_0}(0)\,,$ we have:
\begin{enumerate}[itemsep=5pt, topsep=5pt]
\item For each component $M'$ of $M\,,$ $M' \cap B_{\sigma}(p) \neq \emptyset \,$.
\item The immersed submanifold $M$ intersects $\de B_{\sigma}(p)$ transversely, and $M \cap \de B_{\sigma}(p)$ has $k$ components. Moreover, each component of   $M \cap \de B_{\sigma}(p)$ is diffeomorphic to $\SS^{n-1}$ with the standard smooth structure.
\item The second fundamental form of $M$ satisfies $|A|(x)|\iota(x)-p| \leq \fh{1}{4} $ for all $x \in M \cap \left( \overline{B_{1}(0)} \setminus B_{\sigma}(p) \right)\,.$
\end{enumerate}
Then, $M$ intersects $\de B_{1}(0)$ transversely. Both  $M \cap \left(\overline{B_{1}(0)}\setminus {B_{\sigma}(p)}\right)$ and  $M \cap \de B_{1}(0)$  have $k$ components. Moreover, each component of   $M \cap \de B_{1}(0)$ is diffeomorphic to $\SS^{n-1}$ with the standard smooth structure and
 each component of $M \cap \left(\overline{B_{1}(0)}\setminus {B_{\sigma}(p)}\right)$ is diffeomorphic to $\SS^{n-1}\times [0,1]$ with the standard smooth structure.
\end{lemm}

ref_dict.lemm:curv.est:
\begin{lemm}\label{lemm:curv.est}
For fixed $I \in \ZZ^+,0 <r_0<R_0< \infty\,,$ suppose that $M_j( \iota_j :M_{j} \to  \RR^{n+m})$ is a sequence of $n$-dimensional complete properly immersed minimal submanifolds with nonempty boundary and $\iota_j(M_j) \subset B_{R_0}(0)$ such that $ \int_{M_j} \abs{A_{M_j}}^n d\mu_{M_j} < IK_0 , \limsup \limits_{j\to \infty}\nu_j(B_{R_0}(0)\setminus B_{\fh{r_0}{2}}(0))< K_0$ and $\vol(B_R(q)) \leq \Lambda R^n$ for any $B_R(q) \subset B_{R_0}(0)$. Then, after passing to a subsequence, we have:
\begin{enumerate}[itemsep=5pt, topsep=5pt]
    \item There exist $C>0$ and a sequence of smooth blow-up sets $\cB_{j} \subset M_{j}$  so that 
\begin{equation} \label{eq:seq.cur.esti}
    |A_{M_{j}}|(x)d(\iota_j(x),\iota_j(\cB_{j} \cup \de M_j) ) \leq C\, , \ |\cB_{j}|< I\, , \ \iota_j(\cB_j) \subset B_{\fh{3}{4}r_0}(0)\, ,
\end{equation}
for all $x \in M_{j}\,.$ 
\item  $\iota_j(\cB_j)$ converges to $ \widetilde  \cB_ \infty \subset \RR^{n+m}$ in the Hausdorff distance sense and  the Radon measure $\nu_j$ converges to $ \nu_\infty$ in the Radon measure sense with $\nu_\infty(p_\infty)\geq 2K_0$ for any $p_\infty \in \widetilde \cB_\infty\,.$
\end{enumerate}
\end{lemm}

ref_dict.prop.diffeo:
\begin{theo} \label{prop.diffeo}
Given a sequence $M_{j}$ satisfying \hyperlink{defi:beth}{$(\beth)$} and each $M_j$  intersects $\partial B_{1}(0)$ transversely. By passing to a subsequence, all of the $M_{j}\cap B_{1}(0)$ are diffeomorphic. 
\end{theo}

post_theorem_intro_text:
Our proof is inspired by the ideas in \cite{Chodosh17}, but we need further research in some situations. For instance, one point of concentration is a plane in  Proposition 7.1 of \cite{Chodosh17}, while in our situation it may be a non-flat minimal submanifold with finite total curvature. In Theorem \ref{prop.diffeo}, we can resolve it by an induction argument on the total curvature.

\subsection{Outline of the paper} 
\begin{itemize}
    \item In \S \ref{sec.pre}, we state several definitions
 and curvature estimates for minimal submanifolds which are needed in the following. 
 \item  In \S \ref{sec.geo}, we describe the geometry of ends of complete immersed minimal submanifolds in $\mathbb{R}^{n+m}$ with finite total curvature, enlightened by \cite{schocen} and \cite{anderson1984compactification}. 
This helps us to derive  curvature estimates away from finitely many points in Lemma \ref{lemm:curv.est}.
 \item In \S \ref{sec.top}, we prove a key topological result in Lemma \ref{lemm.Annular.composition} allowing us to control the topology of the “intermediate regions”,
then combined the curvature estimates in \S \ref{sec.geo} we can prove Theorem \ref{theo.finite.top} by an induction argument on the total curvature.
\end{itemize}

expanded_sketch:
The proof is “inspired by the ideas in \cite{Chodosh17},” but differs because “in our situation [a concentration point] may be a non-flat minimal submanifold with finite total curvature” (rather than a plane as in Proposition 7.1 of \cite{Chodosh17}). This issue is resolved “by an induction argument on the total curvature,” using the following theorem:

\begin{theo} \label{prop.diffeo}
Given a sequence $M_{j}$ satisfying \hyperlink{defi:beth}{$(\beth)$} and each $M_j$  intersects $\partial B_{1}(0)$ transversely. By passing to a subsequence, all of the $M_{j}\cap B_{1}(0)$ are diffeomorphic. 
\end{theo}

The stated structure to prove the main theorem is:
\begin{itemize}
\item Develop “definitions and curvature estimates for minimal submanifolds” next.
\item After that, “describe the geometry of ends of complete immersed minimal submanifolds in $\mathbb{R}^{n+m}$ with finite total curvature,” which “helps us to derive curvature estimates away from finitely many points” in the following lemma.

\begin{lemm}\label{lemm:curv.est}
For fixed $I \in \ZZ^+,0 <r_0<R_0< \infty\,,$ suppose that $M_j( \iota_j :M_{j} \to  \RR^{n+m})$ is a sequence of $n$-dimensional complete properly immersed minimal submanifolds with nonempty boundary and $\iota_j(M_j) \subset B_{R_0}(0)$ such that $ \int_{M_j} \abs{A_{M_j}}^n d\mu_{M_j} < IK_0 , \limsup \limits_{j\to \infty}\nu_j(B_{R_0}(0)\setminus B_{\fh{r_0}{2}}(0))< K_0$ and $\vol(B_R(q)) \leq \Lambda R^n$ for any $B_R(q) \subset B_{R_0}(0)$. Then, after passing to a subsequence, we have:
\begin{enumerate}[itemsep=5pt, topsep=5pt]
    \item There exist $C>0$ and a sequence of smooth blow-up sets $\cB_{j} \subset M_{j}$  so that 
\begin{equation} \label{eq:seq.cur.esti}
    |A_{M_{j}}|(x)d(\iota_j(x),\iota_j(\cB_{j} \cup \de M_j) ) \leq C\, , \ |\cB_{j}|< I\, , \ \iota_j(\cB_j) \subset B_{\fh{3}{4}r_0}(0)\, ,
\end{equation}
for all $x \in M_{j}\,.$ 
\item  $\iota_j(\cB_j)$ converges to $ \widetilde  \cB_ \infty \subset \RR^{n+m}$ in the Hausdorff distance sense and  the Radon measure $\nu_j$ converges to $ \nu_\infty$ in the Radon measure sense with $\nu_\infty(p_\infty)\geq 2K_0$ for any $p_\infty \in \widetilde \cB_\infty\,.$
\end{enumerate}
\end{lemm}

\item Next, prove “a key topological result” in the following lemma, allowing control of the topology of the \lq intermediate regions\rq.

\begin{lemm}[Annular decomposition] \label{lemm.Annular.composition}
For fixed $n\,,m\in \ZZ^+\,,n\geq 2\,,$ there is a $0 < \sigma_0 <\fh{1}{2} $ only depending on $n,m$ with the following property. Suppose that $M^n(\iota : M^n \to \bar{B_2(0)} \subset\RR^{n+m})$ is a complete properly immersed submanifold  with $\iota(\de M)  \subset \de B_2(0)\, . $ Assume that for some $\sigma \leq \sigma_0$ and $p \in B_{\sigma_0}(0)\,,$ we have:
\begin{enumerate}[itemsep=5pt, topsep=5pt]
\item For each component $M'$ of $M\,,$ $M' \cap B_{\sigma}(p) \neq \emptyset \,$.
\item The immersed submanifold $M$ intersects $\de B_{\sigma}(p)$ transversely, and $M \cap \de B_{\sigma}(p)$ has $k$ components. Moreover, each component of   $M \cap \de B_{\sigma}(p)$ is diffeomorphic to $\SS^{n-1}$ with the standard smooth structure.
\item The second fundamental form of $M$ satisfies $|A|(x)|\iota(x)-p| \leq \fh{1}{4} $ for all $x \in M \cap \left( \overline{B_{1}(0)} \setminus B_{\sigma}(p) \right)\,.$
\end{enumerate}
Then, $M$ intersects $\de B_{1}(0)$ transversely. Both  $M \cap \left(\overline{B_{1}(0)}\setminus {B_{\sigma}(p)}\right)$ and  $M \cap \de B_{1}(0)$  have $k$ components. Moreover, each component of   $M \cap \de B_{1}(0)$ is diffeomorphic to $\SS^{n-1}$ with the standard smooth structure and
 each component of $M \cap \left(\overline{B_{1}(0)}\setminus {B_{\sigma}(p)}\right)$ is diffeomorphic to $\SS^{n-1}\times [0,1]$ with the standard smooth structure.
\end{lemm}

Combined with the curvature estimates proved earlier, this yields an induction argument on the total curvature, completing the proof of the main theorem.
\end{itemize}

