theorem.content:
[Volume and circumference]\label{thm:vol-circumference}
Let $M$ be a closed hyperbolic $3$-manifold with a pseudo-Anosov flow $\varphi$. Let $S$ be a closed connected surface in $M$ that is almost transverse to $\varphi$, but is not a fiber. Let $c^{s/u}$ be the stable/unstable multicurves of $S$. Assume that $\mathfrak{c}(M\backslash \!\! \backslash S)<\infty$.

There is a constant $k_S = k_S(\chi(S)) \ge 1$, depending only on $\chi(S)$, and a constant $k_{M \backslash \!\! \backslash S} \ge 1$, depending only on $\chi(S)$ and $\mathfrak c(M\backslash \!\! \backslash S)$, so that the following inequalities hold:
\begin{enumerate}
\item $d_{\mathcal{C}(S)}(c^s, c^u) \le k_S \cdot \mathrm{vol}(M) + k_{M\backslash \!\! \backslash S}$, and 
\smallskip
\item $d_{\mathcal{C}(S)}(c^s, c^u) \le k_S \cdot \ell_M(\gamma) + k_{M \backslash \!\! \backslash S}$, where $\gamma$ is any closed geodesic that intersects $S$ essentially and $\ell_M(\gamma)$ is its length in $M$.
\end{enumerate}

ref_dict.th:vol:
\begin{theorem}[Volume]\label{th:vol}
Let $M$ be a closed hyperbolic $3$-manifold, $\varphi$ an almost pseudo-Anosov flow on $M$, and $S$ a closed surface that is transverse to $\varphi$ but not a fiber.
Then
\[
d_{\C(S)}(c^s, c^u) \prec \vol(M) + D_{M\cut S}
\]
\end{theorem}

ref_dict.thm:short-curves:
\begin{thm}[Short curves]\label{thm:short-curves}
Let $M$ be a closed hyperbolic $3$-manifold with a pseudo-Anosov flow $\varphi$. Let $S$ be a closed surface in $M$ that is almost transverse to $\varphi$ and let $Y \subset S$ be a 
subsurface of $S$. Assume that $\mathfrak{c}(M\cut S)<\infty$. Then for any $\epsilon >0$, there is a $K = K(\epsilon, \chi(S)) \ge 0$, depending only on $\epsilon$ and $\chi(S)$, such that if
\begin{itemize}
\item $d_{\C(S)}(c^{s/u} ,\partial Y) \ge k_{M\cut S}$ and 
\item $d_{\C(Y)}(c^s,c^u) \ge K + 2 \cdot  k_{M \cut S}$,
\end{itemize}
then 
\[
\ell_M(\partial Y) \le \epsilon.
\]
\end{thm}

ref_dict.cor:finitedepth:
\begin{theorem}[Junctures and geometry]\label{cor:finitedepth}
Let $M$ be a closed hyperbolic $3$-manifold with a finite depth foliation $\mc F$ so that $\mc F^0$ is a connected surface $S$. Suppose that $j^\pm  \subset S$ are minimal juncture on $S$.

There is a constant $c_S = c_S(\chi(S)) \ge 1$, depending only on $\chi(S)$, and a constant $D\ge 1$, depending only on $\chi(S)$ and $\mathfrak{c}_{\FF}$, so that the following inequalities hold:
\begin{enumerate}
\item $d_{\C(S)}(j^-, j^+) \le c_S \cdot \vol(M) + D$, and 
\smallskip
\item $d_{\C(S)}(j^-, j^+) \le c_S \cdot \ell_M(\gamma) + D$, where $\gamma$ is any closed geodesic that intersects $S$ essentially and $\ell_M(\gamma)$ is its length in $M$.
\end{enumerate}
\end{theorem}

ref_dict.th:short_curves:
\begin{theorem}[Short curves] \label{th:short_curves}
Let $M$ be a closed hyperbolic $3$-manifold with an almost pseudo-Anosov flow $\varphi$. Let $S$ be a closed surface in $M$ that is transverse to $\varphi$ and let $Y \subset S$ be a 
subsurface of $S$. Then for any $\epsilon >0$, there is a $K = K(\epsilon, \chi(S)) \ge 0$, depending only on $\epsilon$ and $\chi(S)$, such that if
\begin{itemize}
\item $d_{\C(S)}(c^{s/u} ,\partial Y) \ge 2D_{M\cut S}+2$ and 
\item $d_{\C(Y)}(c^s,c^u) \ge K + 4 \cdot  D_{M \cut S}$,
\end{itemize}
then 
\[
\ell_M(\partial Y) \le \epsilon.
\]
\end{theorem}

ref_dict.prop:bounded_length:
\begin{proposition}\label{prop:bounded_length}
There are constants $L, d \ge 1$, depending on $|\chi(S)|$ and $\mf c(M \cut S)$, and curves $\alpha$ and $\beta$ in $\C(S)$ such that: 
\begin{itemize}
\item the lengths of the geodesic representatives of $\alpha$ and $\beta$ in $M$ are no more than $L$, and 
\item the intersection numbers $i(c^s, \alpha)$ and $i(c^u, \beta)$ are no more than $d$. 
\end{itemize}
\end{proposition}

ref_dict.thm:vol-circumference:
\begin{thm}[Volume and circumference]\label{thm:vol-circumference}
Let $M$ be a closed hyperbolic $3$-manifold with a pseudo-Anosov flow $\varphi$. Let $S$ be a closed connected surface in $M$ that is almost transverse to $\varphi$, but is not a fiber. Let $c^{s/u}$ be the stable/unstable multicurves of $S$. Assume that $\mathfrak{c}(M\cut S)<\infty$.

There is a constant $k_S = k_S(\chi(S)) \ge 1$, depending only on $\chi(S)$, and a constant $k_{M \cut S} \ge 1$, depending only on $\chi(S)$ and $\mf c(M\cut S)$, so that the following inequalities hold:
\begin{enumerate}
\item $d_{\C(S)}(c^s, c^u) \le k_S \cdot \vol(M) + k_{M\cut S}$, and 
\smallskip
\item $d_{\C(S)}(c^s, c^u) \le k_S \cdot \ell_M(\gamma) + k_{M \cut S}$, where $\gamma$ is any closed geodesic that intersects $S$ essentially and $\ell_M(\gamma)$ is its length in $M$.
\end{enumerate}
\end{thm}

full_context:
\label{sec:intro}
Let $M$ be a closed hyperbolic $3$--manifold and let $\varphi$ be a pseudo-Anosov flow on $M$. The purpose of this paper is to quantify how dynamical properties of $\varphi$ influence the geometry of $M$ through the curve graph of a closed embedded surface $S\subset M$ that is (almost) transverse to $\varphi$.

\smallskip
The prototypical example is where $S$ is a cross section of $\varphi$ (i.e. $S$ is transverse to $\varphi$ and intersects every orbit), and hence $M$ fibers over the circle with $S$ as a fiber. In this setting, the restriction of the stable/unstable foliations of $\varphi$ to $S$ are precisely the end invariants of the cover $\widetilde M_S$ of $\widetilde M$ associated to $S$. Hence, by the resolution of Thurston's Ending Lamination Conjecture, proven by Minsky \cite{ECL1} and Brock--Canary--Minsky \cite{ELC2}, the hyperbolic structure on $\widetilde M_S$ is totally determined by these dynamical/geometric invariants. In fact, geometric quantities like the volume of $M$ \cite{Brock2}, the circumference of $M$ \cite{biringer2019ranks, aougab2022covers}, and the location of short geodesics \cite{minsky2001bounded, viaggi2025effective} are each coarsely determined (up to constants depending only on $\chi(S)$) by combinatorial quantities that are organized by the curve graph of $S$ and its subsurfaces.

Let $M$ be a closed hyperbolic $3$--manifold, let $\varphi$ be an almost pseudo-Anosov flow on $M$, and let $S$ be a connected surface embedded in $M$ that is transverse to $\varphi$.
 The intersections of $S$ with the invariant stable/unstable foliations $\mathcal F^{s/u}$ of $\varphi$ are a pair of singular foliations $\mathcal F_S^{s/u}$ of $S$. When $S$ is not a fiber surface (or more precisely, not a cross section of $\varphi$), the foliations $\mathcal F_S^{s/u}$ each contain a nonempty set of closed leaves $c^{s/u}$ (see \Cref{sec:transvese_shadow}). 
The pair $c^{s/u}$ are essential multicurves on $S$,
which we call the \emph{stable/unstable multicurves} of $S$.

Recall that $M\backslash \!\! \backslash S$ denotes the manifold obtained by cutting $M$ along $S$. Its boundary is a disjoint union $\partial_- (M \backslash \!\! \backslash S) \sqcup \partial_+ (M \backslash \!\! \backslash S)$, where the flow points into, or out of, $M\backslash \!\! \backslash S$ respectively. A \emph{product annulus} in $M \backslash \!\! \backslash S$ is an essential properly embedded annulus that has one boundary component on each of $\partial_-(M\backslash \!\! \backslash S)$ and $\partial_+(M\backslash \!\! \backslash S)$.
Define the \emph{core complexity} of $M\backslash \!\! \backslash S$ to be 
\begin{align*}
\mathfrak{c}(M\backslash \!\! \backslash S) = 
\begin{cases}
0, & M\backslash \!\! \backslash S \text{ contains a product annulus},\\
\min{-\chi(\Sigma)}, & \text{otherwise},
\end{cases}
\end{align*}
where the min is over all properly embedded surfaces $\Sigma$ in $M\backslash \!\! \backslash S$ that are transverse to (a dynamic blowup of) $\varphi$ and which meet both $\partial_+ (M \backslash \!\! \backslash S)$ and $\partial_- (M\backslash \!\! \backslash S)$. Dynamic blowups and almost pseudo-Anosov flows are defined in \Cref{sec:pA}.
For context, $\mathfrak{c}(M\backslash \!\! \backslash S)$ contributes to an \emph{additive} error term in our theorems that relate geometry and dynamics. We note that $\mathfrak{c}(M\backslash \!\! \backslash S)< \infty$ when $\varphi$ is a suspension flow (i.e. $\varphi$ admits a cross section) or more generally when $S$ is a leaf of a (almost) transverse finite depth foliation (see \Cref{sec:examples}).
A cohomological characterization of when $\mathfrak{c}(M\backslash \!\! \backslash S)< \infty$ will be subject of forthcoming work \cite{HT_depthone}.

\smallskip

Our first main theorem relates the curve graph distance between $c^u$ and $c^s$ to the volume and circumference of $M$. See \Cref{th:vol} and \Cref{th:circum}, respectively.

\begin{theorem}[Circumference]
\label{th:circum}
Let $M$ be a closed hyperbolic $3$-manifold, $\varphi$ an almost pseudo-Anosov flow on $M$, and $S$ a closed surface that is transverse to $\varphi$ but not a fiber. Then there is a constant $D \ge 0$, depending only on $|\chi(S)|$ and $\mf c(M\cut S)$, so that 
\[
d_{\C(S)}(c^s, c^u) \prec  \ell(\gamma) + D,
\]
 where $\gamma$ is any closed geodesic that intersects $S$ essentially.
\end{theorem}

\begin{theorem}[Volume]\label{th:vol}
Let $M$ be a closed hyperbolic $3$-manifold, $\varphi$ an almost pseudo-Anosov flow on $M$, and $S$ a closed surface that is transverse to $\varphi$ but not a fiber.
Then
\[
d_{\C(S)}(c^s, c^u) \prec \vol(M) + D_{M\cut S}
\]
\end{theorem}

\smallskip
The prototypical example is where $S$ is a cross section of $\varphi$ (i.e. $S$ is transverse to $\varphi$ and intersects every orbit), and hence $M$ fibers over the circle with $S$ as a fiber. In this setting, the restriction of the stable/unstable foliations of $\varphi$ to $S$ are precisely the end invariants of the cover $\wt M_S$ of $\wt M$ associated to $S$. Hence, by the resolution of Thurston's Ending Lamination Conjecture, proven by Minsky \cite{ECL1} and Brock--Canary--Minsky \cite{ELC2}, the hyperbolic structure on $\wt M_S$ is totally determined by these dynamical/geometric invariants. In fact, geometric quantities like the volume of $M$ \cite{Brock2}, the circumference of $M$ \cite{biringer2019ranks, aougab2022covers}, and the location of short geodesics \cite{minsky2001bounded, viaggi2025effective} are each coarsely determined (up to constants depending only on $\chi(S)$) by combinatorial quantities that are organized by the curve graph of $S$ and its subsurfaces.

Our first main theorem relates the curve graph distance between $c^u$ and $c^s$ to the volume and circumference of $M$. See \Cref{th:vol} and \Cref{th:circum}, respectively.

We remark that when $M\cut S$ contains a product annulus, $\mf c(M\cut S) = 0$ and so the constants in \Cref{thm:vol-circumference} depend only on $\vert \chi(S) \vert$.

\begin{thm}[Short curves]\label{thm:short-curves}
Let $M$ be a closed hyperbolic $3$-manifold with a pseudo-Anosov flow $\varphi$. Let $S$ be a closed surface in $M$ that is almost transverse to $\varphi$ and let $Y \subset S$ be a 
subsurface of $S$. Assume that $\mathfrak{c}(M\cut S)<\infty$. Then for any $\epsilon >0$, there is a $K = K(\epsilon, \chi(S)) \ge 0$, depending only on $\epsilon$ and $\chi(S)$, such that if
\begin{itemize}
\item $d_{\C(S)}(c^{s/u} ,\partial Y) \ge k_{M\cut S}$ and 
\item $d_{\C(Y)}(c^s,c^u) \ge K + 2 \cdot k_{M \cut S}$,
\end{itemize}
then 
\[
\ell_M(\partial Y) \le \epsilon.
\]
\end{thm}

\begin{theorem}[Volume]\label{th:vol}
Let $M$ be a closed hyperbolic $3$-manifold, $\varphi$ an almost pseudo-Anosov flow on $M$, and $S$ a closed surface that is transverse to $\varphi$ but not a fiber.
Then
\[
d_{\C(S)}(c^s, c^u) \prec \vol(M) + D_{M\cut S}
\]
\end{theorem}

\begin{theorem}[Circumference]
\label{th:circum}
Let $M$ be a closed hyperbolic $3$-manifold, $\varphi$ an almost pseudo-Anosov flow on $M$, and $S$ a closed surface that is transverse to $\varphi$ but not a fiber. Then there is a constant $D \ge 0$, depending only on $|\chi(S)|$ and $\mf c(M\cut S)$, so that 
\[
d_{\C(S)}(c^s, c^u) \prec \ell(\gamma) + D,
\]
 where $\gamma$ is any closed geodesic that intersects $S$ essentially.
\end{theorem}

\subsection{Short curves}
Finally, we give a short proof of the following:
\begin{theorem}[Short curves] \label{th:short_curves}
Let $M$ be a closed hyperbolic $3$-manifold with an almost pseudo-Anosov flow $\varphi$. Let $S$ be a closed surface in $M$ that is transverse to $\varphi$ and let $Y \subset S$ be a 
subsurface of $S$. Then for any $\epsilon >0$, there is a $K = K(\epsilon, \chi(S)) \ge 0$, depending only on $\epsilon$ and $\chi(S)$, such that if
\begin{itemize}
\item $d_{\C(S)}(c^{s/u} ,\partial Y) \ge 2D_{M\cut S}+2$ and 
\item $d_{\C(Y)}(c^s,c^u) \ge K + 4 \cdot D_{M \cut S}$,
\end{itemize}
then 
\[
\ell_M(\partial Y) \le \epsilon.
\]
\end{theorem}

There is a constant $c_S = c_S(\chi(S)) \ge 1$, depending only on $\chi(S)$, and a constant $D\ge 1$, depending only on $\chi(S)$ and $\mathfrak{c}_{\FF}$, so that the following inequalities hold:
\begin{enumerate}
\item $d_{\C(S)}(j^-, j^+) \le c_S \cdot \vol(M) + D$, and 
\smallskip
\item $d_{\C(S)}(j^-, j^+) \le c_S \cdot \ell_M(\gamma) + D$, where $\gamma$ is any closed geodesic that intersects $S$ essentially and $\ell_M(\gamma)$ is its length in $M$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Circumference]
\label{th:circum}
Let $M$ be a closed hyperbolic $3$-manifold, $\varphi$ an almost pseudo-Anosov flow on $M$, and $S$ a closed surface that is transverse to $\varphi$ but not a fiber. Then there is a constant $D \ge 0$, depending only on $|\chi(S)|$ and $\mf c(M\cut S)$, so that 
\[
d_{\C(S)}(c^s, c^u) \prec  \ell(\gamma) + D,
\]
 where $\gamma$ is any closed geodesic that intersects $S$ essentially.
\end{theorem}

\begin{thm}[Volume and circumference]\label{thm:vol-circumference}
Let $M$ be a closed hyperbolic $3$-manifold with a pseudo-Anosov flow $\varphi$. Let $S$ be a closed connected surface in $M$ that is almost transverse to $\varphi$, but is not a fiber. Let $c^{s/u}$ be the stable/unstable multicurves of $S$. Assume that $\mathfrak{c}(M\cut S)<\infty$.

There is a constant $k_S = k_S(\chi(S)) \ge 1$, depending only on $\chi(S)$, and a constant $k_{M \cut S} \ge 1$, depending only on $\chi(S)$ and $\mf c(M\cut S)$, so that the following inequalities hold:
\begin{enumerate}
\item $d_{\C(S)}(c^s, c^u) \le k_S \cdot \vol(M) + k_{M\cut S}$, and 
\smallskip
\item $d_{\C(S)}(c^s, c^u) \le k_S \cdot \ell_M(\gamma) + k_{M \cut S}$, where $\gamma$ is any closed geodesic that intersects $S$ essentially and $\ell_M(\gamma)$ is its length in $M$.
\end{enumerate}
\end{thm}

