\section{Preliminaries}\label{sec:2}
\subsection{Auxiliary Analysis Tools}\label{sec:2.1}
In this subsection, we introduce two key lemmas needed later. The first one is
\begin{lemma}\cite{nonuniform-2010-cmp-himonas}\label{phi-cmp-2010}
 Let $\sigma \geq 0, \delta\geq 0, a\in \mr$ and $\lambda\gg 1$. For any Schwartz function $\psi\in \mathcal{S}(\mr)$, it holds that
 \begin{align*}
 \lambda^{\delta/2}\left\|\psi\right\|_{L^2(\mathbb{R})}\leq\left\|\psi\left(\frac{\cdot}{\lambda^\delta}\right)\right\|_{H^\sigma(\mathbb{R})}\leq\lambda^{\delta/2}\left\|\psi\right\|_{H^\sigma(\mathbb{R})},
 \end{align*}
and \begin{align}\label{622}
 \left\|\psi\left(\frac{\cdot}{\lambda^\delta}\right)\cos(\lambda\cdot-a)\right\|_{H^\sigma(\mathbb{R})}\simeq\lambda^{\sigma+\delta/2}\|\psi\|_{L^2(\mathbb{R})}.
\end{align}
Moreover, \eqref{622} holds true if $\cos(\lambda \cdot-a)$ is replaced by $\sin(\lambda \cdot-a)$.
\end{lemma}

\subsection{Approximate Solutions Scheme}\label{sec:3.1}
We begin by constructing two sequences of approximate solutions $b^{w,\lambda}$ and $u^{w,\lambda}$ with $w=\pm 1$, where $b^{w,\lambda}$ contains low frequencies only and $u^{w,\lambda}$ contain both high and low frequencies. More precisely, we set
\begin{align}\label{u-low+high}
 u^{w,\lambda}(x,t)=u^{l,w,\lambda}(x,t)+u^{h,w,\lambda}(x,t).
\end{align}
The high-frequency components $u^{h,w,\lambda}$ are constructed as
\begin{align}\label{u-high}
 u^{h,w,\lambda}(x,t)=\begin{cases}
 \nabla^\perp \phi^{h,w,\lambda}(x,t)=(\partial_{x_2}\phi^{h,w,\lambda}(x,t),-\partial_{x_1}\phi^{h,w,\lambda}(x,t)), &~d=2,\\[3mm]
 \left(\nabla^\perp \phi^{h,w,\lambda}(x,t),0 \right)=(\partial_{x_2}\phi^{h,w,\lambda}(x,t),-\partial_{x_1}\phi^{h,w,\lambda}(x,t),0), &~d=3.
 \end{cases}
\end{align}
In \eqref{u-high}, the function $\phi^{h,w,\lambda}(x,t)$ is defined as
\begin{align}\label{phi-high}
 \phi^{h,w,\lambda}(x,t)=\begin{cases}
 \lambda^{-s-\delta-1}\phi(\dfrac{x_1}{\lambda^\delta})\phi(\dfrac{x_2}{\lambda^\delta})\sin (\lambda x_2-wt),&~d=2,\\[3mm]
 \lambda^{-s-\delta-1}\phi(\dfrac{x_1}{\lambda^\delta})\phi(\dfrac{x_2}{\lambda^\delta})\sin (\lambda x_2-wt)\phi(x_3),&~d=3,
 \end{cases}
\end{align}
where $s > 0, \lambda>0, w=\pm 1$, the parameter $\delta > 0$ is to be specified later and the smooth function $\phi \in C_c^\infty(\mathbb{R})$ satisfies $\text{supp}\,\phi \subset [-2,2]$ and $\phi(x) \equiv 1$ on $|x| < 1$.

Following similar estimates established in \eqref{u,b-low-t-local-bound} and \eqref{u-high-bound}, we can obtain
\begin{align}\label{4.5}
 \|\bar{u}^{l,w,\lambda}(t)\|_{H^m} + \|\bar{b}^{w,\lambda}(t)\|_{H^{m}}
 \leq C\lambda^{-1+\delta},
\end{align}
and
\begin{align}\label{4.6}
 \|\bar{u}^{h,w,\lambda}(t)\|_{H^r}\leq C\lambda^{r-s},\quad \|\bar{u}^{h,w,\lambda}(t)\|_{L^\infty}\leq C\lambda^{-s-\delta},\quad \|\nabla \bar{u}^{h,w,\lambda}(t)\|_{L^\infty}\leq C\lambda^{-s+1-\delta}
\end{align}
for any $0 \leq t \leq T\leq 1$, where $[0,T]$ denotes the existence interval of the solution guaranteed by Lemma~\ref{local-well-pri}.
\subsection{Error Estimates for the Approximate Solutions}\label{sec:4.2}
Following the approach in subsection \ref{sec:3.2} and based on system \eqref{mhd-B}, we construct a perturbed system as follows
\begin{align}\label{4.9}
 \begin{cases}
 \partial_t \bar{u}^{w,\lambda}+\bar{u}^{w,\lambda} \cdot \nabla \bar{u}^{w,\lambda}+\nabla p^{w,\lambda}=\bar{b}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{b}^{w,\lambda}+E_1^{w,\lambda},\\[1mm]
 \partial_t \bar{b}^{w,\lambda}-\Delta \bar{b}^{w,\lambda}+\bar{u}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}=\bar{b}^{w,\lambda}\cdot\nabla \bar{u}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{u}^{w,\lambda}+F_1^{w,\lambda}, \\[1mm]
 \diver\, \bar{u}^{w,\lambda}=\diver\, \bar{b}^{w,\lambda}=0,
 \end{cases}
\end{align}
where
\begin{align*}
 E_1^{w,\lambda}&=\partial_t \bar{u}^{h,w,\lambda}+\bar{u}^{l,w,\lambda}\cdot\nabla \bar{u}^{h,w,\lambda}+\bar{u}^{h,w,\lambda}\cdot\nabla \bar{u}^{h,w,\lambda}+\bar{u}^{h,w,\lambda}\cdot\nabla \bar{u}^{l,w,\lambda},\\\nonumber
 F_1^{w,\lambda}&=\bar{u}^{h,w,\lambda}\cdot\nabla \bar{b}^{w,\lambda}-\bar{b}^{w,\lambda}\cdot\nabla \bar{u}^{h,w,\lambda}-{\bf B_0}\cdot \nabla \bar{u}^{h,w,\lambda}\\
 &\define\diver \tilde{F}_1^{w,\lambda}-{\bf B_0}\cdot \nabla \bar{u}^{h,w,\lambda}.
\end{align*}
The perturbed system \eqref{4.9} is analogous to \eqref{mhd-low+high}. The directional derivative of the high-frequency component along the background magnetic field ${\bf B_0} = (B_1, B_2)$ is
\begin{align*}
 {\bf B_0} \cdot \nabla \bar{u}^{h,w,\lambda} = B_1\partial_{x_1}\bar{u}^{h,w,\lambda} + B_2\partial_{x_2}\bar{u}^{h,w,\lambda}.
\end{align*}
Remarkably, we observe that the oscillatory part in $\bar{u}^{h,w,\lambda}$ satisfies
\begin{align*}
 {\bf B_0} \cdot \nabla \left[\phi\left(\frac{B_1x_2 - B_2x_1}{\lambda^\delta}\right) \cos\left(\lambda(B_1x_2 - B_2x_1) - wt\right)\right] = 0,
\end{align*}
which leads to the following simplified expression
\begin{align*}
 & {\bf B_0}\cdot \nabla \left(\lambda^{-s-\delta}\phi\left(\dfrac{x_1}{\lambda^\delta}\right)
 \phi\left(\dfrac{B_1x_2-B_2x_1}{\lambda^\delta}\right)\cos \left(\lambda \left(B_1x_2-B_2x_1\right)-wt\right)\right)\\
 &=B_1\lambda^{-s-2\delta}\phi'\left(\frac{x_1}{\lambda^{\delta}}\right) \phi\left(\dfrac{B_1x_2-B_2x_1}{\lambda^\delta}\right)\cos \left(\lambda \left(B_1x_2-B_2x_1\right)-wt\right)
\end{align*}
Therefore, following analogous arguments as \eqref{4.3}, we can obtain
\begin{align}\label{4.7}
 \left\| {\bf B_0}\cdot\nabla \bar{u}^{h,w,\lambda}\right\|_{L^2}\leq C\lambda^{-s-\delta}.
\end{align}
Combining the estimates \eqref{4.5}, \eqref{4.6} with Lemma \ref{E,F-error-estimate}, we deduce that
\begin{align}\label{4.8}
 \|E_1^{w,\lambda}(t)\|_{L^2}\leq C\lambda^{-\sigma_{s,\delta}},\quad \|\tilde{F}_1^{w,\lambda}(t)\|_{L^2}\leq C\lambda^{-s-1},
\end{align}
where \begin{align*}
 \sigma_{s,\delta}=\min\{s+1-\delta,2s-1+\delta\}.
\end{align*}
\subsection{Exact Solutions}\label{sec:4.3}
Let $(\bar{u}_{w,\lambda},\bar{b}_{w,\lambda})$ be the unique solution to system \eqref{mhd-B} with the initial data $\left(\bar{u}^{w,\lambda}(x,0),\bar{b}^{w,\lambda}(x,0)\right)$, satisfying
\begin{align*}
 \begin{cases}
 \partial_t \bar{u}_{w,\lambda}+\bar{u}_{w,\lambda} \cdot \nabla \bar{u}_{w,\lambda}+\nabla p_{w,\lambda}=\bar{b}_{w,\lambda}\cdot \nabla \bar{b}_{w,\lambda}+{\bf B_0}\cdot \nabla \bar{b}_{w,\lambda},\\[1mm]
 \partial_t \bar{b}_{w,\lambda}-\Delta \bar{b}_{w,\lambda}+\bar{u}_{w,\lambda}\cdot \nabla \bar{b}_{w,\lambda}=\bar{b}_{w,\lambda}\cdot\nabla \bar{u}_{w,\lambda}+{\bf B_0}\cdot \nabla \bar{u}_{w,\lambda}, \\[1mm]
 \diver\, \bar{u}_{w,\lambda}=\diver\, \bar{b}_{w,\lambda}=0,
 \end{cases}
\end{align*}
It follows from \eqref{4.9} that
\begin{align*}
 \begin{cases}
 \partial_t \bar{u}^{w,\lambda}+\bar{u}^{w,\lambda} \cdot \nabla \bar{u}^{w,\lambda}+\nabla p^{w,\lambda}=\bar{b}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{b}^{w,\lambda}+E_1^{w,\lambda},\\[1mm]
 \partial_t \bar{b}^{w,\lambda}-\Delta \bar{b}^{w,\lambda}+\bar{u}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}=\bar{b}^{w,\lambda}\cdot\nabla \bar{u}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{u}^{w,\lambda}+\diver \tilde{F}_1^{w,\lambda}-{\bf B_0}\cdot \nabla \bar{u}^{h,w,\lambda}, \\[1mm]
 \diver\, \bar{u}^{w,\lambda}=\diver\, \bar{b}^{w,\lambda}=0.
\end{cases}
\end{align*}
The two systems share same initial conditions, which are
\begin{align*}
 \bar{u}_{w,\lambda}(x, 0)&=\bar{u}^{w,\lambda}(x,0)=\nabla^\perp\left( \bar{\phi}^{l,w,\lambda}(x)+\bar{\phi}^{h,w,\lambda}(x,0)\right),\\[1mm]
 \bar{b}_{w,\lambda}(x, 0)&=\bar{b}^{w,\lambda}(x,0)=\nabla^\perp\bar{\phi}^{l,w,\lambda}(x)
\end{align*}

post_theorem_intro_text:
\begin{remark}
	The stabilizing role of background magnetic fields in the MHD equations has been well studied in previous works \cite{lin-2014-GlobalSmallSolutions,full-not-bardos}. Our analysis reveals that despite the stabilization effect of the  background magnetic fields, the data-to-solution map for the resistive MHD equations \eqref{mhd} maintains its non-uniform continuity property for arbitrary non-zero constant fields ${\bf B_0}\neq {\bf 0}$.
\end{remark}

To simplify the notations, we write the perturbed system as follows
\begin{align}\label{mhd-B}
	\begin{cases}
		\partial_t u+u \cdot \nabla u+\nabla p=b\cdot \nabla b+{\bf B_0}\cdot\nabla b,\\[1mm]
		\partial_t b-\Delta b+u\cdot \nabla b=b\cdot\nabla u+{\bf B_0}\cdot\nabla u,  \\[1mm]
		\text{div}\, u=\text{div}\, b=0, \\[1mm]
		u(x, 0)=u_0(x),\,\, b(x, 0)=b_0(x),
	\end{cases}
\end{align}
where we denote $b - {\bf B_0}$ by $b$ for convenience.

We now explain the main ideas of the proof of  Theorem \ref{thm}. It is recalled that  Himonas and Misiołek  \cite{nonuniform-2010-cmp-himonas} introduced a frequency decomposition to construct  approximate solutions of the two-dimensional incompressible Euler equations. Denote
 \begin{align}\label{1.1}
	u^{\pm1,\lambda}(x,t)=u^{l,\pm1,\lambda}(x,t)+u^{h,\pm1,\lambda}(x,t),
\end{align}
where
\begin{itemize}
	\item[(i)] the low-frequency components $u^{l,\pm1,\lambda}$ are  obtained by solving the Euler equations with  low-frequency initial data;
	\item[(ii)] the high-frequency components $u^{h,\pm1,\lambda}$ are explicitly constructed by using  oscillatory profiles, with frequency parameter $\lambda$ controlling the spatial concentration,
	\begin{align}\label{1.2}
		u^{h,\pm1,\lambda}(x,t)=\nabla^\perp \left(\lambda^{-\delta-s-1}\phi\left(\dfrac{x_1}{\lambda^\delta}\right)\phi\left(\dfrac{x_2}{\lambda^\delta}\right)\sin (\lambda x_2\mp t)\right).
	\end{align}
Here, $\lambda>0, \max\{1-s,0\}<\delta < 1$ and $\phi\in C_c^\infty(\mathbb{R})$ with $\text{supp}\,\phi \subset [-2,2]$ and $\phi(x) \equiv 1$ on $|x| < 1$.
\end{itemize}

It is required to modify the construction of the approximate solutions in the presence of the magnetic field. To the resistive MHD equations, due to the diffusive nature of the magnetic field evolution (versus the purely transport equations of the Euler equations ), we restrict high-frequency perturbations to the velocity field alone and  maintain low-frequency components for the magnetic field. More precisely, in the case $\mathbf{B_0} = \mathbf{0}$ (no background magnetic field) and $d=2$,  we set
\begin{itemize}
	\item the low-frequency pairs $(u^{l,\pm1,\lambda}, b^{\pm1,\lambda})$ by solving the resistive MHD equations \eqref{mhd} (equivalently, system \eqref{mhd-B} with $\mathbf{B_0} = \mathbf{0}$) with low-frequency initial data;
	\item the high-frequency velocity components $u^{h,\pm1,\lambda}$ by retain their profiles as in  \eqref{1.2}.
\end{itemize}

In the three-dimensional case $(d = 3)$, we modify  the high-frequency velocity components as
	\begin{align}\label{1.3}
	u^{h,\pm1,\lambda}(x,t)=\begin{pmatrix}
		\partial_{x_1}\\[1mm]
		-\partial_{x_2}\\[1mm]
		0
	\end{pmatrix} \left(\lambda^{-\delta-s-1}\phi\left(\dfrac{x_1}{\lambda^\delta}\right)\phi\left(\dfrac{x_2}{\lambda^\delta}\right)\sin (\lambda x_2\mp t)\phi(x_3)\right).
\end{align}

The error terms induced by the  high-frequency  $u^{h,\pm1,\lambda}$   can be written as
\begin{align}\label{1.4}
	E^{\pm1,\lambda}&=\partial_t u^{h,\pm1,\lambda}+u^{l,\pm1,\lambda}\cdot\nabla u^{h,\pm1,\lambda}+u^{h,\pm1,\lambda}\cdot\nabla u^{h,\pm1,\lambda}+u^{h,\pm1,\lambda}\cdot\nabla u^{l,\pm1,\lambda},\\\label{1.5}
	F^{\pm1,\lambda}&=u^{h,\pm1,\lambda}\cdot\nabla b^{\pm1,\lambda}-b^{\pm1,\lambda}\cdot\nabla u^{h,\pm1,\lambda},
\end{align}
respectively.

Direct estimation of \eqref{1.5} will lead to uncontrolled error terms. Our alternative approach consists of three key steps:
\begin{enumerate}
	\item {\bf Divergence reformulation:} We express $F^{\pm1,\lambda} =\text{div}\,\, \tilde{F}^{\pm1,\lambda}$ and establish estimates for $\tilde{F}^{\pm1,\lambda}$;
	\item {\bf Integration by parts:} In $L^2$ inner product computations, we transfer the divergence operator to $b^{\pm1,\lambda}$ via integration by parts;
	\item {\bf Diffusion cancellation:} The resulting terms are precisely canceled by exploiting the magnetic diffusion term $\Delta b^{\pm1,\lambda}$.
\end{enumerate}

For non-zero background fields $\mathbf{B_0}=(B_1,B_2) \neq \mathbf{0}$, we introduce the coordinate transformation
\begin{align*}
	x_2 \mapsto B_1x_2 - B_2x_1,
\end{align*}
which maintains all norm estimates while achieving exact cancellation of the dominant high-frequency linear term $\mathbf{B_0} \cdot \nabla u^{h,\pm 1,\lambda}$ appearing in the error analysis of $F^{\pm1,\lambda}$.

A key observation is that the directional derivative exhibits a better decay:
\begin{align*}
	\left\|\mathbf{B_0} \cdot \nabla u^{h,\pm 1,\lambda}\right\|_{L^2}\leq C\lambda^{-s-\delta} \ll \left\|u^{h,\pm 1,\lambda}\right\|_{L^2}\leq C\lambda^{-s}, \text{~for~}\lambda \to \infty,
\end{align*}
where $\delta>0$ represent the improved decay rate.

	 The paper is organized as follows. section \ref{sec:2} is the preliminary analytical framework, in which subsection \ref{sec:2.1} is about key Lemmas and subsection \ref{sec:2.2} is on the local well-posedness theory. The core  strategy of the proof is implemented in section \ref{sec:3} (zero background field case, $\mathbf{B_0} = \mathbf{0}$) and section  \ref{sec:4} (non-zero background field case, $\mathbf{B_0} \neq \mathbf{0}$), following the approach as follows: construction of approximate solutions in subsections \ref{sec:3.1} and \ref{sec:4.1}, precise estimation of approximation errors in subsections \ref{sec:3.2} and \ref{sec:4.2}, rigorous construction of exact solutions in subsections \ref{sec:3.3} and \ref{sec:4.3}, finishing the proof of Theorem in the case $\mathbf{B_0} = \mathbf{0}$ and $\mathbf{B_0} \neq \mathbf{0}$ in subsections \ref{sec:3.4} and \ref{sec:4.4}, respectively.

{\bf Notations:}
\begin{enumerate}
\item {\bf Function Spaces:} Throughout this work, let $X$ denote a Banach space equipped with norm $\|\cdot\|_X$. Since all function spaces considered here are defined on $\mathbb{R}^d$ for $d = 2,3$, we will suppress the domain $\mathbb{R}^d$ in our notation unless otherwise specified.
	\item {\bf Differential Operators:} For $x \in \mathbb{R}^2$, we define the perpendicular gradient operator as $\nabla^\perp := (\partial_{x_2}, -\partial_{x_1})$.
	\item {\bf Joint Norms:} Given functions $f, g \in X(\mathbb{R}^d)$, we define their joint norm by
\begin{align*}
	\|f(\cdot),g(\cdot)\|_{X(\mathbb{R}^d)}=	\|f(\cdot)\|_{X(\mathbb{R}^d)}+	\|g(\cdot)\|_{X(\mathbb{R}^d)}
\end{align*}
adopting this concise notation for simplicity.
\end{enumerate}

