 F_iM_n = \bigcap_{j=n-i+1}^n \ker\bigl( \partial_{n,j}:M_n\to M_{n-1} \bigr) \subset M_n .
 \end{equation*}
 Thus $F_iM_n=M_n$, and $F_nM_n=N_n(M)$. The existence of $F_iM_n$
 is shown by induction on $i$: $F_{i+1}M_n$ is the kernel of the
 split epimorphism
 \begin{equation*}
 \partial_{n,n-i} : F_iM_n \to F_iM_{n-1} ,
 \end{equation*}
 with section $s_{n-1,n-i-1}:F_iM_{n-1} \to F_iM_n$.
\end{proof}

The following result of Dold and Puppe \cite{DP} is a reformulation of
the theorem of Dold \cite{Dold} and Kan \cite{Kan}. They state the
theorem when $\mathcal{A}$ is abelian, but their proof applies more
generally. (Recall that a pre-additive category is additive if it has
finite sums.)

Let $M_\bullet$ be a simplicial module. Dold and Puppe \cite{DP}*{Section 3}
define idempotents
\begin{equation*}
 p_n = (1-s_{n-1,0}\partial_{n,1})\ldots(1-s_{n-1,n-1}\partial_{n,n}) : M_n \to M_n .
\end{equation*}
The kernel of the idempotent $p_n:M_n\to M_n$, if it exists, is the
module of degenerate chains $D_n(M)$. The image of $p_n$ is the module
$N_n(M)$ of normalized chains. Provided these modules exist, we have
the direct sum decomposition
\begin{equation*}
 M_n = N_n(M) \oplus D_n(M) .
\end{equation*}

\begin{lemma}
 If $\CA$ is weakly idempotent complete, the idempotent $p_n$ splits,
 implying the existence of the modules $N_n(M)$ and $D_n(M)$.
\end{lemma}
\begin{proof}
 Consider the filtration
 \begin{equation*}
 F_iM_n = \bigcap_{j=n-i+1}^n \ker\bigl( \partial_{n,j}:M_n\to M_{n-1} \bigr) \subset M_n .
 \end{equation*}
 Thus $F_iM_n=M_n$, and $F_nM_n=N_n(M)$. The existence of $F_iM_n$
 is shown by induction on $i$: $F_{i+1}M_n$ is the kernel of the
 split epimorphism
 \begin{equation*}
 \partial_{n,n-i} : F_iM_n \to F_iM_{n-1} ,
 \end{equation*}
 with section $s_{n-1,n-i-1}:F_iM_{n-1} \to F_iM_n$.
\end{proof}

We call this the Dold--Kan decomposition.

The purpose of this article is to give a new proof of a result of
Dwyer and Kan \cite{DK}*{Corollary 6.6}.
\begin{theorem}
 \label{DwyerKan}
 Let $\CA$ be a weakly idempotent additive category.
 \begin{enumerate}[i)]
 \item The duplicial module $M_\bullet$ is paracyclic if and only if the
 restriction of the Karoubi operator $\kappa_n$ to $N_n(M)$ is
 invertible for all $n\ge0$.
 \item The duplicial module $M_\bullet$ is cyclic if and only if the
 restriction of the Dwyer--Kan operator $\pi_n$ to $N_n(M)$ is the
 identity for all $n\ge0$.
 \end{enumerate}
\end{theorem}

A simplicial module $M_\bullet$ gives rise to a chain complex: it carries
the differential
\begin{equation*}
 b_n = \sum_{i=0}^n (-1)^i \partial_{n,i} : M_n \to M_{n-1} .
\end{equation*}
We have
\begin{align*}
 b_{n-1}b_n &= \sum_{0\le j\le k\le n-1} (-1)^{j+k} \, \partial_{n-1,k} \partial_{n,j}
 + \sum_{0\le k< j\le n} (-1)^{j+k} \, \partial_{n-1,k} \partial_{n,j} \\
 &= \sum_{0\le j\le k\le n-1} (-1)^{j+k} \, \partial_{n-1,j} \partial_{n,k+1}
 + \sum_{0\le k< j\le n} (-1)^{j+k} \, \partial_{n-1,k} \partial_{n,j} = 0 .
\end{align*}
Note that the restriction of $b_n$ to $N_n(M)$ equals
$\partial_{n,0}$. This gives a formula for the action of the face map
$\delta_n=\partial_{n,0}$ in the Dold--Kan decomposition:
\begin{equation*}
 \delta_n \bigl( s_{n-1,i_1}\dots s_{n-k,i_k} x_{i_1\ldots i_k} \bigr) =
 \begin{cases}
 s_{n-2,i_1-1} \ldots s_{n-k,i_{k-1}-1} x_{i_1\ldots i_k} , & i_k=0 \\
 s_{n-2,i_1-1}\dots s_{n-k-1,i_k-1} ( b_{n-k}x_{i_1\ldots i_k} ) , &
 i_k>0 .
 \end{cases}
\end{equation*}

It was proved by Eilenberg and Mac Lane \cite{EM1} that the complexes
$(M_\bullet,b)$ and $(N_\bullet(M),b)$ are homotopy equivalent. The following
expression for their homotopy is taken from Epstein
\cite{Epstein}*{Proposition 2.3}.
\begin{proposition}
 Let $M_\bullet$ be a simplicial module. The operator
 \begin{equation*}
 \varphi_n = \sum_{i=0}^n (-1)^i s_{n,i} p_{n,i} : M_n \to M_{n+1}
 \end{equation*}
 satisfies $b_{n+1}\varphi_n + \varphi_{n-1}b_n = p_n - 1$.
\end{proposition}
\begin{proof}
 For $0\le i\le n$,
 \begin{align*}
 b_{n+1} s_{n,i} p_{n,i}
 &= \sum_{k=0}^{i-1} (-1)^k \partial_{n+1,k} s_{n,i} p_{n,i}
 + (-1)^i ( \partial_{n+1,i} - \partial_{n+1,i+1} ) s_{n,i} p_{n,i} \\
 & \quad + \sum_{k=i+2}^{n+1} (-1)^k \partial_{n+1,k} s_{n,i} p_{n,i} \\
 &= \sum_{k=0}^{i-1} (-1)^k s_{n-1,i-1} \partial_{n,k} p_{n,i}
 + \sum_{k=i+2}^{n+1} (-1)^k s_{n-1,i} \partial_{n,k-1} p_{n,i} \\
 &= \sum_{k=0}^n (-1)^k s_{n-1,i-1} \partial_{n,k} p_{n,i}
 - (-1)^i s_{n-1,i-1} \partial_{n,i} p_{n,i} \\
 &= s_{n-1,i-1} b_n p_{n,i} + (-1)^i ( p_{n,i-1} - p_{n,i} ) \\
 &= s_{n-1,i-1} p_{n-1,i-1} b_n + (-1)^i ( p_{n,i-1} - p_{n,i} ) .
 \end{align*}
 Summing over $i$, the result follows
\end{proof}

We now come to the main result of this article.
\begin{theorem}
 $\pi_n= p_n \circ \T_n = \T_n \circ p_n$
\end{theorem}
\begin{proof}
 \begin{align*}
 \pi_n &= (-1)^n \partial_{n+1}(\partial_{n+2}s_{n+1}-s_n\partial_{n+1})^ns_n (-1)^{|j|-|i|} \\
 &= t_n^{n+1} + \sum_{k=1}^{n-1} \sum_{0\le i_1<j_1<i_2<j_2< \ldots<i_k<j_k\le n} \\
 & \qquad \bigl( t_n^{i_1} \partial_{n+1} t_{n+1}^{j_1-i_1} s_n \bigr)
 \bigl( t_n^{i_2-j_1-1} \partial_{n+1} t_{n+1}^{j_2-i_2} s_n \bigr) \ldots
 \bigl( t^{i_k-j_{k-1}-1} \partial_{n+1} t_{n+1}^{j_k-i_k} s_n \bigr)
 t_n^{n-j_k} .
 \end{align*}
 If $p<q$, define
 \begin{align*}
 \Pi_{p,q} &= (-1)^{q-p} s_{n-1,p} \partial_{n,q} \\
 &= \bigl( - s_{n-1,p} \partial_{n,p+1} \bigr)
 \bigl( - s_{n-1,p+1} \partial_{n,p+2} \bigr) \ldots
 \bigl( - s_{n-1,q-1} \partial_{n,q} \bigr) .
 \end{align*}
 By definition,
 \begin{equation*}
 \sum_{k=0}^{n-1} \sum_{0\le i_1<j_1<i_2<j_2< \ldots<i_k<j_k\le n} \Pi_{i_1,j_1} \ldots
 \Pi_{i_k,j_k} .
 \end{equation*}
 We have
 \begin{align*}
 (-1)^{j-i} t_n^i \partial_{n+1} t_{n+1}^{j-i} s_n
 &= (-1)^{j-i} t_n^{i-n-1} \partial_{n+1} t_{n+1}^{j-i+n+2} s_n \\
 &= (-1)^{j-i} \partial_{n+1,n-i+1} t_{n+1}^{j+1} s_n
 = (-1)^{j-i} \partial_{n+1,n-i+1} s_{n,n-j} t_n^{j+1} \\
 &= (-1)^{j-i} s_{n-1,n-j} \partial_{n,n-i} t_{n+1}^{j+1} = \Pi_{n-j,n-i} t_n^{j+1} .
 \end{align*}
 It follows that
 \begin{equation*}
 \pi_n = \sum_{k=0}^{n-1} \sum_{0\le i_1<j_1<\ldots\le i_k<j_k\le n}
 \Pi_{n-j_1,n-i_1} \ldots \Pi_{n-j_k,n-i_k} t_n^{n+1} .
 \end{equation*}
 The proof is completed by showing that if $s<p$,
 \begin{equation}
 \label{PiPi}
 \Pi_{p,q} \Pi_{r,s} = \Pi_{r,s} \Pi_{p,q} .
 \end{equation}
 This allows us to reverse the order of the factors in
 $\Pi_{n-j_1,n-i_1} \ldots \Pi_{n-j_k,n-i_k}$:
 \begin{equation*}
 \Pi_{n-j_1,n-i_1} \ldots \Pi_{n-j_k,n-i_k} = \Pi_{n-j_k,n-i_k} \ldots \Pi_{n-j_1,n-i_1} .
 \end{equation*}
 To prove \eqref{PiPi}, we must show that
 \begin{equation*}
 s_{n-1,p} \partial_{n,q} s_{n-1,r} \partial_{n,s}
 = s_{n-1,r} \partial_{n,s} s_{n-1,p} \partial_{n,q} .
 \end{equation*}
 This is a consequence of the simplicial relations:
 \begin{align*}
 s_{n-1,p} \partial_{n,q} s_{n-1,r} \partial_{n,s} 
 &= s_{n-1,p} s_{n-2,r} \partial_{n-1,q-1} \partial_{n,s} \\
 &= s_{n-1,r} s_{n-2,p-1} \partial_{n-1,s} \partial_{n,q}
 = s_{n-1,r} \partial_{n,s} s_{n-1,p} \partial_{n,q} .
 \qedhere
 \end{align*}
\end{proof}

Theorem \ref{DwyerKan} is an immediate consequence of this theorem. In
terms of the Dold--Kan decomposition, we see that
\begin{equation*}
 \T_n x = \sum_{k=0}^n \sum_{0\le i_k<\cdots<i_1<n} s^{n-1}_{i_1}\ldots s^{n-k}_{i_k}
 \pi_{n-k}x_{i_1\ldots i_k} .
\end{equation*}
We see that $\T_n$ is invertible on $M_n$ if and only if $\pi_{n-k}$ is
invertible on $N_{n-k}(M)$ for $0\le k\le n$. But $\pi_n$ is invertible on
$N_n(M)$ if and only if $\kappa_n$ is, by the formulas
\begin{equation*}
 \kappa_n^{-1} = \pi_n^{-1} (1+b_{n+1}d_n)^n (1+d_{n-1}b_n)^{n-1}
\end{equation*}
and
\begin{equation*}
 \pi_n^{-1} = \kappa_n^{-n-1} (1+d_{n-1}b_n) .
\end{equation*}

