\begin{theorem}
\label{theo:main}
For every non-orientable regular map $\M$ of type $\{p,q\}$ where at least one of $p$ or $q$ is odd, there exists an unstable fully transitive $2$-orbit map $\M^\omega$, that covers $\M$. Moreover, for all $n>3$ there exist $2^{n-3}$ non-isomorphic unstable $2$-orbit fully transitive $n$-maniplexes, whose $3$-faces are isomorphic to $\M^\omega$.
\end{theorem}

ref_dict.open and discrete thm:
\begin{thm}\label{open and discrete thm}
    Let $\Omega\subset\mathbb{R}^n$ be a domain, let $y_0\in\mathbb{R}^n$, and let $p, q \in [1, \infty]$. Suppose that
    $f\in W^{1,n}_{\rm loc}(\Omega,\mathbb{R}^n)$ has a value of finite distortion at $y_0\in\mathbb{R}^n$ with data $(K,\Sigma)$, where $K:\Omega\to[1,\infty)$ and $\Sigma:\Omega\to[0,\infty)$ are measurable functions such that
    \begin{equation}\label{K,Sigma condition}
        K\in L^p_{\rm loc}(\Omega),
        \quad{\rm and}\quad 
        \frac{\Sigma}{K}\in L^{q}_{\rm loc}(\Omega).
    \end{equation}
    If $p > n-1$ and $p^{-1} + q^{-1} < 1$, then either $f\equiv y_0$ a.e.\ in $\Omega$, or the continuous representative of $f$ satisfies the following conditions:
    \begin{itemize}[noitemsep]
        \item $f^{-1}\{y_0\}$ is a discrete subset of $\Omega$,
        \item at every $x_0\in f^{-1}\{y_0\}$ the local index $i(x_0,f)$ is positive, and
        \item for every neighborhood $U$ of a point $x_0\in f^{-1}\{y_0\}$, we have $y_0\in  {\rm int}\ f(U)$.
    \end{itemize}
\end{thm}

