\begin{equation}\label{mainth1eq}
\sum_{k=0}^{p^r-1}(2k+\alpha)\frac{(\alpha)_k^3(\f12)_k}{(1)_k^3(\f12+\alpha)_k}\equiv \alpha^{\ast_r}p^r -\frac{(\alpha^{\ast_r})^3}{(\f12+\alpha)^{\ast_r}}p^{r+2}H_{\alpha^{\ast_r}p-\alpha^{\ast_{r-1}}}^{(2)}\pmod{p^{r+3}},
\end{equation}
where $\alpha=c/d$.

