\begin{theorem}
\label{thm:infinite-geometric-moduli-complex-hyperbolic}
	The complement $S^{2 n + 1} \setminus S_{\bbC}^{2 k + 1}$ satisfies
	$\# \GModuli(S^{2 n + 1} \setminus S_{\bbC}^{2 k + 1}) = \infty$ if $0 \leq k < (n - 2) / 2$.
\end{theorem}

We add some remarks on these theorems.
Let $V$ be a real linear subspace in $\bbC^{n + 1}$
and set $\Lambda \coloneqq V \cap S^{2 n + 1} \subset S^{2 n + 1}$.
If $V$ is totally real or complex and $\dim_{H} \Lambda < n$,
then we proved that $\# \GModuli(S^{2 n + 1} \setminus \Lambda) = \infty$.
The key point of the proof is that
there exists a torsion-free convex cocompact discrete subgroup $\Gamma$ of $PU(n + 1, 1)$
whose limit set coincides with $\Lambda$.
Then the quotient of $S^{2 n + 1} \setminus \Lambda$ by $\Gamma$ satisfies \Cref{keyassumption}.
On the other hand,
when $V$ is neither totally real nor complex,
there exist no discrete subgroups in $PU(n + 1, 1)$
such that its limit set coincides with $\Lambda$,
and hence our argument does not apply.
As far as we know,
there are no existence results for complete contact forms
with constant Tanaka--Webster scalar curvature on $S^{2 n + 1} \setminus \Lambda$

We will also apply \cref{thm:infinite-geometric-moduli-general}
to circle bundles over compact \Kahler manifolds (\cref{thm:infinite-geometric-moduli-circle-bundle})
and the boundary of a Reinhardt domain (\cref{subsection:boundary-of-Reinhardt-domain}),
which is neither spherical nor Sasakian.

This paper is organized as follows.
In \cref{section:CR-geometry},
we review basic materials in CR geometry.
In \cref{section:CR-Yamabe-problem},
we recall the CR Yamabe problem and summarize known existence results that motivate the present work.
In \cref{section:complex-hyperbolic-geometry},
we collect several facts from complex hyperbolic geometry
that are needed to analyze complements of $\bbR$- and $\bbC$-spheres in the CR sphere.
In \cref{section:infinite-tower},
we study an existence problem for infinite towers of finite connected coverings;
this constitutes the technical core of the paper.
In \cref{section:proof-of-main-result},
we use this framework to prove \cref{thm:infinite-geometric-moduli-general}.
In \cref{section:complements-of-spheres},
we apply this theorem to complements of $\bbR$- and $\bbC$-spheres in the CR sphere.
Finally, in \cref{section:other-applications},
we discuss further applications to circle bundles over compact \Kahler manifolds
and to the boundary of a Reinhardt domain.

\section{CR geometry}
\label{section:CR-geometry}

\subsection{CR manifolds}
\label{subsection:CR-manifolds}

Let $M$ be a smooth $(2 n + 1)$-dimensional manifold.
A \emph{CR structure} is a rank $n$ complex subbundle $T^{1, 0} M$
of the complexified tangent bundle $T M \otimes \bbC$ such that
\begin{equation}
	T^{1, 0} M \cap T^{0, 1} M = 0, \qquad
	\comm{\Gamma(T^{1, 0} M)}{\Gamma(T^{1, 0} M)} \subset \Gamma(T^{1, 0} M),
\end{equation}
where $T^{0, 1} M$ is the complex conjugate of $T^{1, 0} M$ in $T M \otimes \bbC$.
Set $H M = \Re T^{1, 0} M$
and let $J \colon H M \to H M$ be the unique complex structure on $H M$ 
such that
\begin{equation}
	T^{1, 0} M = \Ker(J - \sqrt{- 1} \colon H M \otimes \bbC \to H M \otimes \bbC).
\end{equation}
A typical example of a CR manifold is a real hypersurface $M$ in an $(n + 1)$-dimensional complex manifold $X$;
this $M$ has the induced CR structure
\begin{equation}
	T^{1, 0} M
	\coloneqq T^{1, 0} X |_{M} \cap (T M \otimes \bbC).
\end{equation}
In particular,
the unit sphere
\begin{equation}
	S^{2 n + 1}
	\coloneqq \Set{z \in \bbC^{n + 1} | \abs{z}^{2} = 1}
\end{equation}
has the \emph{canonical} CR structure $T^{1, 0} S^{2 n + 1}$.

Let $(M, T^{1, 0} M)$ and $(M^{\prime}, T^{1, 0} M^{\prime})$ be CR manifolds.
A smooth map $f \colon M \to M^{\prime}$ is called a \emph{CR map}
if $f_{\ast} (T^{1, 0} M) \subset T^{1, 0} M^{\prime}$.
If $f$ is a diffeomorphism,
then we call $f$ a \emph{CR diffeomorphism}.
A CR manifold $(M, T^{1, 0} M)$ is said to be \emph{spherical}
if it is locally isomorphic to $(S^{2 n + 1}, T^{1, 0} S^{2 n + 1})$.

A CR structure $T^{1, 0} M$ is said to be \emph{strictly pseudoconvex}
if there exists a smooth real-valued one-form $\theta$ annihilating exactly $H M$
such that the \emph{Levi form}
\begin{equation}
	L_{\theta}(V, W)
	\coloneqq d \theta(V, J W)
	\qquad (V, W \in H M)
\end{equation}
is positive definite.
We call such a one-form a \emph{contact form}.
The triple $(M, T^{1, 0} M, \theta)$ is called a \emph{pseudo-Hermitian manifold}.
Denote by $T$ the \emph{Reeb vector field} with respect to $\theta$; 
that is,
the unique vector field satisfying
\begin{equation}
	\theta(T) = 1, \qquad T \contr d \theta = 0.
\end{equation}
Let $(Z_{\alpha})$ be a local frame of $T^{1, 0} M$,
and set $Z_{\ovxa} = \overline{Z_{\alpha}}$.
Then
$(T, Z_{\alpha}, Z_{\ovxa})$ gives a local frame of $T M \otimes \bbC$,
called an \emph{admissible frame}.
Its dual frame $(\theta, \theta^{\alpha}, \theta^{\ovxa})$
is called an \emph{admissible coframe}.
The two-form $d \theta$ is written as
\begin{equation}
	d \theta
	= \sqrt{- 1} h_{\alpha \ovxb} \theta^{\alpha} \wedge \theta^{\ovxb},
\end{equation}
where $(h_{\alpha \ovxb})$ is a positive definite Hermitian matrix.
We use $h_{\alpha \ovxb}$ and its inverse $h^{\alpha \ovxb}$
to raise and lower indices of tensors.

The flat model of pseudo-Hermitian manifolds is the \emph{Heisenberg group} $\bbH^{2 n + 1}$,
that is,
the Lie group with the underlying manifold $\bbR \times \bbC^{n}$ and the multiplication
\begin{equation}
	(t, z) \cdot (t^{\prime}, z^{\prime})
	\coloneqq (t + t^{\prime} + 2 \Im (z \cdot \ovz^{\prime}), z + z^{\prime}).
\end{equation}
For $\alpha = 1, \dots , n$,
we introduce a left-invariant complex vector field $Z_{\alpha}$ by
\begin{equation}
	Z_{\alpha}
	\coloneqq \pdv{}{z^{\alpha}} + \sqrt{- 1} \ovz^{\alpha} \pdv{}{t}.
\end{equation}
The canonical CR structure $T^{1, 0} \bbH^{2 n + 1}$
is spanned by $Z_{1}, \dots , Z_{n}$.
Define a left-invariant one-form $\theta$ on $\bbH^{2 n + 1}$ by
\begin{equation}
	\theta
	\coloneqq d t + \sqrt{-1} \sum_{\alpha = 1}^{n}
		(z^{\alpha} d \ovz^{\alpha} - \ovz^{\alpha} d z^{\alpha}).
\end{equation}
Then $\theta$ annihilates $T^{1, 0} \bbH^{2 n + 1}$
and the Levi form $L_{\theta}$ satisfies
$L_{\theta}(Z_{\alpha}, Z_{\ovxb}) = 2 \delta_{\alpha \beta}$;
in particular,
$(\bbH^{2 n + 1}, T^{1, 0} \bbH^{2 n + 1})$ is a strictly pseudoconvex CR manifold
and $\theta$ is a contact form on $\bbH^{2 n + 1}$.

A CR manifold $(M, T^{1, 0} M)$ is said to be \emph{embeddable}
if there exists a smooth embedding $F \colon M \to \bbC^{N}$
such that $F_{\ast}(T^{1, 0} M) \subset T^{1, 0} \bbC^{N}$.
It is known that a compact strictly pseudoconvex CR manifold $(M, T^{1, 0} M)$
of dimension at least five must be embeddable~\cite{Boutet_de_Monvel1975}.
On the other hand,
there are many non-embeddable compact strictly pseudoconvex CR manifolds of dimension three;
see for example \cite{Burns-Epstein1990-Embed}.
We say that $(M, T^{1, 0} M)$ is \emph{universally embeddable}
if every finite cover of $(M, T^{1, 0} M)$ is embeddable.
This condition is strictly stronger than the embeddability condition~\cite{Case-Yang2025}.

Assume that $M$ is connected and fix a contact form $\theta$ on $M$.
We can also endow $M$ with the \emph{Carnot--Carath\'{e}odory distance} $d_{\CC}$ on $M$ as follows.
For any $p, q \in M$,
we can find a smooth path $c \colon \clcl{0}{1} \to M$
such that $c(0) = p$, $c(1) = q$, and $\theta(c^{\prime}(t)) = 0$.
Then $d_{\CC}(p, q)$ is the infimum of the length of such curves.
Denote by $\dim_{H} A$ the Hausdorff dimension of $A \subset M$ with respect to $d_{\CC}$.
The Carnot--Carath\'{e}odory distance $d_{\CC}$ induces the standard topology of $M$,
but the Hausdorff dimension $\dim_{H} M$ of $M$ is equal to $2 n + 2$,
which does not coincide with its topological dimension.
See \cite{Gromov1996} for more details.

\subsection{Tanaka--Webster connection}
\label{subsection:TW-connection}

A contact form $\theta$ induces a canonical connection $\nabla$ on $T M$,
called the \emph{Tanaka--Webster connection} with respect to $\theta$.
It is defined by
\begin{equation}
	\nabla T
	= 0,
	\quad
	\nabla Z_{\alpha}
	= \omega_{\alpha} {}^{\beta} Z_{\beta},
	\quad
	\nabla Z_{\ovxa}
	= \omega_{\ovxa} {}^{\ovxb} Z_{\ovxb},
\end{equation}
where $\omega_{\ovxa} {}^{\ovxb} = \overline{\omega_{\alpha} {}^{\beta}}$,
with the following structure equations:
\begin{gather}
\label{eq:str-eq-of-TW-conn1}
	d \theta^{\beta}
	= \theta^{\alpha} \wedge \omega_{\alpha} {}^{\beta}
	+ A^{\beta} {}_{\ovxa} \theta \wedge \theta^{\ovxa}, \\
\label{eq:str-eq-of-TW-conn2}
	d h_{\alpha \ovxb}
	= \omega_{\alpha} {}^{\gamma} h_{\gamma \ovxb}
		+ h_{\alpha \ovxg} \omega_{\ovxb} {}^{\ovxg}.
\end{gather}
The tensor $A_{\alpha \beta} = \overline{A_{\ovxa \ovxb}}$
is symmetric and is called the \emph{Tanaka--Webster torsion}.
The \emph{sub-Laplacian} $\Delta_{b}$ is defined by
\begin{equation}
	\Delta_{b} u
	\coloneqq - \nabla^{\alpha} \nabla_{\alpha} u - \nabla^{\ovxb} \nabla_{\ovxb} u.
\end{equation}

The curvature form
$\Omega_{\alpha} {}^{\beta} \coloneqq d \omega_{\alpha} {}^{\beta}
- \omega_{\alpha} {}^{\gamma} \wedge \omega_{\gamma} {}^{\beta}$
of the Tanaka--Webster connection satisfies
\begin{equation}
\label{eq:curvature-form-of-TW-connection}
	\Omega_{\alpha} {}^{\beta}
	= R_{\alpha} {}^{\beta} {}_{\rho \ovxs} \theta^{\rho} \wedge \theta^{\ovxs}
		\qquad \text{modulo $\theta, \theta^{\rho} \wedge \theta^{\gamma},
		\theta^{\ovxg} \wedge \theta^{\ovxs}$}.
\end{equation}
We call the tensor $R_{\alpha} {}^{\beta} {}_{\rho \ovxs}$
the \emph{Tanaka--Webster curvature}.
This tensor has the symmetry 
\begin{equation}
	R_{\alpha \ovxb \rho \ovxs}
	= R_{\rho \ovxb \alpha \ovxs}
	= R_{\alpha \ovxs \rho \ovxb}.
\end{equation}
Contraction of indices gives the \emph{Tanaka--Webster Ricci curvature}
$\Ric_{\rho \ovxs} = R_{\alpha} {}^{\alpha} {}_{\rho \ovxs}$
and the \emph{Tanaka--Webster scalar curvature}
$R_{\theta} = \Ric_{\rho} {}^{\rho}$.
When $n \geq 2$,
the \emph{Chern tensor} $S_{\alpha \ovxb \rho \ovxs}$ is the completely trace-free part
of $R_{\alpha \ovxb \rho \ovxs}$;
this tensor is the CR analogue of the Weyl tensor in conformal geometry.
It is known that the Chern tensor vanishes identically
if and only if $(M, T^{1, 0} M)$ is spherical~\cite{Chern-Moser1974}.

Fix a contact form $\theta$ on $M$.
Then any contact form $\whxth$ is of the form $u^{2 / n} \theta$,
where
\begin{equation}
	u \in C^{\infty}_{+}(M) \coloneqq \Set{u \in C^{\infty}(M) | u > 0}.
\end{equation}
Under this conformal change,
the Tanaka--Webster scalar curvature $R_{\wtxth}$ with respect to $\whxth$ satisfies
\begin{equation}
	R_{\wtxth}
	= u^{- 1 - 2 / n} \sbra*{(2 + 2 / n) \Delta_{b} u + R_{\theta} u};
\end{equation}
see \cite{Jerison-Lee1987}*{p.\ 174} for example.

\subsection{Sasakian manifolds}
\label{subsection:Sasakian-manifolds}

Sasakian manifolds constitute an important class of pseudo-Hermitian manifolds.
See~\cite{Boyer-Galicki2008} for a comprehensive introduction.

A \emph{Sasakian manifold} is a pseudo-Hermitian manifold $(S, T^{1, 0}S, \theta)$
with vanishing Tanaka--Webster torsion.
This condition is equivalent to the requirement that the Reeb vector field $T$ of $\theta$
preserves the CR structure $T^{1, 0} S$.

A typical example of a Sasakian manifold
is the circle bundle associated with a negative Hermitian holomorphic line bundle.
Let $Y$ be an $n$-dimensional complex manifold
and $(L, h)$ a Hermitian holomorphic line bundle over $Y$
such that
\begin{equation}
	\omega = - \sqrt{- 1} \Theta_{h} = d d^{c} \log h
\end{equation}
is a \Kahler form on $Y$,
where $d^{c} \coloneqq (\sqrt{- 1} / 2)(\delb - \partial)$.
Consider the circle bundle
\begin{equation}
	S = \Set{ v \in L | h(v, v) = 1}
\end{equation}
over $Y$,
which is a real hypersurface in the total space of $L$
and has the canonical CR structure $T^{1, 0} S$.
The one-form $\theta = d^{c} \log h |_{S}$ is a contact form on $S$
and its Tanaka--Webster scalar curvature $R_{\theta}$ coincides with $p^{\ast} R_{\omega}$,
where $p \colon S \to Y$ is the projection
and $R_{\omega}$ is the scalar curvature of $\omega$.
Moreover,
the CR manifold $(S, T^{1, 0} S)$ is spherical if and only if
$(Y, \omega)$ is Bochner-flat.
See \cite{Takeuchi2022-Chern}*{Section 2.3} for more details.

\subsection{Schoen's Theorem for CR automorphism group}

The CR sphere and the Heisenberg group play a distinguished role
in CR geometry from the viewpoint of symmetry.
To explain this,
we begin with some definitions.

\begin{definition}
	Let $(M, T^{1, 0} M)$ be a strictly pseudoconvex CR manifold of dimension $2 n + 1$.
	The \emph{CR automorphism group} $\Aut_{\CR}(M, T^{1, 0} M)$
	consists of all CR diffeomorphisms $\varphi \in \Diff(M)$
	equipped with the compact-open topology.
	We say that $\Aut_{\CR}(M, T^{1, 0} M)$ \emph{acts properly} on $M$
	if $\Set{\varphi \in \Aut_{\CR}(M, T^{1, 0} M) | \varphi(K) \cap K \neq \emptyset}$
	is relatively compact in $\Aut_{\CR}(M, T^{1, 0} M)$ for any compact set $K \subset M$.
\end{definition}

Schoen's theorem for CR automorphism group states that
$\Aut_{\CR}(M, T^{1, 0} M)$ acts properly except for
$(S^{2 n + 1}, T^{1, 0} S^{2 n + 1})$ or $(\bbH^{2 n + 1}, T^{1, 0} \bbH^{2 n + 1})$.

\begin{theorem}[\cite{Schoen1995}*{Theorems 3.3' and 3.4'}]
\label{thm:Schoen's-theorem}
	Let $(M, T^{1, 0} M)$ be a strictly pseudoconvex CR manifold of dimension $2 n + 1$.
	If the CR automorphism group $\Aut_{\CR}(M, T^{1, 0} M)$ of $(M, T^{1, 0} M)$ does not act properly on $M$,
	then $(M, T^{1, 0} M)$ is CR diffeomorphic to
	$(S^{2 n + 1}, T^{1, 0} S^{2 n + 1})$ or $(\bbH^{2 n + 1}, T^{1, 0} \bbH^{2 n + 1})$.
\end{theorem}

