where
\[
\bar Z=\frac{(1+R^2)\,(\theta_y(1)-1)^2}{2(\eta+1)^2}-\frac12.
\]

\subsubsection*{Step 6. Leading-order asymptotics for $\eta$ in nondimensional variables}
Using (\ref{eq:QPX-scaling}), we get
\begin{equation}\label{eq:qPiEtae}
\begin{aligned}
{q(x)}&=\varepsilon_1\,\sqrt{\sigma_0-\tfrac13}\, Q(\bar x);\\
p(x) &= \varepsilon_1^{3/2}P(\bar x).
\end{aligned}
\end{equation}
Therefore, we have $q=O(\varepsilon_1)$ and $p=O(\varepsilon_1^{3/2})$, and thus $|(q,p)|=O(\varepsilon_1)$ and $|(q,p,\varepsilon_1)|=O(\varepsilon_1)$, and by \eqref{eq:r-estimate} we obtain
\begin{equation}\label{eq:r-order}
\|\tilde r(v(x),\varepsilon_1)\|=O(\varepsilon_1^2),
\qquad\Rightarrow\qquad
\Pi_\eta(\tilde r(v(x),\varepsilon_1))=O(\varepsilon_1^2).
\end{equation}
Combining \eqref{eq:eta-q-leading}, \eqref{eq:qPiEtae}, and \eqref{eq:r-order} yields the nondimensional leading-order expansion
\begin{equation}\label{eq:eta-dimless-asympt}
\eta(x)=\varepsilon_1\,Q(\bar x)+O(\varepsilon_1^2),
\qquad
\bar x=\sqrt{\varepsilon_1}(\sigma_0-\tfrac13)^{-1/2}x,
\end{equation}
where $Q$ is the stationary KdV soliton \eqref{eq:homoclinic-QP}. Identifying $\varepsilon_1=\varepsilon$ via \eqref{eq:eps-def} in the regime $\omega_0=1$, we may rewrite \eqref{eq:eta-dimless-asympt} as
\begin{equation}\label{eq:eta-dimless-eps}
\eta(x)=\varepsilon\,Q(\bar x)+O(\varepsilon^2),
\qquad
\bar x=\sqrt{\varepsilon}\,(\sigma_0-\tfrac13)^{-1/2}x,
\qquad
Q(\bar x)=-3\,\sech^2(\bar x/2).
\end{equation}

Using $x=\xi=\xi_{\mathrm{phys}}/d$ and \eqref{eq:eta-phys-from-dimless}, together with $\sigma_0=\sigma=\sigma_{\mathrm{phys}}/(c^2 d)$ from \eqref{eq:nondim-params}, we compute
\[
\bar x=\sqrt{\varepsilon}\,(\sigma_0-\tfrac13)^{-1/2}x
=\sqrt{\varepsilon}\,
\Bigl(\frac{\sigma_{\mathrm{phys}}}{c^2 d}-\frac13\Bigr)^{-1/2}\,
\frac{\xi_{\mathrm{phys}}}{d}.
\]
Therefore, the leading-order solitary-wave profile in physical variables is
\begin{equation}\label{eq:eta-phys-asympt}
\eta_{\mathrm{phys}}(\xi_{\mathrm{phys}})
=
d\,\varepsilon\,
Q\!\left(\varepsilon^{\frac{1}{2}}\bigg(\frac{\sigma_{\mathrm{phys}}}{c^2 d}-\frac13\bigg)^{-\frac{1}{2}}\frac{\xi_{\mathrm{phys}}}{d}\right)
+O(\varepsilon^2),
\end{equation}
as in Theorem \ref{thm:main}.

