The purpose of this paper is to prove this elegant geometric inequality \eqref{MT} by relating it to the positivity of the hyperbolic Hamiltonian mass \cite{CCQW25} in the $(2+1)$-dimensional gravity theory \cite{St63}. The main result in this work might be viewed as an analogue of the positivity of the Brown-York mass \cite{BY93} in general relativity firstly proved by Shi and Tam in their seminal work \cite{ST-JDG02}.

Motivated by the hyperbolic version of the mass expression in \cite[Line 8 in front of Section 2, Page 2358]{ST-CQG07}, we define the Brown-York-Shi-Tam (BYST) quasi-local mass for the boundary curve $\Sigma$ as
\be\begin{split}
\m_{BYST}(\Sigma):& =\frac{1}{\pi}\int_\Sigma \big(\hat{k}-k\big)\sqrt{1+r_0^2}\d s\\
&=\frac{1}{\pi}\int_{0}^{2\pi}\big(\hat{k}-k\big)r_0\sqrt{1+r_0^2}\d \varphi.
\end{split}
\ee
Here $k$ and $\hat k$ are the geodesic curvatures with respect to the physical metric $g$ and the reference metric $g_{-1}$ respectively. The inequality \eqref{MT} is equivalent to the positivity of $\m_{BYST}$, i.e., $\m_{BYST}(\Sigma)\geq 0$.

Let $\tilde{M}_r \subset \tilde{M}$ be the region with $\partial \tilde{M}_r=\Sigma_r$. On $\tilde{M}_r\setminus \Omega$, where the scalar curvature $R(g^u)=-2$, one has
\be\label{SLE}
\begin{split}
\int_{\tilde{M}_r\setminus \Omega} \Big( |\hat\nabla\psi|^2-|\hat D \psi|^2 \Big) &=\int_{\partial \Omega} \Big <\psi,D^{\partial\Omega}\psi+\frac{k_u}{2}\psi +\frac{\sqrt{-1}}{2}c(e_2)\cdot \psi\Big >\\
& \ + \int_{\Sigma_r}\Big <(\hat\nabla_{e_{2r}}+c(e_{2r})\cdot \hat {D} ) \psi,\psi \Big >
\end{split}
\ee
where $e_{2r}$ is the outward normal of $\Sigma_r$ with respect to the metric $g^u$.

\section{A monotonicity formula}
Suppose that $u(r,\varphi)$ is a positive function. Let
\be
\m(r)=\frac{1}{\pi}\int_{0}^{2\pi}\Big(r(k_{1}-k_u)\sqrt{1+r^2}\Big)\d \varphi.\ee
Then one has the following monotonicity formula.
\be\label{mono}
\begin{split}
\frac{\d \m(r)}{\d r}&=\frac{1}{\pi}\frac{\d }{\d r}\int_0^{2\pi}r(k_1-k_u)\sqrt{1+r^2}\d\varphi\\
&=\frac{1}{\pi}\int_0^{2\pi}\frac{\partial }{\partial r}\Big(r(k_1-k_u)\sqrt{1+r^2}\Big)\d\varphi\\
&=\frac{1}{\pi}\int_0^{2\pi}\big(-r(u+\frac{1}{u}-2)+u_{\varphi\varphi}\big)\d\varphi\\
& =-\frac{r}{\pi}\int_0^{2\pi}(u+\frac{1}{u}-2)\d\varphi\\
&\leq 0.
\end{split}
\ee

If $\m_{BYST}(r_0)=0$, or equivalently $\int_{\Sigma}k\d s=\int_{\Sigma}\hat{k}\d s$, then $H^0=0$ and therefore the glued space $\tilde M$ must be the standard hyperbolic 2-space $(\mathbb{H}^2,g_{-1})$. In particular, $(\Omega,g)$ must be a domain in $(\mathbb{H}^2,g_{-1})$. Note that, in this case, $g=g_{-1}$, $L=2\pi r_0 = \mbox{Length of} \ F(\Omega)$, and again by use of the Gauss-Bonnet formula, we obtain $|\Omega|_{g}=|B_{r_0}|_{g_{-1}}$. It immediately follows from the hyperbolic isoperimetric inequality for $(\mathbb{H}^2,g_{-1})$ that $(\Omega,g)$ is a geodesic disk \cite[ Page 69]{RS10}.

\begin{thm}\label{T1}

Let $(\Omega,g)$ be a Jordan domain with boundary $\partial \Omega =\Sigma$. We choose the orthornomal frame $\{e_1,e_2\}$ so that $e_1$ is tangent to $\Sigma$ and $e_2$ is normal to $\Sigma$. The boundary curve $\Sigma$ is parameterised as
\be
[0,2\pi) \ni \varphi \mapsto i(\varphi) \in \Sigma. \ee
Denote by $L=2\pi r_0$ and $k=g(\nabla^g_{e_1}e_2,e_1)$ the length and the geodesic curvature of $\Sigma$ with respect to the outward normal $e_2$ of $\Sigma$ respectively. We can isometrically embed the boundary curve $\Sigma$ as the round circle $F(\Sigma)=\{r=r_0\}$ into the standard hyperbolic 2-space $(\mathbb{H}^2,g_{-1}=\frac{\d r^2}{1+r^2}+r^2\d \varphi^2)$ by identifying the angle parameter $\varphi$. Denote by $\hat k$ the geodesic curvature of the embedded round circle $F(\Sigma)$ in $\mathbb{H}^2$. Suppose that $K_g \geq -1$ in $\Omega$ and $k>0$ on $\Sigma$. Then one has
\be\label{MT}
\int_\Sigma k  \d s \leq \int_\Sigma \hat k \d s= 2\pi \sqrt{1+r_0^2}
\ee
Moreover, if the equality holds, then $(\Omega,g)$ must be a geodesic disk in the standard hyperbolic 2-space $(\mathbb{H}^2,g_{-1})$.\end{thm}

