Noticing that the initial relative entropy is zero, it can be obtained from (\ref{entropy}) that for any $0<t<T^*<T$, 
$$
\mathcal{H}(u_{N}^{\varepsilon}|u^{\varepsilon\otimes N})(t)\le C(m, T)(N^{-2\alpha}\varepsilon^{-6} + (N^{-1} + N^{-\eta})\varepsilon^{-4}).
$$
Combing \eqref{relative entropy} and the C-K-P inequality \eqref{CKP}, we have for $r\in\mathbb{N}$, 
\begin{align}
\sup_{t\in(0,T^*)}\|u_{N,r}^{\varepsilon}(t) - u^{\varepsilon\otimes r}(t)\|_{L^1(\R^{2r})} 
&\le \sup_{t\in(0,T^*)}2\mathcal{H}_r(u_{N,r}^{\varepsilon}|u^{\varepsilon\otimes r})(t)\nonumber\\
&\le \sup_{t\in(0,T^*)}4r\mathcal{H}(u_{N}^{\varepsilon}|u^{\varepsilon\otimes N})(t)\nonumber\\
&\le C(m, T)(N^{-2\alpha}\varepsilon^{-6} + (N^{-1} + N^{-\eta})\varepsilon^{-4}).
\end{align}
According to Theorem \ref{propagation of chaos}, we know that 
\begin{align}
&0<\eta\le\min\{\theta-2\alpha,-(4m+4)\gamma-2\alpha +m(1-2\theta)-1\},\label{eta1}\\
&0<\gamma\le\min\{\frac{\alpha}{3},\frac{-2\alpha + m(1-2\theta)-1}{4m+4}\}. \label{gamma1} 
\end{align}
Based on the previous assumption $\varepsilon\sim N^{-\gamma}$, it holds that there exists $\beta>0$ such that 
\begin{align}
N^{-2\alpha}\varepsilon^{-6} + (N^{-1} + N^{- \eta})\varepsilon^{-4}=\varepsilon^\frac{2\alpha}{\gamma}\varepsilon^{-6}+(\varepsilon^\frac{1}{\gamma}+\varepsilon^\frac{\eta}{\gamma})\varepsilon^{-4}\le \varepsilon^\beta, 
\end{align}
where $\beta$ satisfies
$$1<\beta\le\min\{\frac{2\alpha}{\gamma}-6,\frac{\eta}{\gamma}-4\}.$$ 
Here we have used $\eta<1$.
This further requires that $0<\gamma<\frac{2\alpha}{7}$, $\eta>5\gamma$. Building on the assumptions in \eqref{eta1} and \eqref{gamma1}, we assume
\begin{align*}
&0<\gamma<\min\{\frac{2\alpha}{7},\frac{-2\alpha + m(1-2\theta)-1}{4m+4}\},\\
&5\gamma<\eta<\min\{\theta-2\alpha,-(4m+4)\gamma-2\alpha +m(1-2\theta)-1\}.
\end{align*} 
Then we obtain that for $0<t<T^*<T$, 
\begin{align}
\sup_{t\in(0,T^*)}\|u_{N,r}^{\varepsilon}(t) - u^{\varepsilon\otimes r}(t)\|_{L^1(\R^{2r})} \le C(m,T)\varepsilon^\beta,\quad \beta>1.
\end{align}
Thus, we complete the proof of propagation of chaos. 
\end{proof}

post_theorem_intro_text:
\begin{remark}
To see the value of $\gamma$ and $\eta$ more clearly, we provide a special case. When $m\in\mathbb{N}^+$, $ m\ge\frac{1+\theta}{1-2\theta}$ and $0<\alpha<\frac{\theta}{2}<\frac{1}{2}$, we take $\alpha=0.1$, $\theta=0.3$ and $m=4$ such that
$0<\gamma<\min\{\frac{\alpha}{3},\frac{-2\alpha +m(1-2\theta)-1}{2(2+2m)}\}=\min\{0.033,0.02\}=0.02$. we may assume that $\gamma=0.019$, then $0<\eta\le\min\{\theta-2\alpha,-2\gamma(2+2m)-2\alpha -m(2\theta -1)-1\}=\min\{0.1, 0.02\}=0.02$. 
\end{remark}

The  proof of Theorem \ref{propagation of chaos}, given in Section 2, follows the approach of \cite{lazarovici2017mean}, adopting a superior algebraic scaling with respect to the maximum norm of the trajectory, which \cite{BOL2026113712} only achieved results under logaritheoremic scaling. 
Since the diffusion coefficients in the stochastic models \eqref{sde} and \eqref{mfs} given the nonlinear dependence of the diffusion coefficients on inter-particle interactions, the use of the Burkholder-Davis-Gundy inequality becomes indispensable. The key ingredient of our proof is the introduction of stopping times, a technique that facilitates the application of the Law of Large Numbers. 

Based on the uniform $L^\infty(0,T^*;H^2(\mathbb{R}^2))$ bound for $\nabla\log u_\varepsilon$ in Lemma \ref{weak solution} and the propagation of chaos established in Theorem \ref{propagation of chaos}, our next main result addresses the strong $L^1$ convergence for the propagation of chaos. The proof is mainly presented in Section 3, employing the relative entropy method \cite{jabin2018quantitative} as recently refined in \cite{chen2025quantitative}.

\begin{theorem}\label{Propagation of chaos in the strong sense}\textup{(Propagation of chaos in the strong sense).} 
Under the assumptions of Theorem \ref{propagation of chaos}, let $r\in \mathbb{N^+}$, $u_{N,r}^\varepsilon(t, x_1,\cdots, x_r)$ be the $r$-th marginal density of the joint density $u_N^\varepsilon(t, x_1,\cdots, x_N)$ of $\{X_{N,i}^\varepsilon\}_{1\le i\le N}$, and $u^{\varepsilon \otimes r}(t, x_1,\cdots, x_r)$ be the tensor product of the solutions $u^{\varepsilon}$ to the model \eqref{rpde}. Then for parameters $0<\theta<1/2$, $0 <\alpha<\frac{\theta}{2}$, and $m\in \mathbb{N}^+$ satisfying $m \ge \frac{1+\theta}{1-2\theta}$, there exist a time $T^*\in(0,T)$, a constant $C(m,r,T)>0$, and a parameter $\beta>0$ satisfying the bound $1<\beta\le\min\{\frac{2\alpha}{\gamma}-6,\frac{\eta}{\gamma}-4\}$ such that 
\begin{align}\label{Ps111}
\|u_{N,r}^{\varepsilon}(t) - u^{\varepsilon\otimes r}(t)\|_{L^\infty(0,T^*;L^1(\mathbb{R}^{2r}))} \le C(r,m,T)\varepsilon^{\beta}, 
  \end{align}
where the cut-off parameter satisfies
$\varepsilon\sim N^{-\gamma} $,
and the parameter $\gamma$ defined by
$$0<\gamma<\min\{\frac{2\alpha}{7},\frac{-2\alpha + m(1-2\theta)-1}{4m+4}\},$$
and the parameter $\eta$ satisfies
$$5\gamma<\eta<\min\{\theta-2\alpha,-(4m+4)\gamma-2\alpha +m(1-2\theta)-1\}.$$ 
\end{theorem}
\begin{remark}
To illustrate the feasible range of parameters, we give an explicit example. Choose $\theta = 0.4,\ \alpha = 0.1$ and $m\ge \frac{1+\theta}{1-2\theta}=7$ such that $m=7$.
Then we obtain
$$0<\gamma<\min\{\frac{2\alpha}{7},\frac{-2\alpha + m(1-2\theta)-1}{4m+4}\}=\min\{0.029,0.006\}=0.006.$$
Taking $\gamma=0.0025$ gives
$$0.0125=5\gamma<\eta<\min\{\theta-2\alpha,-(4m+4)\gamma-2\alpha +m(1-2\theta)-1\}=\min\{0.2,0.12\}=0.12.$$
so we pick $\eta=0.03$. Finally, $$1<\beta\le\min\{\frac{2\alpha}{\gamma}-6,\frac{\eta}{\gamma}-4\}=\min\{74,8\}=8$$
we take $\beta = 8$.
With these choices, the propagation of chaos estimate becomes
\begin{align*}
\max_{i=1,\cdots,N}\mathbb{E}\big(\sup_{t\in[0,T]}\big|(X_{N,i}^\varepsilon - \overline{X}_i^\varepsilon)(t)\big|^2\big)\le C\varepsilon^8, 
\end{align*} 
\end{remark}
We comment here that the convergence of the mean-field limit have already been discussed in \cite{BOL2026113712}. It is therefore especially gratifying that our results accelerate the convergence rates  for the solutions to the SDE \eqref{sde} and \eqref{mfs} across different norms. Specifically, Chen et al. in \cite[Theorem 3]{BOL2026113712} presented as
\begin{align*}
\max_{i=1,\cdots,N}\mathbb{E}\big(\sup_{t\in[0,T]}\big|(X_{N,i}^\varepsilon - \overline{X}_i^\varepsilon)(t)\big|^2\big)\le C\varepsilon^2, 
\end{align*}   
where the cut-off parameter $\varepsilon=(\lambda\log N)^{-\frac{1}{4}}$. However, in \eqref{Pe}, we prove algebraic convergence in contrast to logarithmic convergence established in \cite{BOL2026113712}. This represents an  improvement in the convergence rate. Furthermore, in \cite[Theorem 5]{BOL2026113712}, they obtained
\begin{align*}
\|u_{N,r}^{\varepsilon}(t) - u^{\varepsilon\otimes r}(t)\|_{L^\infty(0,T^*;L^1(\mathbb{R}^{2r}))}^2 \le C(r,m,T)\varepsilon.
\end{align*}
By contrast, our estimate in \eqref{Ps111} yields a  faster convergence rate than that bound.

The article is organized as follows. In section 2, we establish the propagation of chaos, which corresponds to the convergence in probability of solutions to the stochastic differential equations \eqref{sde} and \eqref{mfs}. Section 3 further derive quantitative propagation of chaos result in the strong sense by applying the relative entropy method.

