\begin{theorem}\label{teo:areaengel}
	Let $\Sigma \subset \G$ be a $2$-dimensional $C^{1,\alpha}$ regular submanifold with $d(\Sigma)\le 4$. Then the following formula holds for every Borel set $B \subset \Sigma$  
	\begin{equation}\label{areafo}
		\mu_\Sigma(B) = \int_B \lvert \tau_{\Sigma, N}(p)\rvert_g d\sigma_g(p) = \int_B \beta_d(A_p \Sigma) \ d \mathcal{S}^N (p),
	\end{equation}
whenever $(d(\Sigma)-2)/d(\Sigma)<\alpha\le 1$.
