ref_dict.gradosulbordo:
\begin{lemma}\label{gradosulbordo}
If $\Sigma \subset \E$ is a $2$-dimensional $C^1$ smooth submanifold with boundary $\partial \Sigma$, then 
for every $p\in\partial \Sigma$ we have 
$d_{\partial \Sigma}(p) \leq d_{\Sigma}(p) - 1$ and in particular
    \begin{equation}\label{thesisgrado}
    d(\partial \Sigma) \leq d(\Sigma) - 1.
    \end{equation}
\end{lemma}

ref_dict.genres:
\begin{theorem}[Upper blow-up]\label{genres}
Let $\Sigma \subset \mathbb{G}$ be a smooth $k$-dimensional submanifold of class $C^1$ and 
degree $\NN$. Let $p \in \Sigma$ be a point of maximum degree $\NN$. 
 For the translated submanifold
$
\Sigma_p = p^{-1}\Sigma,
$
we introduce the $C^1$ smooth homeomorphism $\eta : \R^k \rightarrow \R^k$ by
\begin{equation}\label{funzioneeta}
\eta(t) = \Big(\frac{\lvert t_1 \rvert^{b_1}}{b_1}{\rm sgn}(t_1), \ldots, \frac{\lvert t_p \rvert^{b_k}}{b_k}{\rm sgn}(t_k)\Big)
\end{equation}
where $b_i$ is the induced degree, defined as follows
\begin{equation}\label{inducedb}
    b_i = j \quad \mbox{if and only if } \mu_{j - 1} < i \leq \mu_j
\end{equation}
for every $i=1 \ldots,k$,
where $\mu_j$ are defined in \eqref{def:mu_j}.
If $\phi$ denotes the mapping of Theorem~\ref{t:specialcoord}
applied to 
$\Sigma_p$, we define the $C^1$ smooth mapping
\begin{equation}\label{funzionegamma}
  \Gamma = \phi \circ \eta  
\end{equation}
and we set the subset of indexes $I \subset \{1,\ldots, n\}$ such that
\begin{equation*}
        A_0 \Sigma = { \rm span} \{ 
        e_1, \ldots, e_{\alpha_1}, e_{m_1 + 1}, \ldots, e_{m_1 + \alpha_2}, \ldots, e_{m_{\iota- 1} + 1}, \ldots, e_{m_{\iota -1} + \alpha_\iota}
        \}.
\end{equation*} 
Using notation and definitions of \cite[Theorem~3.1]{Magnani2019Area}, 
	if we assume the validity of the local expansion   
	\begin{equation}\label{localexp}
		\Gamma_s(t) = 
		\begin{cases}
			\frac{\lvert t_{s - m_{d_s - 1} + \mu_{d_s - 1}}\rvert^{d_s}}{d_s} {\rm sgn}(t_{s - m_{d_s - 1} + \mu_{d_s - 1}}) \;\; \mbox{if } s \in I \\
			o(\lvert t \rvert^{d_s}) \quad \quad \mbox{if } s \not \in I
		\end{cases},
	\end{equation}
	and $\beta_d \big(A_p \Sigma \big)$ denotes the \emph{spherical factor} associated to the homogeneous tangent space $A_p \Sigma$ in \eqref{sfe}, then
	\begin{equation}\label{eq:betadens}
	\theta^N(\mu_\Sigma, p) = \beta_d \big(A_p \Sigma \big).
	\end{equation}
\end{theorem}

ref_dict.Gammas:
\begin{proposition}\label{Gammas}
Let $\Sigma \subset \E$ be a $C^1$ smooth surface with $d(\Sigma) = 3$. If $p \in \Sigma$ is a point of maximum degree, then 
     \begin{equation}\label{mainequality}
\theta^3(\mu_\Sigma, p) = \beta_d \big(A_p \Sigma \big).
    \end{equation}
\end{proposition}

ref_dict.mainstokestheorem:
\begin{theorem}\label{mainstokestheorem}
Let $\Sigma \subset \E$ be a $2$-dimensional $C^1$ smooth submanifold of degree 3. If $p\in\Sigma$ is a point of maximum degree $3$, 
then the orthonormal graded basis $(Y_1,Y_2,Y_3,Y_4)$ provided by Theorem~\ref{t:specialcoord} and having the
structure coefficients $\xi_{ij}$ given by \eqref{structurecoeff} must have $\xi_{13} = 0$.
\end{theorem}

ref_dict.teotrascu:
\begin{theorem}\label{teotrascu}
	Let $\Sigma\subset\E$ be a $2$-dimensional $C^{1,\alpha}$ smooth submanifold with $2\le d(\Sigma)\le 4$ and let $C(\Sigma)\subset \Sigma$ be the subset of points of degree less than $d(\Sigma)$. Then we have
	\begin{equation}\label{eq:SN0}
		\mathcal{S}^{d(\Sigma)}(C(\Sigma)) = 0
	\end{equation}
	whenever $(d(\Sigma)-2)/d(\Sigma)<\alpha\le 1$. 
\end{theorem}

ref_dict.teo:areageneral:
\begin{theorem}\label{teo:areageneral}
Let $\mu$ be a regular measure and a Borel measure over a homogeneous group $\G$, 
and let $a>0$. We fix a Borel set $A \subset \G$ and
assume that the following conditions hold:
\begin{enumerate}
    \item $A$ has a countable covering whose elements are open and have $\mu$-finite measure,
    \item the subset $\{x \in A : \theta^a(\mu,x) = 0\}$ is $\sigma$-finite with respect to $\mathcal{S}^a$,
    \item $\mu \mres A$ is absolutely continuous with respect to $\mathcal{S}^a \mres A$.
\end{enumerate}
Then $\theta^a(\mu, \cdot) : A \to [0,+\infty]$ is Borel and for every Borel set $B \subset A$ we have
\begin{equation*}
        \mu(B) = \int_B \theta^a(\mu, p) d \mathcal{S}^a(p).
    \end{equation*}
\end{theorem}

ref_dict.horizontalnon:
\begin{theorem}\label{horizontalnon}
There does not exist any $C^1$ smooth surface of degree $2$ in the Engel group.
\end{theorem}

ref_dict.Gammas2:
\begin{proposition}\label{Gammas2}
    Let $\Sigma \subset \E$ be a  $C^1$ smooth surface with degree $d(\Sigma)=4$. Let $p \in \Sigma$ be a point of maximum degree, then 
     \begin{equation}\label{mainequality2}
        \theta^4(\mu_\Sigma, p) = \beta_d \big(A_p \Sigma \big).
    \end{equation}
\end{proposition}

post_theorem_intro_text:
The intrinsic measure $\mu_\Sigma$ is introduced in Definition~\ref{intrinsicmeas} and $\beta_d(A_p \Sigma)$ is the \textit{sherical factor}, see Definition~\ref{sfe}. 
Combining Proposition \ref{Gammas}, Proposition \ref{Gammas2}, Theorem \ref{genres}, Theorem~\ref{teo:areageneral}, Theorem~\ref{teotrascu}, and Theorem~\ref{horizontalnon} the proof of Theorem~\ref{teo:areaengel} follows.
We point out that Theorem~\ref{teo:areageneral} could be also replaced by the general tool in \cite[Theorem~1.2]{CorMag25}.

If we equip the Engel group with a multiradial distance,
see \cite[Definition 1.3]{CorMag25}, we can apply
\cite[Theorem 1.5]{CorMag25}, that joined with 
Theorem \ref{teo:areaengel} gives the following.
\begin{corollary}
Let $\mathbb{E}$ be the Engel group equipped with a multiradial distance $d$. Let $\Sigma \subset \mathbb{E}$ be a $2$-dimensional $C^{1,\alpha}$ regular submanifold with $d(\Sigma)=N\leqslant 4$. Thus, setting $\mathcal{S}_d^N=\omega_d(\mathcal{F}_{1,1,0}) \mathcal{S}^N$ if $N=3$ and $\mathcal{S}_d^N=\omega_d(\mathcal{F}_{1,0,1}) \mathcal{S}^N$ if $N=4$ according to \cite[Theorem~3.3]{CorMag25}, for every Borel set $B \subset \Sigma $ we have
\begin{equation}\label{areafo}
    \mathcal{S}_d^N(B) = \int_B \lvert \tau_{\Sigma, N}(p)\rvert_g d\sigma_g(p)
\end{equation}
whenever $(d(\Sigma)-2)/d(\Sigma)<\alpha\leqslant 1$.
\end{corollary}
Useful examples of multiradial distances are the distance $d_{\infty}$, \cite{FSSC5}, and the family of homogeneous distances arising from \cite[Theorem 2]{HebSik90}.
We close this introduction stating another corollary of Theorem~\ref{teo:areaengel}, that is more manageable for applications and relies on the area formula for 
transversal submanifolds abd curves of class $C^1$, \cite[Theorem~1.3]{Magnani2019Area}. Indeed surfaces of degree five and hypersurfaces in $\E$ are precisely transversal submanifolds, namely they have the highest possible Hausdorff dimension among all $C^1$ surfaces.

\begin{corollary}\label{cor:areaengel}
For every submanifold $\Sigma \subset \E$ 
of class $C^{1,\alpha}$ with $\alpha>1/2$,
the following area formula holds   
	\begin{equation}\label{areafo}
		\mu_\Sigma(B) = \int_B \lvert \tau_{\Sigma, N}(p)\rvert_g d\sigma_g(p) = \int_B \beta_d(A_p \Sigma) \ d \mathcal{S}^N (p)
	\end{equation}
for every Borel set $B \subset \Sigma$.
\end{corollary}

