\begin{theo}\label{higherdim}
Let $E \subset \mathbb{R}^n$ be a Borel or analytic set. Then

(i) $\dh\mbox{\rm proj}_V E \leq \min\{\dh E, m\}$  with equality for $\gamma_{n,m}$-almost all $V \in G(n,m)$,
\smallskip

(ii) if $\dh E >m$ then ${\mathcal L}^m (\mbox{\rm proj}_V E) > 0$ for $\gamma_{n,m}$-almost all $V \in G(n,m)$. 
\end{theo}

ref_dict.marthm:
\begin{theo}\label{marthm}
Let $E \subset \mathbb{R}^2$ be a Borel or analytic set. Then

(i) $\dh \mbox{\rm proj}_\theta E \leq \min\{\dh E, 1\}$ with equality for almost all $\theta \in [0,\pi)$,
\smallskip

(ii) if $\dh E >1$ then ${\mathcal L} (\mbox{\rm proj}_\theta E) > 0$ for almost all $\theta \in [0,\pi)$.
\end{theo}

