\begin{corollary}
 \label{cor:proper_dualizing}
 Let $f\colon \mathcal{Y}\to \mathcal{X}$ be a concentrated proper Deligne--Mumford morphism of Noetherian algebraic $\mathbb{Q}$-stacks where $\mathcal{X}$ has a separated diagonal. If $K$ is a dualizing complex on $\mathcal{X}$, then $f^\times K$ is a dualizing complex on $\mathcal{Y}$.
\end{corollary}

\begin{notation}
 \label{not:neeman}
 We assume a $2$-subcategory $\mathbb{S}_{\mathbf{e}}$ of the $2$-category of Noetherian algebraic stacks following \cite[Notation 1.1]{Neeman:2023}. The $2$-morphisms are any $2$-morphism in the category of algebraic stacks between $1$-morphisms in $\mathbb{S}_{\mathbf{e}}$. Its objects are Noetherian algebraic stacks $\mathcal{X}$ with quasi-affine diagonals for which there exists an \'{e}tale, surjective, separated morphism $\mathcal{X}^\prime \to \mathcal{X}$ which is representable by algebraic spaces and of finite presentation, where $\mathcal{X}^\prime$ satisfies the resolution property and one of the following: $\mathcal{X}^\prime$ is a $\mathbb{Q}$-stack or $\mathcal{X}^\prime$ has quasi-finite diagonal.

\begin{lemma}
 \label{lem:rep_by_space_finite_type_pullback_dualizing}
 Let $\mathbb{S}_{\mathbf{e}}$ be a $2$-subcategory as in \Cref{not:neeman}. Consider a morphism $(f\colon \mathcal{Y}\to \mathcal{X})\in \mathbb{S}_{\mathbf{e}}$ of finite presentation and a smooth surjective morphism $(s\colon U \to \mathcal{X}) \in \mathbb{S}_{\mathbf{e}}$ from a scheme. If $f$ is representable by algebraic spaces and $K$ is a dualizing complex on $\mathcal{X}$, then $f^! K$ is a dualizing complex on $\mathcal{Y}$. 
\end{lemma}

\begin{proposition}
 \label{prop:existence_DM}
 Let $\mathbb{S}_{\mathbf{e}}$ be a $2$-subcategory as in \Cref{not:neeman} which is closed under \'{e}tale morphisms to objects; that is, if $\mathcal{X}\in \mathbb{S}_{\mathbf{e}}$ and $\mathcal{Y}\to \mathcal{X}$ is \'{e}tale, then $\mathcal{Y}\in \mathbb{S}_{\mathbf{e}}$. Consider a Deligne-Mumford morphism $(f\colon \mathcal{X}\to S)\in \mathbb{S}_{\mathbf{e}}$ of presentation from an algebraic stack to an algebraic space. If $K$ is a dualizing complex on $S$, then $f^! K$ is a dualizing complex on $\mathcal{X}$. 
\end{proposition}

\begin{theorem}
 \label{thm:DM_morphism_dualizing}
 Let $\mathbb{S}_{\mathbf{e}}$ be a $2$-category as in \Cref{not:neeman} which is closed under \'{e}tale morphisms to objects. Consider a Deligne--Mumford morphism $(f\colon \mathcal{Y}\to \mathcal{X})\in \mathbb{S}_{\mathbf{e}}$ of finite presentation. If $K$ is a dualizing complex on $\mathcal{X}$, then $f^! K$ is a dualizing complex on $\mathcal{Y}$.
\end{theorem}

\begin{proof}
 [Proof of \Cref{cor:proper_dualizing}]
 Choose a smooth surjective morphism $s\colon U \to \mathcal{X}$ from an affine scheme. Consider the fibered square
 \begin{displaymath}
 \begin{tikzcd}
 {\mathcal{Y}\times_{\mathcal{X}} U} & U \\
 {\mathcal{Y}} & {\mathcal{X}.}
 \arrow["{f^\prime}", from=1-1, to=1-2]
 \arrow["{s^\prime}"', from=1-1, to=2-1]
 \arrow["s", from=1-2, to=2-2]
 \arrow["f"', from=2-1, to=2-2]
 \end{tikzcd}
 \end{displaymath}
 Here, $f^\prime$ is a concentrated proper morphism of Noetherian Deligne--Mumford $\mathbb{Q}$-stacks with separated diagonals. Recall that \Cref{prop:dualizing_complex_for_stacks} tells us $\mathbf{L}s^\ast K$ is a dualizing complex for $U$. By \Cref{thm:DM_morphism_dualizing_char_zero_case}, it follows that $(f^\prime)^! \mathbf{L}s^\ast K$ is a dualizing complex on $\mathcal{Y}\times_{\mathcal{X}} U$. Note that $(f^\prime \colon \mathcal{Y}\times_{\mathcal{X}} U \to U)\in\mathbb{S}_{\mathbf{e}}$ where $\mathbb{S}_{\mathbf{e}}$ is the case of \Cref{ex:neeman_char_zero}. Hence, by \Cref{rmk:neeman_upper_shriek2}, properness of $f^\prime$ promises that there is a natural isomorphism $(f^\prime)^\times \to (f^\prime)^!$. So, $(f^\prime)^\times \mathbf{L}s^\ast K$ is a dualizing complex. Then \cite[Lemma 0.1]{Neeman:2023} implies that the base change morphism $\mathbf{L}(s^\prime)^\ast f^\times K \to (f^\prime)^\times \mathbf{L}s^\ast K$ is an isomorphism. Hence, $\mathbf{L}(s^\prime)^\ast f^\times K$ is a dualizing complex. However, $s^\prime$ is a concentrated smooth surjective morphism, so \Cref{cor:smooth_morphism_ascend_descend} and \Cref{lem:lisse-etale_pullback_and_qc_pullback} promises that $f^\times K$ is a dualizing complex as desired.
\end{proof}

\begin{corollary}
    \label{cor:proper_dualizing}
    Let $f\colon \mathcal{Y}\to \mathcal{X}$ be a concentrated proper Deligne--Mumford morphism of Noetherian algebraic $\mathbb{Q}$-stacks where $\mathcal{X}$ has a separated diagonal. If $K$ is a dualizing complex on $\mathcal{X}$, then $f^\times K$ is a dualizing complex on $\mathcal{Y}$.
\end{corollary}

\begin{theorem}
    \label{thm:DM_morphism_dualizing}
    Let $\mathbb{S}_{\mathbf{e}}$ be a $2$-category as in \Cref{not:neeman} which is closed under \'{e}tale morphisms to objects. Consider a Deligne--Mumford morphism $(f\colon \mathcal{Y}\to \mathcal{X})\in \mathbb{S}_{\mathbf{e}}$ of finite presentation. If $K$ is a dualizing complex on $\mathcal{X}$, then $f^! K$ is a dualizing complex on $\mathcal{Y}$.
\end{theorem}

\begin{theorem}
    \label{thm:DM_morphism_dualizing_char_zero_case}
    Let $f\colon \mathcal{Y}\to \mathcal{X}$ be a separated morphism of finite presentation between Deligne--Mumford $\mathbb{Q}$-stacks. Assume $\mathcal{X}$ is Noetherian and has a separated diagonal. If $K$ is a dualizing complex on $\mathcal{X}$, then $f^! K$ is a dualizing complex on $\mathcal{Y}$.
\end{theorem}

post_theorem_intro_text:
In fact, we prove a more general statement; see \Cref{thm:DM_morphism_dualizing}. Note that we use the upper shriek functor $f^!$ rather than the right adjoint $f^\times$ of $\mathbf{R}f_\ast$. Consequently, this yields existence of dualizing complexes in broad generality.

\begin{corollary}
    Let $S$ be a Noetherian $\mathbb{Q}$-scheme admitting a dualizing complex. Then dualizing complexes exist for any Deligne--Mumford stack which is of finite presentation and separated over $S$.
\end{corollary}

Concretely, examples include every separated Deligne--Mumford stack of finite presentation over a field of characteristic zero. Notably, there are no properness constraints. Moreover, we prove a relative analog of \Cref{thm:DM_morphism_dualizing_char_zero_case}:

\begin{corollary}
    \label{cor:proper_dualizing}
    Let $f\colon \mathcal{Y}\to \mathcal{X}$ be a concentrated proper Deligne--Mumford morphism of Noetherian algebraic $\mathbb{Q}$-stacks where $\mathcal{X}$ has a separated diagonal. If $K$ is a dualizing complex on $\mathcal{X}$, then $f^\times K$ is a dualizing complex on $\mathcal{Y}$.
\end{corollary}

Observe that \Cref{cor:proper_dualizing} involves the right adjoint of the derived pushforward $\mathbf{R}f_\ast$. This leverages a base change result for the functors \cite[Lemma 0.1]{Neeman:2023}, which allows us to reduce to a setting where $f^\times \cong f^!$. In particular, the upper shriek exists in said reduction, whereas it is not clear whether it does in the generality of \Cref{cor:proper_dualizing} a priori.

The proofs combine Nagata compactification techniques with upper shriek base change formulas of \cite[Theorem 1.8]{Neeman:2023}. Nagata compactifications for algebraic spaces were established in \cite{Conrad/Lieblich/Olsson:2012}, whereas the Deligne--Mumford case relies on forthcoming work by \cite{Rydh:2026}. Whenever possible, we reduce arguments to the algebraic space setting, allowing us to invoke results such as \cite[Lemma 2.7]{Lyu/Murayama:2022}. The restriction to $\mathbb{Q}$-stacks is essential for the applications considered here with compactifications (see \Cref{ex:neeman_char_zero}). Extending these existence results to mixed and positive characteristic remains an open direction.

\subsection{Why it matters}
\label{sec:intro_why_it_matters}

We expect our results to extend further as the theory of Nagata compactifications develops, for example in positive characteristic. Moreover, there is growing interest in birational geometry and the minimal model program for algebraic spaces and stacks over $\mathbb{Q}$; see e.g.\ \cite{Kresch/Tschinkel:2023,Enokizono/Hashizume:2026,Lyu/Murayama:2022}. As singularities are studied in these frameworks, the existence of dualizing complexes will play an increasingly important role, for which our results also become increasingly relevant.

