(\cite[Conjecture 4.6]{Rui2026})\label{conjsymetrycmHZv}
Let $x_1,\ldots,x_r$ be roots of unity and $a\in \mathbb{C}\setminus \mathbb{Z}$. For $\bfk=(k_1,\ldots,k_r)\in \mathbb{N}^r$ and $(k_1,x_1),\ (k_r,x_r)\neq (1,1)$, we have
\begin{align*}
\Li_{k_1,\ldots,k_r}(x_1,\ldots,x_r;a)\equiv  (-1)^{k_1+\cdots+k_r-1} (x_1\cdots x_r) \Li_{k_r,\ldots,k_1}(x^{-1}_r,\ldots,x_1^{-1};1-a)\quad (\text{mod products}),
\end{align*}
where ``mod products" means discarding all product terms of cyclotomic multiple Hurwitz zeta values with depth $<r$.

ref_dict.main-thm-corthree:
\begin{cor}\label{main-thm-corthree}
Let $x_1,\ldots,x_r$ be roots of unity and $a_1,\ldots,a_r\in \mathbb{C}\setminus \Z$ satisfy $a_j-a_i\notin \N^-$ for $i< j\ (i,j\in \{1,2,\ldots,r\})$. For $\bfk_{1,r}=(k_1,\ldots,k_r)\in \N^r$ and $(k_r,x_r),\ (k_1,x_1)\neq (1,1)$, we have
\begin{align*}
&\Li_{k_1,\ldots,k_r}(x_1,\ldots,x_r;a_1,\ldots,a_r)\\
&\equiv  (-1)^{k_1+\cdots+k_r-1} (x_1\cdots x_r) \Li_{k_r,\ldots,k_1}(x^{-1}_r,\ldots,x_1^{-1};1-a_r,\ldots,1-a_1)\quad (\text{mod products}),
\end{align*}
where ``mod products" means discarding all product terms of cyclotomic multiple Hurwitz zeta values of smaller depth.
\end{cor}

