There exists a minimizing couple $(u,\ell)$ of the following problem in both variables
\begin{equation}
 \label{pb min}
 \min\left \{E_\eps(u,\ell), \, u \in H^{1}(\C) \text{ such that } 0\leqslant u \leqslant 1 , \, u = 1 \text{ on } \partial{\C} \text{ and } \ell \in \curve^\Lambda(\gamma_0,\gamma_1) \right\}.
\end{equation}

The study of this energy is motivated by the $\Gamma$-convergence result established in \cite{bonnivard2025phasefieldapproximationplateaus}, where this decoupled functional was introduced both in the proof of the $\Gamma$-convergence and for numerical applications. Recall that the phase-field approach they proposed is a generalization to Plateau’s problem of the method introduced in \cite{bonnivard2015approximation} for Steiner’s problem. A similar study of the existence of solutions for the decoupled functional in the Steiner case was carried out in \cite{bonnivard2018phase}. The present work is inspired by this paper, but there are some differences that we explain below.

We begin by studying the following minimization problem 
\begin{equation}
\label{pb min l fixe}
 \inf_{u} E_\varepsilon(u,\ell), \text{ where } \ell \in \curve^\Lambda(\gamma_0,\gamma_1).
\end{equation}
The following Proposition will be proven in Section~\ref{section l fixe}. 
\begin{proposition}
For any given $\ell \in \curve^\Lambda(\gamma_0, \gamma_1)$, there exists a unique minimizer $u \in H^1(\Ccal)$ of $ E_\varepsilon(\cdot,l)$ which is globally $C^{0,\alpha}$, for all $0< \alpha <1$: there exists a constant $C_\alpha>0$ such that 
\[\|u \|_{C^{0,\alpha}(\mathcal{C})} \leqslant C_\alpha \frac{1+\Lambda c_\varepsilon ^{-1}}{\varepsilon^{\alpha}}.\]
\end{proposition}
The assumption that the surface $S_\ell$ is $\Lambda$-upper Ahlfors regular is the key ingredient to establish lower semi-continuity, and hence the existence of minimizers in this setting. We then apply classical results from elliptic regularity to derive Hölder estimates for the minimizer. Note that these estimates depend explicitly on $\Lambda$ and $\varepsilon$, but are independent of the specific surface $S_\ell$. This part is strongly inspired by \cite{bonnivard2018phase}.

\begin{proposition}
\label{prop holder}
Let $\ell \in~\curve^\Lambda(\gamma_0,\gamma_1)$ and let $u$ be the minimizer of $E_\varepsilon^\ell$. Then, $u$ is $\alpha$-Hölder continuous for all $0<\alpha<1$ with the estimate:
\[\|u\|_{C^{0,\alpha}(\mathcal{C})} \leqslant C_\alpha \frac{1+\Lambda c_\varepsilon ^{-1}}{\varepsilon^{\alpha}}.\]
\end{proposition}

\begin{lemma}
\label{lem 2.10}
Recall the definition of the parameter $\eta_0 = \dist(\partial \Ccal_0,\partial \Ccal)$ introduced in the previous Lemma.
Let $\ell \in \curve^\Lambda(\gamma_0, \gamma_1)$, $0< \rho < \min(1,\frac{\eta_0}{4})$ and $x_0 \in \mathcal{C}$ such that $\dist(x_0,\partial \mathcal{C}) \geqslant \frac{\eta_0}{2} $. Then, $u \in W^{1,p}(B(x_0,\rho))$ for all $3\leqslant p < \infty$ and we have the following estimate on the rescaled function $u_\rho (x) := u(x_0+\rho x)$
\begin{equation}
 \|\nabla u_\rho\|_{L^p(B_1)} \leqslant C_p\left( \frac{\rho^2}{\varepsilon^2}+1+\frac{\Lambda \rho}{c_\varepsilon \varepsilon}\right).
\end{equation}
\end{lemma}

\medskip
\emph{Step 3.} We define the rescaled function $u_\rho$ on $B_2$ by $u_\rho(x) := u(x_0+\rho x)$. Then, for all $\varphi \in C^\infty_c(B_2)$ 
\begin{align*}
 \int_{B_2}\nabla u_\rho \cdot \nabla\varphi \dm x &= \frac{1}{\rho}\int_{B(x_0,2\rho)}\nabla u \cdot \nabla\varphi_\rho \dm x,\\
 &= \frac{1}{\rho4\varepsilon^2}\int_{B(x_0,2\rho)}(1- u)\varphi_\rho \dm x - \frac{1}{\rho c_\varepsilon \varepsilon}B[\ell](u,\varphi_\rho),\\
 &= \frac{\rho^2}{4\varepsilon^2}\int_{B_2}(1- u_\rho)\varphi \dm x - \frac{1}{\rho c_\varepsilon \varepsilon}\langle T_\rho,\varphi \rangle.
\end{align*}
Hence, $u_\rho$ satisfies the following PDE in $\mathcal{D}'(B_2)$
\[-\Delta u_\rho = \frac{\rho^2}{4\varepsilon^2}(1- u_\rho) - \frac{1}{\rho c_\varepsilon \varepsilon} T_\rho.\]
We denote $w_\rho := u_\rho + \frac{1}{\rho c_\varepsilon \varepsilon}v_\rho \in H^1(B_2)\cap L^\infty(B_2)$. And we deduce that 
\[-\Delta w_\rho = \frac{\rho^2}{4\varepsilon^2}(1- u_\rho) \text{ in } \mathcal{D}'(B_2). \]
Thus, \cite[Corollary 8.36]{gilbargelliptic} yields that $w_\rho \in C_{\mathrm{loc}}^{1,\alpha}(B_2)$ for all $\alpha >0$ and 
\begin{align*}
 \|\nabla w_\rho\|_{L^\infty(B_1)} \leqslant \|w_\rho\|_{C^{1,\alpha}(B_1)} &\leqslant C\left(\| w_\rho\|_{L^\infty(B_1)} +\frac{\rho^2}{4\varepsilon^2}\|1- u_\rho\|_{L^\infty(B_1)}\right),\\
 &= C\left(\| u_\rho\|_{L^\infty(B_1)}+ \frac{1}{\rho c_\varepsilon \varepsilon}\| v_\rho\|_{L^\infty(B_1)} +\frac{\rho^2}{4\varepsilon^2}\right),\\
 &\leqslant C\left(1 + \frac{\Lambda \rho}{c_\varepsilon \varepsilon} + \frac{\rho^2}{4\varepsilon^2}\right).
\end{align*}
Finally, we can conclude that $u_\rho = w_\rho - \frac{1}{\rho c_\varepsilon \varepsilon}v_\rho \in W^{1,p}(B_1)$ with the desired estimate
\[ \|\nabla u_\rho\|_{L^p(B_1)} \leqslant C_p\left( \frac{\rho^2}{\varepsilon^2}+1+\frac{\Lambda \rho}{c_\varepsilon \varepsilon}\right).\]
This concludes the proof of this Lemma.
