 The flow $(\mathbb{T}\times\Gamma\backslash G, S_\alpha)$, abbreviated as $({\rm X},S_\alpha)$, is shown to be distal. Assume further the conditions
 \begin{enumerate}[leftmargin=20mm]
 \item[(ii)] $\varphi = \eta$,
 \item[(iii)] $\varphi$ and hence $\eta$ have zero mean, i.e. $\int_0^1 \varphi(t)\,\textup{d} t=\int_0^1 \eta(t)\,\textup{d} t=0$.
 \end{enumerate} 
 Huang et al. showed that for rational $\alpha$, the M\"obius disjointness conjecture for $({\rm X}, S_\alpha)$ holds, and for irrational $\alpha$, 
 the flow $({\rm X},S_\alpha)$ has sub-polynomial measure complexity with respect to some natural metric and any measure in $M({\rm X}, S_\alpha)$. Consequently under the conditions (i)-(iii), the M\"obius disjointness conjecture for $({\rm X}, S_\alpha)$ holds for all $\alpha$. See Appendix~II and Theorem~1.1 of \cite{HLW}.

In \cite{HW}, keeping $\eta=\varphi$ but relaxing $\varphi (=\eta)$ and $\psi$ to be $C^{2+2\varepsilon}$- and $C^{1+\varepsilon}$-smooth, the polynomial rate of rigidity for $({\rm X},S_\alpha)$ was established, hence the M\"obius disjointness. This work 
 combines the ideas from Huang-Liu-Wang \cite{HLW}, Kanigowski-Lema\'{n}czyk-Radziwill \cite{KLR} and de Faveri \cite{Faveri}. 
 Ma and Wu \cite{MW} followed \cite{HLW} more and {\it relaxed the condition (ii)} but kept the smoothness assumption (i). In \cite[Theorem 1.1 and 1.2]{MW}, the M\"obius disjointness in the case of rational $\alpha$ was derived without the constraint $\eta=\varphi$ while the sub-polynomial measure complexity for irrational $\alpha$ can be established with the condition $\eta=k\varphi$ in place of (ii), where $k$ is a (fixed) nonzero real number.

In this paper our primary goal is to {\it remove the condition (ii)} with a relaxation of (i) for the M\"obius disjointness for $(\mathbb{T}\times\Gamma\backslash G, S_{\alpha})$. This is Theorem~\ref{thm} below, (the case of irrational $\alpha$) which is a consequence of Theorem~\ref{intd}, because by Proposition~\ref{prop2.1}, the polynomial rate of rigidity (PR rigidity) is a sufficient condition for the M\"obius disjointness. 
 In addition to the PR rigidity, we can show the sub-polynomial measure complexity without assuming condition (ii). 
 Precisely we get the following theorems.

\begin{theorem}\label{prop}
 With the same setting as in Theorem~\ref{intd}, but now assuming that $\varphi, \eta, \psi$ are $C^\infty$-smooth, the measure complexity of $(\mathbb{T}\times\Gamma\backslash G, S_\alpha, \rho)$ is sub-polynomial for any $\rho\in M(\mathbb{T}\times\Gamma\backslash G, S_\alpha)$ and irrational $\alpha$.
 \end{theorem}

\begin{remark}
 The Sarnak conjecture for $(\mathbb{T}\times\Gamma\backslash G, S_\alpha)$ for irrational $\alpha$ follows from both Theorems~\ref{intd} and \ref{prop} but under different conditions of smoothness. The required smoothness may have reached the argument's limit and the zero mean condition (iii) seems unavoidable in our applied methods. We also prove Theorem~\ref{prop}, although it implies the Sarnak conjecture under the stronger smoothness condition, because at present there is no evidence that the sub-polynomial measure complexity follows from the PR rigidity. 
 \end{remark}

We consider the family $\cF$ of Lipschitz continuous functions $g$ on ${\rm X}:= \T\times \Gamma \backslash G$. For any $\nu \in M({\rm X}, S)$ with $S=S_\alpha$, $n\in \N$ and $g\in \cF$, we have
 \begin{eqnarray*}
 \|g\circ S^n-g\|_{L^2(\nu)}^2 \ll_g \int_{\T\times \Gamma\backslash G} d\big( (t,\overline{g}), S^n((t,\overline{g})) \big)^2 \textup{d} \nu(t,\overline{g}).
 \end{eqnarray*}
 Suppose there exist $\varepsilon>\delta >0$ and an unbounded sequence $\{r_n\}_{n\ge 1}\subset \N$ for which 
 \begin{eqnarray}\label{A1}
 \int_{\T\times \Gamma\backslash G} d\big( (t,\overline{g}), S^{jr_n}((t,\overline{g})) \big)^2 \textup{d} \nu(t,\overline{g}) \ll_\varepsilon r_n^{-\varepsilon}, \qquad \forall \ |j|\le r_n^\delta.
 \end{eqnarray}
 Clearly \eqref{A1} implies \eqref{PRr} and the PR rigidity follows.

\subsection{Bounding the metric on $\mathbb{T}\times \Gamma \backslash G$}
 Using \eqref{eqd}, \eqref{Sn}, \eqref{eq3.1} and \eqref{eqdGammaG}, we have 
 \begin{eqnarray}\label{d}
 d\big( (t,\overline{g}), S^n((t,\overline{g})) \big)^2
 &=&\|n\alpha\|^2 + d_{\Gamma\backslash G} \left( \overline{g}, \overline{g}\begin{pmatrix}\begin{smallmatrix}
 1 & \Phi_n(t) & \langle \Psi_n(t) \rangle \\ & 1 & \xi_n(t) \\ & & 1 \end{smallmatrix}\end{pmatrix} \right)^2 \nonumber\\
 &\ll& \|n\alpha\|^2+ |\Phi_n(t)|^2 + |\xi_n(t)|^2 + \|\Omega_n(t)\|^2 + \|H_n(t)\|^2
 \end{eqnarray}
 as $|\langle \Psi_n(t)\rangle | = \|\Psi_n(t)\|$ and $\|\cdot \|$ is a norm. By \eqref{d}, we obtain
 \begin{eqnarray*}
 &&\int_{\T\times \Gamma\backslash G} d\big( (t,\overline{g}), S^n((t,\overline{g})) \big)^2 \textup{d} \nu(t,\overline{g})\nonumber\\
 &\ll& \|n\alpha\|^2+ \int_{\T\times \Gamma\backslash G} \big(|\Phi_n(t)|^2 + | \xi_n(t)|^2 + \|\Omega_n(t)\|^2 +\|H_n(t)\|^2 \big) \textup{d} {\nu}(t,\overline{g}).
 \end{eqnarray*}
 The pushforward measure $\pi_*\nu$ of the projection map $\pi(t,\overline{g})=t$ is a Borel probability measure on the torus $\T$. When $\alpha$ is irrational, this measure is rotational invariant and hence equal to the normalized Haar measure (which is also the Lebesgue measure) on $\T$. 
 Since the integrand depends only on $t$ (and not on $\overline{g}$), we obtain that
 \begin{eqnarray}\label{target1}
 && \int_{\T\times \Gamma\backslash G} d\big( (t,\overline{g}), S^n((t,\overline{g})) \big)^2 \textup{d} \nu(t,\overline{g})
 \le \|n\alpha\|^2+ I_\Phi(n) + I_\xi(n) + I_\Omega(n) + I_H(n),
 \end{eqnarray}
 where 
 \begin{eqnarray*}
 \ds I_\Phi(n) = \int_\T |\Phi_n(t)|^2 \textup{d}t, && 
 \ds I_\xi(n) = \int_\T |\xi_n(t)|^2 \textup{d}t,\\
 \ds I_\Omega(n) = \int_\T \|\Omega_n(t)\|^2 \textup{d}t, && 
 \ds I_H(n) = \int_\T \|H_n(t)\|^2 \textup{d}t.
 \end{eqnarray*}

In fact, now we have 
 \begin{eqnarray*}
 \varphi(t)= \widetilde{g}_\varphi\circ l_\alpha(t) - \widetilde{g}_\varphi(t),
 \qquad
 \eta(t)= \widetilde{g}_\eta\circ l_\alpha(t) - \widetilde{g}_\eta(t),
 \end{eqnarray*}
 for which $\widehat{\varphi}(0)=\widehat{\eta}(0)=0$ is applied. Set
 \begin{eqnarray*}
 \varpi(t):=\psi(t)+(\widetilde{g}_\varphi \eta)(t) -(\varphi(t)+\widetilde{g}_\varphi(t))\cdot \widetilde{g}_\eta\circ l_\alpha(t)+ (\widetilde{g}_\varphi \widetilde{g}_\eta)\circ l_\alpha(t) ,
 \end{eqnarray*}
 which is smooth and of period 1 as $\psi, \varphi, \widetilde{g}_\varphi, \widetilde{g}_\eta$ are smooth functions on $\R/\Z$. Then,
 \begin{eqnarray*}
 \varpi(t)=\widehat{\varpi}(0) + \widetilde{g}_\varpi\circ l_\alpha(t) - \widetilde{g}_\varpi(t)
 \end{eqnarray*}
 and the inverse of the map
 \begin{eqnarray*}
 \widetilde{R}: (t,\overline{g}) \mapsto
 \left(t,\overline{g} \begin{pmatrix}\begin{smallmatrix} 1 \, & \widetilde{g}_\varphi(t) & \\ & 1 & \widetilde{g}_\eta(t) \\ & & 1 \end{smallmatrix}\end{pmatrix} \begin{pmatrix}\begin{smallmatrix} 1 & \phantom{\widetilde{g}_\varphi(t)} & \widetilde{g}_\varpi(t) \\ & 1 & \phantom{\widetilde{g}_\varphi}\\ & & 1 \end{smallmatrix}\end{pmatrix}\right)
 \end{eqnarray*}
 sends $(t,\overline{g})$ to
 \begin{eqnarray*}
 \left(t,\overline{g} \begin{pmatrix}\begin{smallmatrix} 1 \, & -\widetilde{g}_\varphi(t) & \\ & 1 & -\widetilde{g}_\eta(t) \\ & & 1 \end{smallmatrix}\end{pmatrix} \begin{pmatrix}\begin{smallmatrix} 1 & \phantom{-\widetilde{g}_\varphi(t)}& \widetilde{g}_\varphi(t)\widetilde{g}_\eta(t)-\widetilde{g}_\varpi(t) \\ & 1 & \phantom{\widetilde{g}_\varphi}\\ & & 1 \end{smallmatrix}\end{pmatrix}\right).
 \end{eqnarray*}
 Thus, $\tilde{T}_1:=\widetilde{R}^{-1} S\widetilde{R} $ maps $(t,\overline{g})$ to
 \begin{eqnarray*}
 && \widetilde{R}^{-1} S \left(t,\overline{g} \begin{pmatrix}\begin{smallmatrix} 1 \, & \widetilde{g}_\varphi(t) & \\ & 1 & \widetilde{g}_\eta(t) \\ & & 1 \end{smallmatrix}\end{pmatrix} \begin{pmatrix}\begin{smallmatrix} 1 & \phantom{\widetilde{g}_\varphi(t)} & \widetilde{g}_\varpi(t) \\ & 1 & \phantom{\widetilde{g}_\varphi}\\ & & 1 \end{smallmatrix}\end{pmatrix}\right)\\
 &=& \widetilde{R}^{-1} \left(l_\alpha(t),\overline{g} \begin{pmatrix}\begin{smallmatrix} 1 \, & \varphi(t) +\widetilde{g}_\varphi(t) & \\ & 1 & \eta(t)+ \widetilde{g}_\eta(t) \\ & & 1 \end{smallmatrix}\end{pmatrix} \begin{pmatrix}\begin{smallmatrix} 1 & \phantom{\widetilde{g}_\varphi(t)} & \psi(t)+\widetilde{g}_\varphi(t) \eta(t)+ \widetilde{g}_\varpi(t) \\ & 1 & \phantom{\widetilde{g}_\varphi} \\ & & 1 \end{smallmatrix}\end{pmatrix}\right)\\
 &=&
 \left(l_\alpha(t) ,\overline{g}
 \begin{pmatrix}\begin{smallmatrix} 1 & \phantom{\widetilde{g}_\varphi(t)} & \varpi(t)- \big(\widetilde{g}_\varpi\circ l_\alpha(t)-\widetilde{g}_\varpi(t)\big) \\ & 1 & \\ & & 1 \end{smallmatrix}\end{pmatrix}\right)\\
 &=& \left(l_\alpha(t) ,\overline{g}
 \begin{pmatrix}\begin{smallmatrix} 
 1 & \phantom{\widetilde{g}_\varphi} & \widehat{\varpi}(0)
 \\ & 1 &
 \\ & & 1
 \end{smallmatrix}\end{pmatrix}
 \right),
 \end{eqnarray*}
 where $S=S_\alpha$.
 By Proposition~\ref{prop2.3}, the measure complexity of $(\mathbb{T}\times\Gamma\backslash G, S, \rho)$ is sub-polynomial, i.e. satisfying \eqref{sp}, if and only if the measure complexity of $(\mathbb{T}\times\Gamma\backslash G, \tilde{T}_1, v)$ with $v=\rho\circ \tilde{R}$ is sub-polynomial. From \S\S~\ref{ss3.2}, the metric $d$ is seen to be invariant under $\tilde{T}_1$, so for any $n\geq1$ and $\varepsilon>0$, 
 $$
 s_{n}(\mathbb{T}\times\Gamma\backslash G, \tilde{T}_1, d, v, \varepsilon)=s_{1}(\mathbb{T}\times\Gamma\backslash G, \tilde{T}_1, d, v, \varepsilon).
 $$
 Since $\mathbb{T}\times\Gamma\backslash G$ is compact, we have $s_{1}(\mathbb{T}\times\Gamma\backslash G, \tilde{T}_1, d, v, \varepsilon)<\infty$ and consequently
 $$
 \lim_{n\rightarrow\infty}\frac {s_{n}(\mathbb{T}\times\Gamma\backslash G, \tilde{T}_1, d, v, \varepsilon)}{n^\tau}=\lim_{n\rightarrow\infty}\frac {s_{1}(\mathbb{T}\times\Gamma\backslash G, \tilde{T}_1, d, v, \varepsilon)}{n^\tau}=0.
 $$
 Hence the measure complexity of $(\mathbb{T}\times\Gamma\backslash G, S, \rho)$ satisfies \eqref{sp} for finite $\#\cQ_B$ as well.

